  'Webhook URL' => '网络钩子 URL',
  '[[\'In the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.created, customer.subscription.updated, customer.subscription.deleted, invoice.paid and invoice.payment_failed, then save its signing secret above. An endpoint set up earlier for Flux Forms keeps working.\', \'en\']]' => '在 Stripe 仪表板中添加一个带有此 URL 的 Webhook 端点和事件 payment_intent.succeeded、 payment_intent. payment_failed、 payment_intent.canceled、 charge.refunded、 customer.subscription.created、 customer.subscription.updated、 customer.subscription.deleted、invoice.paid 和 invoice. payment_failed,然后保存上面的签名密钥。之前为 Flux Forms 设置的端点仍然有效。',
  '\\nPayment records\\n' => '付款记录',
