  '\\nThere is no open donation type yet.\\n' => '尚无开放的捐赠类型。',
  '\\nOnly for a free amount.\\n' => '仅限免费。',
  '\\nOne name per line, one per unit; this name goes on the certificate. Empty = the donor\\\'s name.\\n' => '每行一个名称,每个单元一个;这个名字出现在证书上。空 = 捐赠者姓名。',
  '\\nPhone or e-mail is required: the payment link goes there.\', \'en\']]' => '需要电话或电子邮件:那里有付款链接。',
