  '\\nAgreements\\n' => '协议',
  '\\nAgreed cost per type and option. The price valid on the day an item is sent is kept on the item. A partner whose agreements for a type are all switched off gets no new work for it.\\n' => '每种类型和选项的商定成本。商品上保留商品发送当天的有效价格。某个类型的协议全部关闭的合作伙伴无法获得新的工作。',
  'Price' => '价格',
  '\\nValid from\\n' => '有效期自',
