  'Open' => '打开',
  '[[\'%dwithout a price\', \'en\']]' . chr(0) . '[[\'%dwithout a price\', \'en\']]' => '%d无价格',
  '\\nRe-read prices from the agreements\\n' => '重新读取协议中的价格',
  '\\nDonations, donors and recurring gifts at a glance.\\n' => '捐款、捐助者和经常性礼物一目了然。',
