  '\\nTracking\\n' => '跟踪',
  '\\nExtra tabs\\n' => '额外选项卡',
  'System check' => '系统检查',
  '[[\'Settings sections\\n' => '设置部分',
  '\\nDefault currency\\n' => '默认货币',
  '\\nTurkish lira (₺)\\n' => '土耳其里拉 (₺)',
  '\\nEuro (€)\', \'en\']]' => '欧元 (€)',
  '\\nUS dollar ($)\\n' => '美元 ($)',
  '\\nPound sterling (£)\\n' => '英镑 (£)',
  '\\nDashboard totals are in this currency; gifts in other currencies are listed but not added to the totals.\\n' => '仪表板总计以该货币表示;其他货币的礼物会列出,但不会添加到总数中。',
  '\\nTracking module\\n' => '跟踪模块',
  '\\nChosen donation types get one item per unit with a code, sent to partners (with agreed prices and settlement), files and history. Leave it off if you do not need it.\\n' => '选定的捐赠类型每单位获得一件带有代码的物品,发送给合作伙伴(具有商定的价格和结算)、文件和历史记录。如果不需要,请将其关闭。',
  '[[\'A Reports screen with editable JSON reports (always on with the tracking module).\\n' => '带有可编辑 JSON 报告的报告屏幕(始终与跟踪模块一起打开)。',
  '[[\'Gifts on behalf of a person\\n' => '代表某人的礼物',
  '[[\'Adds a proxy (vekâlet) text the donor accepts, intentions and one item per unit with the name of the person it is given for. Turns tracking on too.\\n' => '添加捐赠者接受的代理 (vekâlet) 文本、意图以及每个单位的一个项目,其中包含捐赠者的姓名。也打开跟踪。',
  '\\nWhich payments are donations?\\n' => '哪些付款属于捐赠?',
  '\\nEvery payment taken through a Flux Forms form\\n' => '通过 Flux Forms 表格进行的每笔付款',
  '\\nOnly payments through the forms selected below (and forms linked to a donation type)\\n' => '仅通过下面选择的表格(以及链接到捐赠类型的表格)进行付款',
  'Save settings' => '保存设置',
  '\\nHow donations are recorded", \'tr\']]' => '如何记录捐款',
  '\\nA donation is stored when a Flux Forms payment is completed: at the final form submission (with name, phone and e-mail from the form), from the payment provider\\\'s notifications (refunds, renewals of recurring gifts) and by an hourly check that catches payments whose form was not submitted.\\n' => '当 Flux Forms 付款完成时,捐款将被存储:最终表单提交时(包含表单中的姓名、电话和电子邮件)、支付提供商的通知(退款、经常性礼物的续订)以及每小时检查未提交表单的付款。',
  '\\nDonors are matched on phone number or e-mail address, never on name alone.\\n' => '捐赠者通过电话号码或电子邮件地址进行匹配,而不仅仅是姓名。',
  '\\nShown on receipts, donation pages and in exports. Empty fields fall back to the site name, the theme logo and the theme colours.\\n' => '显示在收据、捐赠页面和导出中。空字段会回退到站点名称、主题徽标和主题颜色。',
  '\\nOrganisation name\\n' => '组织名称',
  'Logo' => '标志',
  '\\nChoose a logo\\n' => '选择徽标',
  'Choose logo' => '选择标志',
  '[[\'brand color\\n' => '品牌颜色',
  '\\nHex color such as #1F2937. Empty = the theme\'s primary colour.\\n' => '十六进制颜色,例如#1F2937。空 = 主题的原色。',
  '\\nReceipt text\\n' => '收据文本',
  '\\nA thank-you note printed on the donation receipt.\\n' => '捐款收据上印有感谢信。',
  '\\nFooter text\\n' => '页脚文本',
  '\\nAddress, registration number, bank details and similar; printed at the bottom of receipts.\', \'en\']]' => '地址、注册号、银行详细信息及类似信息;打印在收据底部。',
  '\\nDonation type categories\\n' => '捐赠类型类别',
  '\\nGroup donation types, e.g. Sacrifice, Ramadan, General. The key is stored on the types; a category that is in use cannot be removed.\\n' => '团体捐赠类型,例如牺牲,斋月,将军。密钥存储在类型上;无法删除正在使用的类别。',
  'Add category' => '添加类别',
  '[[\'Save categories\\n' => '保存类别',
  '[[\'Used by%stype\', \'en\']]' . chr(0) . '[[\'Used by%stypes\', \'en\']]' => '由%s类型使用',
  '\\nRemove category\\n' => '删除类别',
  '\\nThe words on the tracking screens. A donation type can use its own words (Donation types › Tracking); empty fields use these, and empty ones here the built-in words.\\n' => '跟踪屏幕上的文字。捐赠类型可以使用自己的词语(捐赠类型 › 跟踪);空字段使用这些,空字段使用内置单词。',
  '\\nEarly days\\n' => '早期',
  '\\nHow many days before the target date an item may already be done. After the target day it is still allowed, but shown as late.\\n' => '在目标日期之前多少天某个项目可能已经完成。在目标日期之后,仍然允许,但显示为迟到。',
  '\\nProxy (vekâlet) text\\n' => '代理 (vekâlet) 文本',
  '\\nThe text a donor accepts to authorise the organisation to give on their behalf. Every change is saved as a new version; each donation keeps the version that was accepted.\\n' => 'The text a donor accepts to authorise the organisation to give on their behalf.每次更改都会保存为新版本;每次捐赠都会保留已接受的版本。',
  '\\nWho items are sent to, their agreed prices and payments are kept under Donations › Partners.\\n' => '物品发送给谁,其商定的价格和付款保存在捐赠 › 合作伙伴下。',
  '\\nProxy text versions\\n' => '代理文本版本',
  '\\nNo text yet. Donations of types that require a proxy cannot be paid until a text is saved.\\n' => '还没有文字。在保存文本之前,无法支付需要代理的类型的捐赠。',
  '\\nVersion%1$s·%2$s\\n' => '版本%1$s·%2$s',
  '\\nAdd your own tabs with fields to tracked records ("on": "item") or donations ("on": "donation"), for all or some donation types. Leave it empty if you do not need any.\\n' => '为所有或某些捐赠类型添加您自己的带有字段的选项卡,以跟踪记录(“on”:“item”)或捐赠(“on”:“donation”)。如果不需要,请将其留空。',
  '\\nTabs (JSON list)\\n' => '选项卡(JSON 列表)',
  '\\nTabs in use\\n' => '正在使用的选项卡',
  'Donation page' => '捐款页面',
  '\\nRecord page\\n' => '记录页面',
  '[[\'%dfield\', \'en\']]' . chr(0) . '[[\'%dfields\', \'en\']]' => '%d字段',
  '\\nfrom a plugin\\n' => '来自插件',
  '\\nNo extra tabs yet.\\n' => '还没有额外的选项卡。',
  'Example' => '示例',
  '\\nReads completed payments stored by Flux Forms and adds the missing ones as donations. Safe to run more than once: a payment is never imported twice.\\n' => '读取 Flux Forms 存储的已完成付款,并将缺失的付款添加为捐款。可以安全运行多次:付款绝不会导入两次。',
  '\\nFlux Forms\\\'s payment table was not found. Is Flux Forms installed?\\n' => '未找到 Flux Forms 的付款表。是否安装了 Flux Forms?',
  '\\nImporting...\\n' => '正在导入...',
  '\\nImport now\\n' => '立即导入',
  '\\nLast run%1$s:%2$spayments checked,%3$simported.\\n' => '上次运行%1$s:检查%2$s付款,导入%3$s。',
  'Closed' => '已关闭',
  'Archived' => '已存档',
  '\\nUpcoming (%s)\\n' => '即将推出 (%s)',
  'Ended' => '结束',
  '\\nNew donation type\\n' => '新的捐赠类型',
  '\\nDonation types and campaigns\\n' => '捐赠类型和活动',
  '\\nWhat people can give for: each type has its own prices and options, dates, goal and linked forms.\\n' => '人们可以付出什么:每种类型都有自己的价格和选项、日期、目标和链接表格。',
  '\\nOpen and closed\\n' => '打开和关闭',
  'Archive' => '存档',
  '\\nThe archive is empty\\n' => '存档为空',
  '\\nNo donation types yet\\n' => '尚无捐赠类型',
  '\\nCreate a type such as a general donation, a sapling or a kurban share, set its prices, and link the forms that collect for it.\\n' => '创建一个类型,例如一般捐赠、树苗或库尔班份额,设置其价格,并链接为其收集的表格。',
  'Order' => '订单',
  'Prices' => '价格',
  'Progress' => '进展',
  'Dates' => '枣子',
  'Forms' => '表格',
  'Move up' => '向上移动',
  'Move down' => '下移',
  '\\nNo category\\n' => '没有类别',
  '\\n(inactive)\\n' => '(无效)',
  '\\n(price not set)\\n' => '(价格未定)',
  '\\nfree amount (min.%s)\\n' => '免费金额(最少%s)',
  '\\nfree amount\\n' => '免费金额',
  '[[\'quantity\\n' => '数量',
  '\\nrecurring\\n' => '重复',
  '\\n%1$sof%2$s(%3$s%%)\\n' => '%1$s或%2$s(%3$s%%)',
  '\\nOpen-ended\\n' => '开放式',
  'Edit' => '编辑',
  '\\nLoad sample types\\n' => '加载样本类型',
  '\\nAdds ready-made types and categories that you can edit. Types whose sample price is 0 start closed until you set their prices.\\n' => '添加您可以编辑的现成类型和类别。样本价格为 0 的类型开始关闭,直到您设置其价格。',
  '\\nSample set\\n' => '样本集',
  'Load' => '负载',
  '\\nDonation type not found\', \'en\']]' => '未找到捐赠类型',
  '\\nEdit donation type\\n' => '编辑捐赠类型',
  'Basics' => '基础知识',
  'Title' => '标题',
  'Category' => '类别',
  '\\nEdit categories\\n' => '编辑类别',
  '\\nSlug\\n' => '子弹',
  '\\nOptional; created from the title.\\n' => '可选;根据标题创建。',
  '\\nPrices and the goal are in this currency. A linked form must charge in the same currency, otherwise its payments are stopped.\\n' => '价格和目标均以该货币表示。链接的表单必须以相同的货币收费,否则其付款将停止。',
  'Short description' => '简短描述',
  'Automatic' => '自动',
  'Heart' => '心',
  'Gift' => '礼物',
  '\\nSheep\\n' => '羊',
  'Cattle' => '牛',
  '\\nCamel\\n' => '骆驼',
  '\\nCard subtitle", \'en\']]' => '卡片副标题',
  '\\nOne short line under the title on the type cards, e.g. "Sheep or goat".\', \'en\']]' => '类型卡标题下有一条短线,例如“绵羊或山羊”。',
  'Icon' => '图标',
  '\\nShown when the type has no image.\\n' => '当类型没有图像时显示。',
  'Image' => '图片',
  '\\nChoose an image\\n' => '选择图像',
  'Choose image' => '选择图片',
  '\\nPrices and options\\n' => '价格和选项',
  '\\nOne option is a fixed price per unit (e.g. one sapling). Several options give the donor a choice (e.g. adak, akika, şifa). The amount charged is always computed on the server from these prices.\\n' => '一个选项是每单位的固定价格(例如一棵树苗)。捐赠者有多种选择(例如adak、akika、şifa)。收费金额始终根据这些价格在服务器上计算。',
  '\\nA price of 0 means the price is not announced yet: the option is shown but cannot be paid. An inactive option is hidden and cannot be paid.\\n' => '价格为 0 表示价格尚未公布:选项已显示但无法支付。不活动的选项被隐藏并且无法支付。',
  'Add option' => '添加选项',
  '[[\'Free amount allowed\\n' => '允许免费金额',
  '\\nMinimum amount\\n' => '最低金额',
  '\\nQuantity allowed\\n' => '允许数量',
  '\\nMaximum quantity\\n' => '最大数量',
  '\\nEmpty = no limit.\\n' => '空 = 无限制。',
  '[["Recurring giving allowed\\n' => '[[“允许重复捐赠',
  '\\nLinked forms\\n' => '链接表单',
  '\\nGifts through these Flux Forms forms count for this type. Map each priced choice of the form to an option: the form then charges the price set here.\\n' => '通过这些 Flux Forms 形式提供的礼物属于此类型。将表单的每个定价选择映射到一个选项:然后表单按此处设置的价格收费。',
  '\\nNo payment form found in Flux Forms yet.\\n' => '尚未在 Flux Forms 中找到付款表单。',
  '\\nalso linked to:%s\\n' => '还链接到:%s',
  '\\nSave after choosing a form to map its choices.\\n' => '选择表单后保存以映射其选择。',
  '\\nHide the choice in the form when it was preselected\\n' => '预选时隐藏表单中的选项',
  '\\nWhen the page passes a choice (flxb_opt in the address or FLXB.preselect()), the form shows a short summary with a "Change" link instead of the choice list.\\n' => '当页面传递选择(地址中的 flxb_opt 或 FLXB.preselect())时,表单会显示带有“更改”链接的简短摘要,而不是选择列表。',
  'Publishing' => '出版',
  '\\nA closed type keeps its history but its forms no longer take payments.\\n' => '封闭类型保留其历史记录,但其表单不再接受付款。',
  'Start date' => '开始日期',
  '\\nEnd date\\n' => '结束日期',
  '\\nGoal amount\\n' => '目标金额',
  '\\nOptional. Shown as a progress bar.\\n' => '可选。显示为进度条。',
  '\\nShow it on the site\\n' => '在网站上显示',
  '\\nAdd baslik="hayir" to hide the title and description.\\n' => '添加 baslik="hayir" 以隐藏标题和说明。',
  '\\nDelete this donation type\\n' => '删除此捐赠类型',
  '\\nDelete this donation type?\\n' => '删除此捐赠类型吗?',
  '\\nThis type has gifts, so it can be archived but not deleted.\\n' => '此类型有礼物,因此可以存档但不能删除。',
  '\\nOption name\\n' => '选项名称',
  '\\ne.g. Sapling, Adak, Iftar\\n' => 'e.g.树苗、埃达克、开斋',
  '\\nfrom the name\\n' => '从名字来看',
  '\\nRemove option\\n' => '删除选项',
  'Unit' => '单位',
  '\\n— note set\\n' => '— 注释集',
  '\\nUnits per choice\\n' => '每个选择的单位',
  '\\ne.g. a whole animal = 7 shares\\n' => 'e.g.一整只动物 = 7 份',
  'Badge' => '徽章',
  '\\nnot offered\', \'en\']]' => '未提供',
  '\\nTranslations\\n' => '翻译',
  '\\nShown on the donation page, the cart and the checkout in that language (Flux Lang). Empty fields use the texts above. Records keep the texts above. Save once after adding options to translate their names.\\n' => '以该语言 (Flux Lang) 显示在捐赠页面、购物车和结帐处。空字段使用上面的文本。记录保留上述文字。添加翻译名称的选项后保存一次。',
  '\\nOption:%s\\n' => '选项:%s',
  '\\nEach unit of a gift becomes its own item with a 7-digit code: approved, sent to a partner, completed, delivered to the owner, with files and history.\\n' => '礼物的每个单元都成为带有 7 位数代码的自己的物品:批准、发送给合作伙伴、完成、交付给所有者,并带有文件和历史记录。',
  '\\nTrack every unit one by one\\n' => '一一跟踪每个单元',
  '\\nAlways on for gifts given on behalf of a person.\\n' => '代表某人赠送礼物时始终打开。',
  '\\nThe first file marks it completed\\n' => '第一个文件将其标记为已完成',
  '\\nWords for this type\', \'en\']]' => '此类型的单词',
  '\\nOn behalf of a person\\n' => '代表某人',
  '\\nFor types given on behalf of a named person: each unit becomes its own item with that person\\\'s name, and the donor must accept the proxy (vekâlet) text.\\n' => '对于代表指定人物给出的类型:每个单位都成为带有该人姓名的自己的项目,并且捐赠者必须接受代理 (vekâlet) 文本。',
  '\\nProxy (vekâlet) required\\n' => '需要代理 (vekâlet)',
  '\\nAnimal\\n' => '动物',
  '\\nCattle (7 shares)\\n' => '牛(7股)',
  '\\nAll of the meat goes to people in need\\n' => '所有的肉都送给有需要的人',
  '\\nMapping for “%s”\\n' => '映射“%s”',
  '\\nThis form charges in%1$sbut the donation type is in%2$s: its payments are stopped until both use the same currency.\\n' => '此表单以%1$s收费,但捐赠类型为%2$s:其付款将停止,直到两者使用相同的货币。',
  '\\nThis form has no priced choices to map.\\n' => '此表单没有可供映射的价格选择。',
  '\\nForm choice\\n' => '表单选择',
  '\\nUnits\\n' => '单位',
  '\\nform price:%s\\n' => '表格价格:%s',
  '\\nNot mapped (form price)\\n' => '未映射(形成价格)',
  '\\nQuantity field\\n' => '数量字段',
  '\\nFree amount field\\n' => '免费金额字段',
  '\\nOn behalf of (names field)\\n' => '代表(名称字段)',
  '\\nOne name per line. Units without a name are given on behalf of the donor.\\n' => '每行一个名称。没有名字的单位是代表捐赠者提供的。',
  '\\nProxy consent field\\n' => '代理同意字段',
  '\\nMonthly, weekly or yearly gifts charged automatically by the payment provider.\\n' => '支付提供商自动收取每月、每周或每年的礼物费用。',
  '\\nName, e-mail, phone, reference...\\n' => '姓名、电子邮件、电话、参考...',
  '\\nNo recurring donations yet\\n' => '尚无经常性捐款',
  '\\nA recurring donation is created when a payment form is set to charge every day, week, month or year.\\n' => '当付款表单设置为每天、每周、每月或每年收费时,就会创建定期捐款。',
  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => '%s经常性捐款',
  '\\nInterval\\n' => '间隔',
  'Started' => '开始',
  '\\nNext charge\\n' => '下次充电',
  '\\nAttempt%1$sof%2$sfailed:%3$s\\n' => '尝试%1$s或%2$s失败:%3$s',
  '\\ncanceled%s\\n' => '已取消%s',
  '\\nCancel this recurring donation at the payment provider? No further charges will be made.\\n' => '在支付提供商处取消此定期捐赠吗?不会再收取任何费用。',
  'WooCommerce' => 'WooCommerce',
  '\\nCard payments: the official iyzico plugin is enabled.\\n' => '刷卡支付:已启用官方 iyzico 插件。',
  '\\nCard payments: Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => '卡支付:Flux Donate iyzico(未启用官方 iyzico 插件)。',
  '\\nCard payments:%s.\\n' => '卡付款:%s。',
  '\\nNo card method is enabled (WooCommerce › Settings › Payments).\\n' => '未启用银行卡方式(WooCommerce › 设置 › 付款)。',
  '\\nMonthly donations: Flux Donate iyzico is ready.\\n' => '每月捐赠:Flux Donate iyzico 已准备就绪。',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" and enter iyzico keys.\\n' => '每月捐赠已关闭:启用“卡 (iyzico) - Flux 捐赠”并输入 iyzico 密钥。',
  '\\nBank transfer (donations) is enabled.\', \'en\']]' => '银行转账(捐赠)已启用。',
  '\\nBank transfer (donations) is disabled.\\n' => '银行转账(捐赠)已禁用。',
  '\\nFlux Certificates is connected.\\n' => 'Flux 证书已连接。',
  '\\nFlux Certificates is active but has no active template.\\n' => 'Flux 证书处于活动状态,但没有活动模板。',
  '\\nFlux Certificates is not active: no certificate is made after payment.\\n' => 'Flux 证书未激活:付款后未颁发证书。',
  '\\nDonation page:\\n' => '捐赠页面:',
  '\\nThe donation options are not on a page yet.\\n' => '页面上还没有捐赠选项。',
  '\\nWooCommerce is not active. Donations are paid through WooCommerce from version 2.0: install and activate WooCommerce.\\n' => 'WooCommerce 未激活。从 2.0 版开始,捐款通过 WooCommerce 支付:安装并激活 WooCommerce。',
  '\\nSapling packages, prices and badges are edited on the donation type (Donations › Donation types). Which types give a certificate is set there too.\\n' => '树苗包、价格和徽章是根据捐赠类型(捐赠 › 捐赠类型)编辑的。哪些类型提供证书也在那里设置。',
  'Template' => '模板',
  '[[\'Automatic ("Fidan Bağış Sertifikası")\\n' => '自动(“Fidan Bağış Sertifikası”)',
  'Event' => '活动',
  '\\nWhen chosen, online donation certificates count for this open event.\\n' => '选择后,在线捐赠证书将计入此公开活动。',
  '\\nSend by\\n' => '发送者',
  '\\nWhen the payment is confirmed the certificate link goes out on these channels. With a WhatsApp route no SMS is sent.\\n' => '付款确认后,证书链接将在这些渠道上消失。通过 WhatsApp 路由,不会发送短信。',
  '\\n"Online + printed certificate"\\n' => '“在线+打印证书”',
  '\\nShown as "Coming soon" (cannot be chosen)\\n' => '显示为“即将推出”(无法选择)',
  '\\nCan be chosen\\n' => '可以选择',
  'Hidden' => '隐藏',
  '\\nPrinted certificate fee (per line)\\n' => '打印证书费用(每行)',
  '\\n0 = free. Orders with a printed certificate stay "Processing"; set them to "Completed" when sent.\\n' => '0 = 免费。带有打印证书的订单仍处于“处理中”状态;发送时将其设置为“已完成”。',
  '\\nComplete paid orders with an online certificate automatically\\n' => '自动使用在线证书完成支付订单',
  '\\nIBAN, recipient and reference code: WooCommerce › Settings › Payments › Bank transfer (donations). The transfer details and the receipt link are added to WooCommerce\\\'s "on hold" e-mail.\\n' => 'IBAN、收件人和参考代码:WooCommerce › 设置 › 付款 › 银行转账(捐赠)。转账详细信息和收据链接将添加到 WooCommerce 的“暂停”电子邮件中。',
  '\\nShort notification\\n' => '简短通知',
  '\\nA short message to the donor\\\'s phone when a transfer is registered (through Flux Mail, or Flux Certificates\\\'s providers). With both ticked, SMS only goes out when there is no WhatsApp route.\\n' => '注册转账时(通过 Flux Mail 或 Flux 证书提供商)向捐赠者的手机发送一条短信。勾选两者后,只有在没有 WhatsApp 路由时才会发出短信。',
  '\\nWhatsApp text\\n' => 'WhatsApp 文本',
  '\\nPlaceholders:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}\\n' => '占位符:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}',
  '\\nSMS text\\n' => '短信',
  '\\nLargest receipt file (MB)\\n' => '最大收据文件 (MB)',
  '\\nTell this address when a receipt is uploaded\\n' => '上传收据时告知此地址',
  'Cart and checkout' => '购物车和结帐',
  '\\nAfter "Donate"\\n' => '“捐赠”之后',
  '\\nGo straight to the checkout\\n' => '直接去结账',
  '\\nGo to the cart\\n' => '转到购物车',
  '\\nStay on the page\\n' => '留在页面上',
  '\\nCurrencies donors can choose\\n' => '货币捐赠者可以选择',
  '\\n(store currency)\\n' => '(存储货币)',
  '\\nWith more than one, donors pick the currency (shortcode [flx_bagis_para_birimi] or the theme). There are no exchange rates: set each option\\\'s price per currency on the donation type; options without a price in a currency are not offered in it. Check that your payment methods take these currencies.\', \'en\']]' => '如果有不止一种货币,捐赠者可以选择货币(简码 [flx_bagis_para_birimi] 或主题)。没有汇率:在捐赠类型上设置每个选项的每种货币的价格;其中不提供没有货币价格的期权。检查您的付款方式是否支持这些货币。',
  '\\nDo not ask for an address at the checkout when the cart holds only donations\\n' => '当购物车仅装有捐款时,请勿在结帐时询问地址',
  '\\nSupport WhatsApp number\\n' => '支持 WhatsApp 号码',
  '\\nShown at the checkout and with the bank transfer details as "Any trouble? Write to us on WhatsApp". Leave empty to hide.\\n' => '结账时显示,银行转账详细信息显示为“有任何问题吗?通过 WhatsApp 给我们写信”。留空以隐藏。',
  '\\n— Choose —\\n' => '— 选择—',
  '\\n"Donate" links and the hidden product pages go here.\\n' => '“捐赠”链接和隐藏的产品页面位于此处。',
  '\\nCard payment method\\n' => '银行卡付款方式',
  '\\nAutomatic: another virtual POS if one is enabled (e.g. EsnekPOS), otherwise iyzico\\n' => '自动:另一个虚拟 POS(如果已启用)(例如 EsnekPOS),否则为 iyzico',
  '\\niyzico\\n' => 'iyzico',
  '\\nShow every enabled card method\', \'en\']]' => '显示每个启用的卡方法',
  '\\nDonors see one card method; now:%s. Monthly donations always use Flux Donate iyzico (it stores the card). Bank transfer is always shown.\\n' => '捐助者见一卡法;现在:%s。每月捐款始终使用 Flux Donate iyzico(它存储卡)。始终显示银行转帐。',
  '\\nall\\n' => '全部',
  '\\nShow other payment plugins on the checkout block\\n' => '在结账栏显示其他支付插件',
  '\\nVirtual POS plugins that take the card on their own page but have no checkout block support (for example EsnekPOS) are added to the Checkout block. Plugins with their own card fields need the classic checkout.\\n' => '在自己的页面上使用卡但不支持结帐块的虚拟 POS 插件(例如 EsnekPOS)将添加到结帐块中。具有自己的卡字段的插件需要经典的结帐。',
  '\\nFlux Forms payment forms continue on the WooCommerce checkout\\n' => 'Flux Forms 付款表格在 WooCommerce 结帐时继续',
  '\\nThe donor picks card or bank transfer there; the form entry, the certificate automation and the donation record are completed when the order is paid.\\n' => '捐赠者在那里领取卡或银行转账;订单支付时,表单录入、证书自动化和捐赠记录完成。',
  '\\nCard payment screen\\n' => '卡支付屏幕',
  '\\nOur own card fields on the checkout (3D Secure, installments, saved cards)\\n' => '结帐时我们自己的卡字段(3D Secure、分期付款、保存的卡)',
  '\\niyzico payment page (as before)\\n' => 'iyzico 付款页面(和以前一样)',
  '\\nOfficial iyzico plugin for one-time donations\\n' => '用于一次性捐赠的官方 iyzico 插件',
  '\\nCard numbers go straight to iyzico and are never stored on this site. Monthly donations always use Flux Donate iyzico (it stores the card).\\n' => '卡号直接进入 iyzico,并且绝不会存储在该网站上。每月捐款始终使用 Flux Donate iyzico(它存储卡)。',
  '\\nMost installments\\n' => '大部分分期付款',
  '[["Single payment only\\n' => '[[“仅限单次付款',
  '[[\'With our own card fields. The options and any interest come from iyzico for each card.\\n' => '用我们自己的卡字段。每张卡的选项和任何利息均来自 iyzico。',
  '\\nAdd the "Donation options" block to any page, or create a ready page:\\n' => '将“捐赠选项”块添加到任何页面,或创建一个就绪页面:',
  '\\nCreate the online donation page\\n' => '创建在线捐赠页面',
  '\\nProduct list (XML)\\n' => '产品列表 (XML)',
  '\\nFor iyzico "upload your products with XML" and Google Merchant Center. Every fixed-price option on sale is one product; free amounts are left out. Updating daily is enough.\\n' => '对于 iyzico“使用 XML 上传您的产品”和 Google Merchant Center。销售的每个固定价格选项都是一种产品;免费金额被忽略。每天更新就足够了。',
  'Address' => '地址',
  '\\nShortcode and block\\n' => '短代码和块',
  '\\nWithout attributes it shows the donation types marked "Show in the Donation options block". tur="slug1,slug2" shows only those types; sekme="slug" opens that type\\\'s tab first. In the editor: "Donation options" block.\\n' => '如果没有属性,它会显示标记为“在捐赠选项块中显示”的捐赠类型。 tur="slug1,slug2" 仅显示这些类型; sekme="slug" 首先打开该类型的选项卡。在编辑器中:“捐赠选项”块。',
  'Online donation' => '网上捐款',
  '\\nChoose a sapling package or give any amount you like. You can pay by card or bank transfer; a certificate is made in your name.\\n' => '选择一个树苗包或提供任何您喜欢的数量。您可以通过银行卡或银行转账方式支付;证书将以您的名义制作。',
  '\\nOnline donation page\\n' => '在线捐款页面',
  '\\nHow this type appears in the "Donation options" block and the WooCommerce cart. Its hidden WooCommerce product is kept in step automatically.\\n' => '此类型如何显示在“捐赠选项”块和 WooCommerce 购物车中。其隐藏的 WooCommerce 产品会自动保持同步。',
  '[[\'Show in the "Donation options" block (donation page) and the product XML\\n' => '在“捐赠选项”块(捐赠页面)和产品 XML 中显示',
  '\\nGive a certificate (Flux Certificates)\\n' => '提供证书(Flux 证书)',
  'Certificate template' => '证书模板',
  '\\nSame as the WooCommerce settings\\n' => '与 WooCommerce 设置相同',
  '\\nOption with a − / + quantity\\n' => '带有 - / + 数量的选项',
  '\\nThis option\\\'s card gets − / + buttons (e.g. "1 sapling"); price = number × this option\\\'s price, checked again on the server. The other options stay fixed packages. Use "Maximum quantity" above for the limit.\\n' => '此选项的卡片有 - / + 按钮(例如“1 棵树苗”);价格=数量×该选项的价格,在服务器上再次检查。其他选项保持固定套餐。使用上面的“最大数量”作为限制。',
  '\\nPreset amounts (free amount)\\n' => '预设金额(免费金额)',
  '\\nSeparated by spaces, e.g. 250 500 1000.\\n' => '用空格分隔,例如250 500 1000。',
  '\\nPreset amounts in%s\\n' => '%s中的预设金额',
  '\\nPage address\\n' => '页面地址',
  '\\nOptional: where its product page and the product XML link go. Empty = the donation page in the WooCommerce settings.\\n' => '可选:产品页面和产品 XML 链接所在的位置。空 = WooCommerce 设置中的捐赠页面。',
  '\\nWooCommerce product #%d(hidden from the shop).\\n' => 'WooCommerce 产品 #%d(在商店中隐藏)。',
  '\\nThis order has no donation line.\\n' => '此订单没有捐赠热线。',
  '\\nDonation records:\\n' => '捐赠记录:',
  '\\nReference code:\\n' => '参考代码:',
  '\\nMake the certificate\\n' => '制作证书',
  '\\nRefund this amount to the donor\'s card?\\n' => '将此金额退还到捐赠者的卡上吗?',
  '\\nRecord this refund? The money is not sent back automatically for this payment method.\\n' => '记录这笔退款吗?对于此付款方式,资金不会自动退回。',
  '\\nRecord refund\\n' => '记录退款',
  '\\nRefunded through WooCommerce and the payment method; the record follows.\\n' => '通过 WooCommerce 和付款方式退款;记录如下。',
  '\\nRecorded in WooCommerce only: send the money back yourself (e.g. by bank transfer).\\n' => '仅在 WooCommerce 中记录:自行将钱汇回(例如通过银行转帐)。',
  'Order not found.' => '未找到订单。',
  '\\nOrder line not found.\\n' => '未找到订单行。',
  '\\nEnter an amount up to what is left to refund.\\n' => '输入剩余退款金额。',
  '\\nRefunded from Flux Donate by%s\\n' => '从%s的 Flux 捐赠中退还',
  '\\nNo donation lines.\\n' => '没有捐赠热线。',
  '\\nUnknown donation type.\\n' => '未知的捐赠类型。',
  '\\nThe donation product could not be created.\\n' => '无法创建捐赠产品。',
  'Enter an amount.' => '输入金额。',
  '\\nRecorded in Flux Chat (donation #%d).\\n' => '记录在 Flux 聊天中(捐赠 #%d)。',
  '\\nCanceled in Flux Donate.\\n' => '在通量捐赠中取消。',
  '\\nPut on hold in Flux Donate.\\n' => '暂停通量捐赠。',
  '\\nMarked as failed in Flux Donate.\\n' => '在 Flux Donate 中标记为失败。',
  '\\nThis payment link has expired. Please fill in the form again.\\n' => '此付款链接已过期。请重新填写表格。',
  '\\nFlux Forms entry%scompleted by this payment.\\n' => '本次付款已完成通量表格条目%s。',
  '\\nAfter you place the order you will see the IBAN and your own reference code. Once you have paid you can upload the receipt on the site; your certificate is sent when the payment is confirmed.\\n' => '下订单后,您将看到 IBAN 和您自己的参考代码。付款后,您可以在网站上上传收据;确认付款后将发送您的证书。',
  'Recipient' => '收件人',
  'Bank' => '银行',
  'Reference' => '参考',
  '\\nYour pre-registration is in\\n' => '您的预注册时间为',
  '\\nTo complete your donation, make a bank transfer to the account below. Please write your own reference code in the description.\\n' => '要完成捐赠,请通过银行转帐至以下帐户。请在描述中写下您自己的参考代码。',
  'Make the bank transfer' => '进行银行转帐',
  '\\nThe reference code lets us match your payment to your donation.\\n' => '参考代码让我们能够将您的付款与您的捐款进行匹配。',
  'Upload your receipt' => '上传您的收据',
  '[[\'Receive your certificate\\n' => '收到您的证书',
  '\\nOnce the payment is confirmed your certificate is sent by WhatsApp and e-mail; it also appears under My account › Orders.\\n' => '付款确认后,您的证书将通过 WhatsApp 和电子邮件发送;它还显示在我的帐户 › 订单下。',
  '\\nWe confirm your donation\\n' => '我们确认您的捐赠',
  '\\nOnce the payment is confirmed the order is completed and you get an e-mail; it also appears under My account › Orders.\\n' => '付款确认后,订单完成,您会收到一封电子邮件;它还显示在我的帐户 › 订单下。',
  '\\nMy pending donations\\n' => '我的待处理捐款',
  'Bank transfer details' => '银行转账详情',
  'After paying, upload your receipt:' => '付款后,上传收据:',
  'Please write the reference above in the transfer description. After paying, upload your receipt:' => '请在转账说明中填写上述参考信息。付款后,上传收据:',
  'Upload receipt' => '上传收据',
  '\\nCard number\\n' => '卡号',
  '\\nName on the card\\n' => '卡上的姓名',
  '\\nExpiry (MM/YY)\\n' => '到期 (MM/YY)',
  'context_def6e4575e04\\nMM/YY\\n' => '月/年',
  '\\nCVC\\n' => 'CVC',
  '\\nSave my card for next time\\n' => '保存我的卡以供下次使用',
  '\\niyzico keeps the card; this site never stores card numbers.\\n' => 'iyzico 保留该卡;此站点从不存储卡号。',
  '\\nFor the monthly donation iyzico keeps your card and charges it once a month. You can cancel at any time.\\n' => '对于每月捐款,iyzico 会保留您的卡并每月收取一次费用。您可以随时取消。',
  '\\nUse another card\\n' => '使用另一张卡',
  '\\nYour saved cards\\n' => '您保存的卡片',
  '\\nInstallments\\n' => '分期付款',
  '\\nSingle payment\', \'en\']]' => '单笔支付\', \'zh\']]',
  '\\n%1$sinstallments ×%2$s(total%3$s)\\n' => '%1$s分期付款 ×%2$s(总计%3$s)',
  '\\nInstallment options appear after the card number.\\n' => '分期付款选项出现在卡号后面。',
  '\\nPlease check the card number.\\n' => '请检查卡号。',
  '\\nPlease write the name on the card.\\n' => '请把名字写在卡上。',
  '\\nPlease check the expiry date.\\n' => '请检查到期日期。',
  '\\nPlease check the security code (CVC).\\n' => '请检查安全代码 (CVC)。',
  '[[\'Paid with 3D Secure through iyzico. Your bank may send you a code.\\n' => '通过 iyzico 使用 3D Secure 付款。您的银行可能会向您发送一个代码。',
  '\\nTest mode: use an iyzico test card, e.g. 5528 7900 0000 0008, 12/30, 123.\', \'en\']]' => '测试模式:使用 iyzico 测试卡,例如5528 7900 0000 0008, 12/30, 123.',
  '\\nFill in the test card\', \'en\']]' => '填写测试卡',
  '\\nTest mode accepts only iyzico test cards. Use "Fill in the test card".\\n' => '测试模式仅接受 iyzico 测试卡。使用“填写测试卡”。',
  '\\nCard payments are not configured on this site. Please choose another payment method.\\n' => '此网站未配置卡付款。请选择其他付款方式。',
  '\\nThe amount must be greater than zero.\\n' => '金额必须大于零。',
  '\\nThis saved card cannot be used any more. Please enter the card.\\n' => '这张保存的卡不能再使用。请输入卡。',
  '\\nThis installment option is not available for the card. Please choose another.\\n' => '此分期付款选项不适用于该卡。请选择另一个。',
  '\\nCard payment could not start:%1$s(card%2$s,%3$s).\\n' => '卡付款无法开始:%1$s(卡%2$s、%3$s)。',
  '\\ntest mode\\n' => '测试模式',
  '\\nlive\\n' => '直播',
  '\\nCard payment started:%1$sinstallments,%2$scharged by the bank.\\n' => '卡付款开始:%1$s分期付款,%2$s由银行收取。',
  '\\niyzico 3D Secure:%s\\n' => 'iyzico 3D 安全:%s',
  '\\nThe bank did not confirm the 3D Secure code. Please try again.\\n' => '银行未确认 3D 安全代码。请重试。',
  '\\nThis card is not enrolled for 3D Secure. Please call your bank or use another card.\\n' => '此卡未注册 3D Secure。请致电您的银行或使用其他卡。',
  '\\nThe bank could not check the card. Please try again or use another card.\\n' => '银行无法检查该卡。请重试或使用另一张卡。',
  '\\niyzico: the payment was not completed (%s).\\n' => 'iyzico: 付款未完成 (%s)。',
  '[[\'Default address\\n' => '默认地址',
  '\\nThe page has expired. Please try again.\\n' => '该页面已过期。请重试。',
  '\\nPlease fill in the name, address and city.\\n' => '请填写姓名、地址和城市。',
  'Address saved.' => '地址已保存。',
  '\\nAddress deleted.\\n' => '地址已删除。',
  '\\nDefault address changed.\\n' => '默认地址已更改。',
  '\\nAddress book\\n' => '通讯录',
  '\\nSaved addresses are offered in a list at the checkout. The default one is filled in automatically.\\n' => '结帐时会在列表中提供已保存的地址。默认值会自动填写。',
  'Default' => '默认',
  'Make default' => '设为默认',
  '\\nDelete this address?\\n' => '删除该地址?',
  '\\n+ Add a new address\\n' => '+ 添加新地址',
  '\\nAddress name\\n' => '地址名称',
  '\\ne.g. Home, Office\\n' => 'e.g.家庭、办公室',
  'Save address' => '保存地址',
  '\\nSaved address\\n' => '已保存的地址',
  '\\nWrite the new address below; it is saved to your address book with the order.\\n' => '在下面写下新地址;它会与订单一起保存到您的地址簿中。',
  '\\nManage addresses\\n' => '管理地址',
  '\\nKeys are read from the iyzico WooCommerce plugin settings.\\n' => '密钥是从 iyzico WooCommerce 插件设置中读取的。',
  '\\nKeys are read from Donations › Settings › Payments › iyzico.\\n' => '密钥从捐赠 › 设置 › 付款 › iyzico 中读取。',
  '\\nNo iyzico keys found. Enter them in the iyzico WooCommerce plugin or in Donations › Settings › Payments › iyzico.\\n' => '未找到 iyzico 密钥。在 iyzico WooCommerce 插件或捐赠 › 设置 › 付款 › iyzico 中输入它们。',
  '\\nEnvironment: sandbox (test).\\n' => '环境:沙箱(测试)。',
  '\\nEnvironment: live.\\n' => '环境:现场。',
  '\\niyzico reported a payment (%s) that does not match this order (amount, currency or basket). Check it in the iyzico panel before doing anything.\\n' => 'iyzico 报告了一笔付款 (%s) 与此订单(金额、货币或篮子)不匹配。在执行任何操作之前,请在 iyzico 面板中检查它。',
  '\\niyzico payment received:%1$s, payment id%2$s(%3$s).\\n' => 'iyzico 收到付款:%1$s,付款 ID%2$s(%3$s)。',
  '\\nEnter an amount to refund.\\n' => '输入退款金额。',
  '\\nThis order has no iyzico transaction to refund.\\n' => '此订单没有可退款的 iyzico 交易。',
  '\\nThe amount is more than what is left to refund at iyzico.\\n' => '金额超过了 iyzico 剩余的退款金额。',
  '\\niyzico refused the refund:%s\\n' => 'iyzico 拒绝退款:%s',
  '\\nRefunded at iyzico:%1$s.%2$s\\n' => '在 iyzico 退款:%1$s。%2$s',
  '\\nClassic\\n' => '经典',
  '\\nOne card: type tabs on top, the choices under them, the total at the bottom.\\n' => '一张卡:在顶部键入选项卡,在其下方键入选项,在底部键入总计。',
  '\\nA · Steps + summary\\n' => 'A · 步骤 + 摘要',
  '\\nNumbered steps on the left, a summary with the total and the button on the right.\\n' => '左侧有编号的步骤,右侧有包含总计的摘要和按钮。',
  '\\nB · Two panels\\n' => 'B · 两个面板',
  '\\nTypes as a list on the left, the details on the right; a dark total bar.\\n' => '在左侧输入列表,在右侧输入详细信息;黑色总栏。',
  '\\nC · Picture cards\\n' => 'C · 图卡',
  '[[\'Large cards with the type picture or icon; the details open below.\\n' => '带有类型图片或图标的大卡片;详细信息如下。',
  'List' => '列表',
  '\\nAll options one under the other.\\n' => '所有选项一个接一个。',
  '\\nDrop-down\\n' => '下拉菜单',
  '\\nOne row: the option in a drop-down menu and the quantity beside it.\\n' => '一行:下拉菜单中的选项及其旁边的数量。',
  '\\nList, then one row\\n' => '列表,然后一行',
  '\\nThe list first; after a pick it folds into one row (drop-down + quantity) and the rest of the form opens.\\n' => '列表优先;选择后,它会折叠成一行(下拉菜单+数量),然后打开表单的其余部分。',
  'Theme' => '主题',
  '\\nThe look of WooCommerce and the theme.\\n' => 'WooCommerce 的外观和主题。',
  'A · Side-by-side cards' => 'A·并排卡',
  '\\nMethods as cards with icons; the details of the picked one below.\\n' => '方法如带有图标的卡片;下面是所选择的详细信息。',
  'B · Plain list' => 'B · 普通列表',
  '\\nRows one under the other; the picked row opens.\\n' => '一排排在另一排下面;选定的行将打开。',
  'C · Segmented tabs' => 'C·分段选项卡',
  '\\nOne row of tab buttons; the details of the picked one below.\\n' => '一排选项卡按钮;下面是所选择的详细信息。',
  '\\nOptions and amount\\n' => '选项和金额',
  '\\nOn whose behalf\\n' => '代表谁',
  '\\nCertificate design\\n' => '证书设计',
  '\\nRepeat every month\\n' => '每月重复一次',
  'Appearance' => '外观',
  'Donation form' => '捐款表格',
  '\\nHow the "Donation options" block looks on the site. Prices, options and names are set under Donation types.\\n' => '“捐赠选项”块在网站上的外观。价格、选项和名称在捐赠类型下设置。',
  '\\nView the page\\n' => '查看页面',
  '\\nHeading over the types\\n' => '类型标题',
  '\\nShown in the A and C layouts.\\n' => '显示在 A 和 C 布局中。',
  '\\nHeading over the options\\n' => '查看选项',
  '\\nChoose an option\\n' => '选择一个选项',
  '\\nHow the options are shown\\n' => '选项如何显示',
  '\\nOrder of the sections\\n' => '各部分的顺序',
  '\\nThe type choice is always first and the total always last. Sections a type does not use are skipped.\\n' => 'The type choice is always first and the total always last.类型不使用的部分将被跳过。',
  '\\nAsk a phone number for every share (types with a proxy). The video or certificate of that share can be sent there too.\\n' => '询问每个共享的电话号码(使用代理的类型)。该共享的视频或证书也可以发送到那里。',
  '\\nPayment options at the checkout\\n' => '结帐时的付款选项',
  '\\nHow card, PayPal, bank transfer and the other methods are shown. The methods themselves are turned on under WooCommerce › Settings › Payments.\\n' => '如何显示卡、PayPal、银行转账和其他方式。这些方法本身在 WooCommerce › 设置 › 付款下打开。',
  '\\nColours and corners\\n' => '颜色和角',
  '\\nUsed by the form and the payment options. Empty fields follow the theme.\\n' => '由表单和付款选项使用。空字段遵循主题。',
  'Main colour' => '主色',
  'Accent colour' => '强调色',
  '\\nCorner radius (px)\\n' => '圆角半径 (px)',
  '\\n0 = square, 4 = plain corporate, 16 = round.\\n' => '0 = 方形,4 = 普通公司,16 = 圆形。',
  '\\nTransaction fee\\n' => '交易费用',
  '\\nDonors can choose to also pay the fee of the payment method, so the whole donation reaches you. The fee is added at the checkout for the method they pick.\\n' => '捐赠者可以选择同时支付付款方式的费用,以便全部捐赠到达您的手中。费用会在结帐时根据他们选择的方法添加。',
  '\\nShow "I will cover the transaction fee" on the donation form\\n' => '在捐款表格上注明“我将支付交易费”',
  '\\nTicked by default\\n' => '默认勾选',
  '\\nFixed\\n' => '已修复',
  '\\nEmpty or 0 = no fee for that method (for example bank transfer). Fee = donation × % + fixed.\\n' => '空或 0 = 该方法不收取任何费用(例如银行转账)。费用=捐款×%+固定金额。',
  '\\nPlease choose what you would like to donate for.\\n' => '请选择您想要捐赠的项目。',
  '\\nThis option cannot be donated in%s. Please choose another currency.\\n' => '此选项无法在%s中捐赠。请选择其他货币。',
  '\\nThis option cannot be donated online at the moment.", \'en\']]' => '此选项目前无法在线捐赠。',
  '\\nThe number must be between 1 and%s.\', \'en\']]' => '数字必须介于 1 和%s之间。',
  '\\nThe amount must be at least%s.\\n' => '金额必须至少为%s。',
  '\\nFor this amount please get in touch with us.\\n' => '对于此金额,请与我们联系。',
  '\\nPlease choose an option.\\n' => '请选择一个选项。',
  '\\nPrinted certificates are not available yet. Please choose the online certificate.\\n' => '打印证书尚不可用。请选择在线证书。',
  '\\nPlease write the postal address for the printed certificate.\\n' => '请填写打印证书的邮寄地址。',
  '\\nPlease write the name of the person you are donating for.\\n' => '请写下您要为其捐款的人的姓名。',
  '\\nThis donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.\\n' => '此捐赠需要代理 (vekâlet) 同意,但尚未设置。请联系站点管理员。',
  '\\nThe proxy (vekâlet) text has been updated. Please read it again and accept it.\\n' => '代理 (vekâlet) 文本已更新。请再次阅读并接受。',
  '[[\'Please write at most%sname (one per share).\', \'en\']]' . chr(0) . '[[\'Please write at most%snames (one per share).\', \'en\']]' => '请最多写入%s名称(每个共享一个)。',
  '\\nThe phone number does not look right. Example: 0532 123 45 67\\n' => '电话号码看起来不正确。示例: 0532 123 45 67',
  '\\nThe e-mail address does not look right.\\n' => '电子邮件地址看起来不正确。',
  '\\nThis cause does not take monthly donations.\\n' => '该事业不需要每月捐款。',
  '\\nMonthly donations are not available at the moment.\\n' => '目前无法提供每月捐款。',
  '\\nDonations in%scannot be paid here at the moment.\\n' => '目前无法在%s中支付捐款。',
  '\\nThe donation product could not be found.\\n' => '找不到捐赠产品。',
  '\\nIt could not be added to the cart.\\n' => '无法将其添加到购物车。',
  '\\nA donation in your cart cannot be paid in%sand was removed.\\n' => '您购物车中的捐款无法在%s中支付,已被删除。',
  '\\nA donation in your cart is no longer available and was removed.\\n' => '您购物车中的捐赠不再可用,已被删除。',
  '\\nPrinted certificates can only be paid in the store currency; your certificate will be sent online.\\n' => '打印的凭证只能以商店货币支付;您的证书将在线发送。',
  '\\nProducts in your cart can only be paid in%1$s.<a href="%2$s">Switch to%1$s</a>\\n' => '您购物车中的产品只能通过%1$s付款。<a href="%2$s">切换到%1$s</a>',
  '\\nPrinted certificate delivery\\n' => '打印证书交付',
  '\\nRepeats\\n' => '重复',
  'Every month' => '每个月',
  '[[\'Names (one per share)\\n' => '名称(每股一个)',
  '\\nDesign\\n' => '设计',
  '\\nName on the certificate\\n' => '证书上的名称',
  '\\nSent to\\n' => '发送至',
  '\\ncopy to me\\n' => '复制给我',
  '\\nPostal address\\n' => '邮寄地址',
  '\\naccepted (text version%s)\\n' => '已接受(文本版本%s)',
  '\\nOnline + printed\\n' => '在线 + 打印',
  'Online' => '在线',
  '\\n%sSapling Donation\\n' => '%s树苗捐赠',
  '\\nCertificate no\\n' => '证书编号',
  '\\nThe certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).\\n' => '无法制作证书:找不到 Flux 证书模板(捐赠 > 设置 > WooCommerce)。',
  '\\nThe certificate could not be made:%s\\n' => '无法制作证书:%s',
  '\\nNot sent yet.\\n' => '尚未发送。',
  '\\nCertificate made:%1$s(%2$s).%3$s\\n' => '制作的证书:%1$s(%2$s)。%3$s',
  '\\nCertificates made again (%d); the old ones were revoked.\\n' => '再次制作证书(%d);旧的已被撤销。',
  '\\nNo delivery channel is chosen.\\n' => '未选择传送渠道。',
  '\\nQueued:%s.\\n' => '排队:%s。',
  '\\nCopy to the donor:%s.\\n' => '复制到捐赠者:%s。',
  'Link copied' => '链接已复制',
  '\\nThe preview could not be drawn. You can open it with "View certificate".\\n' => '无法绘制预览。您可以使用“查看证书”打开它。',
  '[[\'Your certificate is ready\', \'en\']]' . chr(0) . '[[\'Your certificates are ready\', \'en\']]' => '您的证书已准备好',
  '\\nNo:%s\\n' => '否:%s',
  'Download PDF' => '下载PDF',
  '\\nView certificate\\n' => '查看证书',
  '\\nYour certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.\\n' => '正在准备您的证书。几分钟后将通过 WhatsApp 和电子邮件发送;您还可以刷新此页面来查看它。',
  '\\nThis certificate design cannot be chosen any more. Please pick another one.\\n' => '此证书设计无法再选择。请选择另一个。',
  '\\nPlease fill in "%s" for the certificate.\\n' => '请填写“%s”作为证书。',
  '\\nPick the design of your certificate. The donation amount does not change.\\n' => '选择您的证书的设计。捐赠金额不变。',
  'Standard' => '标准型',
  '\\n"%s" was paid once: the card was not stored, so it will not repeat monthly.\\n' => '“%s”已支付一次:该卡未存储,因此每月不会重复。',
  '\\n"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.\\n' => '“%1$s”每月重复一次(定期捐赠#%2$d);该卡存储在 iyzico。',
  '\\nCard (iyzico), monthly\\n' => '卡 (iyzico),每月',
  '\\nMonthly renewal of recurring donation #%1$d(first order #%2$s).\\n' => '每月续订定期捐款 #%1$d(第一笔订单 #%2$s)。',
  '\\nMonthly charge accepted by iyzico:%1$s, payment id%2$s.\\n' => 'iyzico 接受的每月费用:%1$s,付款 ID%2$s。',
  '\\nMonthly charge failed after the last attempt:%s\\n' => '最后一次尝试后每月充电失败:%s',
  '\\nMonthly charge failed, it will be retried:%s\\n' => '月费失败,将重试:%s',
  '\\nFlux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.\\n' => 'Flux Donate 始终使用 EsnekPOS 的安全支付页面;需要时银行会要求提供 3D Secure。',
  '\\nFlux Donate\\n' => '通量捐赠',
  '\\nFlux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\\\'s developer page.\\n' => 'Flux Donate 运行此付款方式:经典和块结帐、无购物车的付款链接,并且在订单标记为已付款之前,每笔付款均通过服务器的 EsnekPOS 进行确认。要进行测试,请输入商家 TEST1234 以及来自 EsnekPOS 开发者页面的测试商家密钥。',
  '\\nDonation #%d\\n' => '捐赠 #%d',
  '\\nEsnekPOS did not answer (HTTP%d).\\n' => 'EsnekPOS 未应答 (HTTP%d)。',
  '\\nEsnekPOS payment could not start:%s\\n' => 'EsnekPOS 付款无法开始:%s',
  '\\nEsnekPOS payment could not start:%1$s(%2$s).\\n' => 'EsnekPOS 付款无法开始:%1$s(%2$s)。',
  '\\nThe payment is being checked. Please wait a moment and refresh the page.\\n' => '正在检查付款。请稍等片刻并刷新页面。',
  '\\nEsnekPOS payment could not be checked:%s\\n' => '无法检查 EsnekPOS 付款:%s',
  '\\nThe payment could not be verified yet. If money was taken from your card, please contact us before trying again.\\n' => '尚未验证付款。如果您的卡上的钱被提取,请在重试之前联系我们。',
  '\\nEsnekPOS payment received: reference%1$s,%2$sinstallment(s),%3$scharged.\\n' => '已收到 EsnekPOS 付款:参考%1$s、%2$s分期付款、已收取%3$s。',
  '\\nEsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.\\n' => 'EsnekPOS 报告的付款 (%s) 与此订单(金额或参考)不匹配。在执行任何操作之前,请在 EsnekPOS 面板中检查它。',
  '\\nEsnekPOS return said success but EsnekPOS did not confirm the payment:%s\\n' => 'EsnekPOS 返回表示成功,但 EsnekPOS 未确认付款:%s',
  '\\nEsnekPOS: the payment was not completed (%s).\\n' => 'EsnekPOS: 付款未完成 (%s)。',
  '\\nTest mode (merchant TEST1234).\\n' => '测试模式(商家 TEST1234)。',
  '\\nFlux Donate sends the order lines, no cart needed.\\n' => 'Flux Donate 发送订单行,无需购物车。',
  '\\nFlux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.\\n' => 'Flux Donate 在订单标记为已付款之前询问 EsnekPOS (ProcessQuery)。',
  '\\nOn EsnekPOS\\\'s payment page, as set in the EsnekPOS panel.\\n' => '在 EsnekPOS 的支付页面上,按照 EsnekPOS 面板中的设置。',
  '\\nRefund in the EsnekPOS panel, then mark the order refunded.\\n' => '在 EsnekPOS 面板中退款,然后将订单标记为已退款。',
  '[[\'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' . chr(0) . '[[\'Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' => '%1$s树苗捐赠。%2$s会为您种植它们,并以您的名义发送在线证书。通过卡或银行转帐付款。',
  '\\nDonation packages\\n' => '捐赠包',
  '\\nDonation >%s\\n' => '捐赠 >%s',
  '\\nI will also cover the transaction fee\\n' => '我还将支付交易费',
  '\\nSo your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.\\n' => '这样您的全部捐款就达到了目的。确切的费用取决于付款方式并在结账时显示。',
  '\\nTransaction fee (covered by you)\\n' => '交易费用(由您承担)',
  '\\nAny trouble? Write to us on WhatsApp:\\n' => '有什么麻烦吗?通过 WhatsApp 给我们写信:',
  '\\nNo badge\\n' => '没有徽章',
  '\\nBest value\\n' => '最佳价值',
  '\\nMost popular\', \'en\']]' => '最受欢迎',
  '\\nFamily pack\\n' => '家庭包',
  '\\nHello{ad}, your donation of{tutar}is registered. IBAN:{iban}Reference:{aciklama}Upload your receipt:{link}\\n' => '您好{ad},您的{tutar}捐赠已登记。 IBAN:{iban}参考号:{aciklama}上传收据:{link}',
  '\\nHello{ad}🌱\\n\\nYour donation of *{tutar}* is registered (No:{siparis}).\\n\\nBank transfer details:\\nRecipient:{alici}\\nIBAN:{iban}\\nReference: *{aciklama}*\\n\\nAfter the transfer you can upload your receipt here:\\n{link}\\n\\nThank you,\\n{site}\\n' => '您好{ad}🌱' . chr(10) . '' . chr(10) . '您的 *{tutar}* 捐赠已登记(编号:{siparis})。' . chr(10) . '' . chr(10) . '银行转帐详细信息:' . chr(10) . '收款人:{alici}' . chr(10) . 'IBAN:{iban}' . chr(10) . '参考:*{aciklama}*' . chr(10) . '' . chr(10) . '转帐后,您可以在此处上传您的收据:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . '谢谢你,' . chr(10) . '{site}',
  '\\nPending transfer notification sent:%s.\\n' => '已发送待处理传输通知:%s。',
  '\\nWooCommerce checks\\n' => 'WooCommerce 检查',
  'This check could not run: %s' => '此检查无法运行:%s',
  '\\nVersion%1$sis active. Flux Donate was checked up to%2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.\\n' => '版本%1$s处于活动状态。 Flux Donate 已检查至%2$s;它仅使用稳定的公共 WooCommerce 功能,但会在大型 WooCommerce 更新后测试捐赠。',
  '\\nActive, version%s. Donations are paid through the WooCommerce cart and checkout.\\n' => '活动,版本%s。捐款通过 WooCommerce 购物车和结帐支付。',
  '\\nOne-time card payments are taken by%s; iyzico is not shown at the checkout.\\n' => '一次性卡付款由%s进行;结帐时不会显示 iyzico。',
  '\\nOne-time card payments are taken by the official iyzico WooCommerce plugin.\\n' => '一次性卡付款由官方 iyzico WooCommerce 插件进行。',
  '\\nCard payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).\\n' => '卡付款在结帐时使用我们自己的卡字段(iyzico 3D Secure、分期付款、保存的卡)。',
  '\\nOne-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => '一次性卡付款由 Flux Donate iyzico 进行(未启用官方 iyzico 插件)。',
  '\\nCard payments are taken by:%s.\\n' => '银行卡付款方式为:%s。',
  '\\nNo card method is enabled; donations can only be paid by bank transfer.\\n' => '未启用任何卡方法;捐款只能通过银行转账的方式支付。',
  '\\nCard payments (WooCommerce)\\n' => '卡付款 (WooCommerce)',
  '\\nMonthly donations\\n' => '每月捐款',
  '\\nFlux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.\\n' => 'Flux Donate iyzico 在首次付款时存储该卡;每月都会开立续订订单并收取费用。',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.\\n' => '每月捐赠已关闭:在 WooCommerce › 设置 › 付款中启用“卡 (iyzico) - Flux Donate”并输入 iyzico 密钥。',
  '\\nBank transfer (donations)\\n' => '银行转账(捐款)',
  '\\nNo IBAN entered.\\n' => '未输入 IBAN。',
  '\\nThe payment method is disabled.\\n' => '付款方式已禁用。',
  '\\nBank transfer settings\\n' => '银行转帐设置',
  '\\nTwo bank transfer methods\\n' => '两种银行转帐方式',
  '\\nWooCommerce\\\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".\\n' => 'WooCommerce 自己的“直接银行转账”在捐赠银行转账旁边启用。捐赠者会看到两个类似的选择,并且收据上传仅适用于捐赠的一项;禁用“直接银行转帐”。',
  '\\nThe shop currency is%1$s; these types use another currency and are charged in%1$sat the same number:%2$s\\n' => '商店货币为%1$s; these types use another currency and are charged in%1$sat the same number:%2$s',
  '\\nWooCommerce settings\\n' => 'WooCommerce 设置',
  '\\nDonation types and the shop use%s.\\n' => '捐赠类型和商店使用%s。',
  '\\nDonation products\\n' => '捐赠产品',
  '\\nThese types get their hidden WooCommerce product the first time they are donated to or saved:%s\\n' => '这些类型在第一次捐赠或保存时获得隐藏的 WooCommerce 产品:%s',
  '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' => '%d活动类型具有其隐藏的 WooCommerce 产品。%d活动类型具有隐藏的 WooCommerce 产品。',
  '\\nNo page with the donation options block is selected.\\n' => '未选择带有捐赠选项块的页面。',
  '\\nOther payment plugins\\n' => '其他支付插件',
  '\\nCheck these on the donation checkout:%s. Details: Donations › Settings › WooCommerce › Payment methods.\\n' => '在捐赠结帐处检查这些:%s。详细信息:捐赠 › 设置 › WooCommerce › 付款方式。',
  'Payment methods' => '付款方式',
  '\\nEnabled and shown on the donation checkout:%s.\\n' => '已启用并显示在捐赠结帐上:%s。',
  '\\nCertificates after payment\\n' => '付款后证书',
  '\\nFlux Certificates makes the certificates of paid donation lines.\\n' => 'Flux Certificates 制作付费捐款线的证书。',
  '\\nFlux Certificates has no active template.\\n' => 'Flux 证书没有活动模板。',
  '\\nProduct XML\\n' => '产品 XML',
  '\\n%1$slists%2$ddonation packages (Google Merchant format, e.g. for iyzico).\\n' => '%1$s列出%2$d捐赠包(Google Merchant 格式,例如 iyzico)。',
  '\\nPayment forms on the checkout\\n' => '结帐时的付款表格',
  '\\nDonation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.\\n' => '捐赠表格将他们的选择发送到 WooCommerce 购物车;订单支付后,“付款已完成”自动化运行。',
  '\\nFlux Forms%sis active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.\\n' => '通量形式%s处于活动状态。表单在结账时付款,但其“付款已完成”自动化功能需要 Flux Forms 2.1.0 或更高版本。',
  'Plugins' => '插件',
  '\\nDonation e-mails\\n' => '捐赠电子邮件',
  '\\nSent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.\\n' => '通过 Flux 邮件发送;可以在那里编辑模板(“Flux Donate”组)。 WooCommerce 订单电子邮件保留在 WooCommerce › 设置 › 电子邮件中。',
  '\\nE-mail templates\\n' => '电子邮件模板',
  '\\nFlux Mail is not active: the donation e-mails are sent as plain text with their default wording.\\n' => 'Flux 邮件未激活:捐赠电子邮件以纯文本形式使用默认措辞发送。',
  '\\nBank transfer (donation)\\n' => '银行转账(捐赠)',
  '\\nThe donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.\\n' => '捐赠者使用特定于订单的参考号转账,并将收据上传到网站上。确认付款后将颁发证书。',
  'Enabled' => '启用',
  '\\nTake donations by bank transfer\\n' => '通过银行转账接受捐款',
  'Empty = "Bank transfer" in the site language.' => '空 = 网站语言中的“银行转账”。',
  'Text on the checkout page' => '结帐页面上的文字',
  'Empty = the default text in the site language.' => '空 = 站点语言的默认文本。',
  'Recipient (account holder)' => '收款人(账户持有人)',
  '\\nEmpty = the holder of the bank account below or, without an IBAN here, of WooCommerce\\\'s "Direct bank transfer" account (else the theme settings).\\n' => '空 = 以下银行帐户的持有人,或者此处没有 IBAN 的 WooCommerce“直接银行转帐”帐户(否则主题设置)的持有人。',
  '\\nThe account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\\\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.\\n' => '帐户随处可见(捐赠页面、结帐、呼叫中心)。空 = WooCommerce 的“直接银行转账”的第一个帐户,其他为主题设置;收件人和银行也来自该帐户。',
  'Bank (optional)' => '银行(可选)',
  '\\nWhat the donor writes in the transfer description. Placeholders:{tur}(sapling donation / donation),{kod}(prefix + order no),{siparis},{ad}. Empty:{tur}{kod}{ad}\\n' => '捐赠者在转账说明中所写的内容。占位符:{tur}(树苗捐赠/捐赠)、{kod}(前缀+订单号)、{siparis}、{ad}。空:{tur}{kod}{ad}',
  'Code prefix' => '代码前缀',
  '\\nBank transfer pre-registration: waiting for the payment.\\n' => '银行转账预登记:等待付款。',
  '\\nCard (iyzico) - Flux Donate\\n' => '卡片 (iyzico) - 通量捐赠',
  '\\nCard payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.\\n' => 'iyzico 安全页面上的卡付款。每月捐款所需(该卡由 iyzico 存储,每月收费);当官方 iyzico 插件未激活时,也可用于一次性捐赠。',
  'Enable' => '启用',
  '\\nCard payments through Flux Donate (iyzico)\\n' => '通过 Flux Donate (iyzico) 进行卡支付',
  '\\nCredit / debit card (iyzico)\\n' => '信用卡/借记卡 (iyzico)',
  'Description' => '描述',
  'API keys' => 'API 密钥',
  '\\nYou will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.\\n' => '您将在 iyzico 的安全页面上付款。对于每月捐款,您的卡由 iyzico 存储并每月收取一次费用;您可以随时取消。',
  '\\nDonation options\\n' => '捐赠选项',
  '\\nSapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.\\n' => '树苗包裹、原因和无偿捐赠;添加到购物车并通过 WooCommerce 付款。',
  '\\nTab shown first\\n' => '首先显示选项卡',
  '\\nThe first one\\n' => '第一个',
  '\\nNone chosen = the types marked "Show in the Donation options block".\\n' => '未选择 = 标记为“在捐赠选项块中显示”的类型。',
  '\\nPrices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.\\n' => '价格和选项:捐赠 › 捐赠类型。证书和购物车:捐赠 › 设置 › WooCommerce。',
  '[[\'Could not copy, please select it by hand.\\n' => '无法复制,请手动选择。',
  'Uploading…' => '正在上传...',
  '\\nWe have your receipt. Thank you! We will let you know once the payment is confirmed.\\n' => '我们有您的收据。谢谢你!付款确认后我们会通知您。',
  'The file is too large.' => '文件太大。',
  'Something went wrong. Please try again.' => '出了点问题。请再试一次。',
  'Add another receipt' => '添加另一张收据',
  '\\nReceipt under review\\n' => '收据正在审核中',
  '\\nPlease write a WhatsApp number or an e-mail address (at least one).\\n' => '请写下 WhatsApp 号码或电子邮件地址(至少一个)。',
  '\\nPlease enter a valid e-mail address.\\n' => '请输入有效的电子邮件地址。',
  '\\nPlease enter a valid phone number.\\n' => '请输入有效的电话号码。',
  '\\nPlease write at most one name per share.\\n' => '每个共享最多只能写一个名称。',
  '\\n/ month\\n' => '/月',
  '\\n(up to%s)\\n' => '(直到%s)',
  '[[\'%sSapling\', \'en\']]' . chr(0) . '[[\'%sSaplings\', \'en\']]' => '%s树苗',
  '\\nWho is this donation for?\\n' => '这笔捐款是给谁的?',
  '\\nFor myself\\n' => '为了我自己',
  '\\nOn behalf of someone else\\n' => '代表其他人',
  '\\nTheir name\\n' => '他们的名字',
  '\\ne.g. Ayşe Yılmaz or the Yılmaz family\\n' => 'e.g. Ayşe Yılmaz 或 Yılmaz 家族',
  '\\nOptional. If you leave it empty, the name from the checkout is used.\\n' => '可选。如果将其留空,则使用结账时的名称。',
  '\\nWritten on the certificate and the donation record.\\n' => '写在证书和捐赠记录上。',
  '\\nWritten on the donation record.\\n' => '写在捐款记录上。',
  '\\nWhere should the certificate go?\\n' => '证书应该去哪里?',
  '\\nEmpty fields use the phone and e-mail of your account or the checkout.\\n' => '空白字段使用您帐户或结帐时的电话和电子邮件。',
  '\\nTheir phone and e-mail. Empty fields use yours.\', \'en\']]' => '他们的电话和电子邮件。空字段使用您的。',
  '\\nSend me a copy too\\n' => '也给我发一份',
  '\\nOnline certificate\\n' => '在线证书',
  '\\nSent by WhatsApp and e-mail once the payment is confirmed, ready to download.\\n' => '付款确认后通过 WhatsApp 和电子邮件发送,可供下载。',
  '\\nOnline + printed certificate\\n' => '在线+打印证书',
  '\\nA printed certificate is also posted to your address.\\n' => '打印的证书也会邮寄到您的地址。',
  'Free' => '免费',
  'Coming soon' => '即将推出',
  '\\nPostal address for the printed certificate\\n' => '打印证书的邮寄地址',
  '\\nName, full address, district / city, phone\', \'en\']]' => '姓名、详细地址、区/市、电话',
  '\\nBy card, stop any time.\\n' => '刷卡,随时停车。',
  '\\nYour donation was added to the cart.\\n' => '您的捐款已添加到购物车。',
  '\\nGo to cart\\n' => '转到购物车',
  '\\nYour donation\\n' => '您的捐款',
  'Continue' => '继续',
  'Add to cart' => '添加到购物车',
  '\\nfrom%s\\n' => '来自%s',
  '\\nPayments are taken securely by iyzico.\\n' => 'iyzico 安全地进行付款。',
  '\\nPay safely by card or bank transfer.\\n' => '通过卡或银行转帐安全付款。',
  '\\nYour card details are never stored on our site.\\n' => '您的银行卡详细信息绝不会存储在我们的网站上。',
  '\\nHow many saplings would you like to donate?\\n' => '您想捐赠多少棵树苗?',
  '\\nAnother amount\\n' => '另一笔金额',
  'Fewer' => '更少',
  'Number of saplings' => '树苗数量',
  'More' => '更多',
  'Donation amount' => '捐款金额',
  '\\nOr write another amount\\n' => '或者写另一个金额',
  '\\nAt least%s\\n' => '至少%s',
  '\\nOn whose behalf?\\n' => '代表谁?',
  '\\nGiven in your name, as you write it at the checkout.\\n' => '以您在结账时所写的姓名提供。',
  '\\nShares without a name are given in the name from the checkout. With a phone number we can also send that person the news on WhatsApp.\\n' => '没有名称的股票以结帐时的名称给出。通过电话号码,我们还可以通过 WhatsApp 向该人发送新闻。',
  '\\nShares without a name are given in the name from the checkout.\\n' => '没有名称的共享以结账时的名称给出。',
  '\\nRead the proxy (vekâlet) text (version%s)\\n' => '读取代理 (vekâlet) 文本(版本%s)',
  '\\nI give my proxy (vekâlet) for the sacrifice according to this text.\\n' => '我根据本文给出我的代理人(vekâlet)作为牺牲。',
  '\\nShare%s\\n' => '共享%s',
  '\\nApply to all\\n' => '应用于所有',
  '\\ne.g. Ali Yılmaz\\n' => 'e.g.阿里·耶尔马兹',
  'Phone (optional)' => '电话(可选)',
  '\\nNo receipt is expected for this donation.\\n' => '预计此次捐赠不会有收据。',
  '\\nAt most 5 receipts can be uploaded for a donation.\\n' => '一次捐赠最多可上传 5 张收据。',
  'The file could not be uploaded. Please try again.' => '文件无法上传。请再试一次。',
  'The file can be at most %s MB.' => '文件最多可为%sMB。',
  'Only PDF, JPG, PNG, WEBP or HEIC files can be uploaded.' => '只能上传 PDF、JPG、PNG、WEBP 或 HEIC 文件。',
  'The file could not be saved.' => '无法保存文件。',
  '\\nThe donor uploaded a receipt:%1$s(%2$s). Check the payment and confirm it.\\n' => '捐赠者上传了收据:%1$s(%2$s)。检查付款并确认。',
  'WhatsApp' => 'WhatsApp',
  '\\nthe site\\n' => '网站',
  '[[\'Warning: this receipt was uploaded before (%1$dtime, via%2$s). Check it before confirming the payment.\', \'en\']]' . chr(0) . '[[\'Warning: this receipt was uploaded before (%1$dtimes, via%2$s). Check it before confirming the payment.\', \'en\']]' => '警告:此收据之前已上传(%1$d次,通过%2$s)。请先检查后再确认付款。',
  '\\nEarlier donation: #%d.\\n' => '之前的捐赠:#%d。',
  'We have your receipt. We will let you know once the payment is confirmed.' => '我们有您的收据。付款确认后我们会通知您。',
  'Choose a receipt or drop it here' => '选择收据或将其放在此处',
  'PDF, JPG or PNG · up to %s MB' => 'PDF、JPG 或 PNG · 最大%sMB',
  'Send receipt' => '发送收据',
  'Please choose a file.' => '请选择一个文件。',
  'We have your receipt. Thank you!' => '我们有您的收据。谢谢你!',
  '\\nWooCommerce checkout\\n' => 'WooCommerce 结帐',
  '\\nYou will choose how to pay (card or bank transfer) on the next page.\\n' => '您将在下一页选择付款方式(卡或银行转帐)。',
  '\\nMonthly donations are paid by card; the card is stored by iyzico and charged once a month.\\n' => '每月捐款通过卡支付;该卡由 iyzico 存储,每月收费一次。',
  '\\nThis form is not linked to a donation type. Please contact the site administrator.\\n' => '此表格未链接到捐赠类型。请联系站点管理员。',
  '\\nThe donation type of this form was not found.\\n' => '找不到此表单的捐赠类型。',
  '\\nThe amount could not be calculated. Please review your choices and try again.\\n' => '金额无法计算。请检查您的选择并重试。',
  'Pending donations' => '待定捐款',
  '\\nYou have no pending donations.\\n' => '您没有待处理的捐款。',
  '\\nDonations made by bank transfer appear here until the payment is confirmed.\\n' => '通过银行转帐进行的捐款将显示在此处,直至付款得到确认。',
  'Donate' => '捐赠',
  '\\nYour bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.\\n' => '您的银行转帐捐款。如果您已付款,请上传收据;您的证书一经确认就会发送。',
  '\\nDonation #%s\\n' => '捐赠 #%s',
  'Awaiting payment' => '等待付款',
  '[[\'%sdonation is awaiting payment\', \'en\']]' . chr(0) . '[[\'%sdonations are awaiting payment\', \'en\']]' => '%s捐款正在等待付款',
  '\\nIf you have made the transfer, upload your receipt.\\n' => '如果您已进行转账,请上传收据。',
  '\\nPlease write your e-mail or phone number (at least one).\\n' => '请写下您的电子邮件或电话号码(至少一个)。',
  'Donation summary' => '捐款概要',
  '\\nWrite at least one. We send your receipt and certificate there.\\n' => '至少写一个。我们会将您的收据和证书发送到那里。',
  '\\nContinue to payment\\n' => '继续付款',
  '\\nI have read and accept the%1$sprivacy policy%2$sand the%3$sdonation agreement%4$s.\\n' => '我已阅读并接受%1$s隐私政策%2$s和%3$s捐赠协议%4$s。',
  '\\nMake payment\\n' => '付款',
  '\\nPlease read and accept the terms to continue.\\n' => '请阅读并接受条款以继续。',
  '\\nDonation terms\\n' => '捐赠条款',
  '\\nPrivacy policy\\n' => '隐私政策',
  '\\nThese terms apply to donations made on this site to%s.\\n' => '这些条款适用于在本网站上向%s进行的捐赠。',
  '\\nA donation is a gift without anything in return. It is used for the purpose chosen on the donation form (for example sapling planting). When a purpose is fully funded, the association may use the donation for a similar purpose.\\n' => '捐赠是一种礼物,没有任何回报。它用于捐赠表格上选择的目的(例如树苗种植)。当某个目的得到全额资助时,协会可以将捐款用于类似目的。',
  '\\nCard payments are processed by the licensed payment institution iyzico with 3D Secure. Card details are not stored on this site. For bank transfers, the donation is confirmed when the money reaches the association account.\\n' => '卡支付由持牌支付机构 iyzico 和 3D Secure 处理。该网站不存储银行卡详细信息。对于银行转账,当资金到达协会帐户时,捐款即被确认。',
  '\\nA monthly donation is charged to the same card every month until you cancel it. You can cancel it at any time from your account page or by writing to us.\\n' => '每月捐款会每月从同一张卡中扣除,直到您取消为止。您可以随时从您的帐户页面或写信给我们取消它。',
  '\\nThe online certificate is sent to the e-mail address or phone number you give after the payment is confirmed. Please check the names you write on the certificate.\\n' => '付款确认后,在线证书将发送至您提供的电子邮件地址或电话号码。请检查您写在证书上的姓名。',
  '\\nCancellation and refunds\\n' => '取消和退款',
  '\\nIf a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.\\n' => 'If a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.',
  'Personal data' => '个人资料',
  '\\nYour name and contact details are used to record the donation, send the receipt and certificate, and contact you about your donation. See the privacy policy for details.\\n' => '您的姓名和联系方式将用于记录捐赠、发送收据和证书,并就捐赠事宜与您联系。有关详细信息,请参阅隐私政策。',
  '\\nFor any question about your donation, write to us on WhatsApp:%s\\n' => '如果对您的捐赠有任何疑问,请通过 WhatsApp 给我们写信:%s',
  '\\nFor any question about your donation, write to us through the contact page.\\n' => '如果对您的捐赠有任何疑问,请通过联系页面写信给我们。',
  '\\n%sprocesses your personal data under the Turkish Personal Data Protection Law (KVKK).\\n' => '%s根据土耳其个人数据保护法 (KVKK) 处理您的个人数据。',
  '\\nWhat we collect\\n' => '我们收集什么',
  '\\nName, e-mail address, phone number and the details of your donation. Card details are entered on the payment institution and are not stored by us.\\n' => '姓名、电子邮件地址、电话号码和您的捐款详细信息。卡详细信息由支付机构输入,我们不会存储。',
  'Why' => '为什么',
  '\\nTo record donations, send receipts and certificates, meet legal obligations and answer your questions.\\n' => '记录捐款、发送收据和证书、履行法律义务并回答您的问题。',
  '\\nYour rights\\n' => '您的权利',
  '\\nYou can ask what data we hold about you, have it corrected or deleted, by writing to us.\\n' => '您可以写信给我们,询问我们持有您的哪些数据、更正或删除这些数据。',
  '\\nBlock checkout\\n' => '阻止结帐',
  '\\nNo address\\n' => '没有地址',
  '\\nServer check\\n' => '服务器检查',
  '\\nSaved cards\\n' => '已保存的卡片',
  '\\nRefund from site\\n' => '从网站退款',
  'Monthly' => '每月',
  '\\nShown on a checkout page built with the Checkout block. The classic checkout ([woocommerce_checkout]) shows every method.\\n' => '显示在使用结帐块构建的结帐页面上。经典结帐 ([woocommerce_checkout]) 显示每种方法。',
  '\\nPays an existing order from its payment link (call center, "pay again"), without a cart.\\n' => '通过付款链接(呼叫中心,“再次付款”)支付现有订单,无需购物车。',
  '[["Works on our checkout that asks no address: Flux Donate fills the organisation\'s city and address in.\\n' => '[[“适用于我们的结帐,无需询问地址:Flux Donate 填写组织的城市和地址。',
  '\\nThe payment is confirmed with the provider from the server before the order is marked paid.\\n' => '在订单标记为已付款之前,先从服务器向提供商确认付款。',
  '\\nThe donor can pay in installments.\\n' => '捐赠者可以分期付款。',
  '\\nThe donor can save a card for the next donation.\\n' => '捐赠者可以保存一张卡片以供下次捐赠使用。',
  '\\nThe Refund button on the order sends the refund to the provider.\\n' => '订单上的退款按钮将退款发送给提供商。',
  '\\nMonthly donations charge a stored card every month. Only Flux Donate iyzico does this.\\n' => '每月捐款每月从存储的卡中收取费用。只有 Flux Donate iyzico 可以执行此操作。',
  '\\nAdded by Flux Donate (the plugin has no block support).\\n' => '由 Flux Donate 添加(该插件没有块支持)。',
  '\\nAdded by Flux Donate once the method is enabled.\\n' => '启用该方法后,由 Flux Donate 添加。',
  '\\nTurn on "Show other payment plugins on the checkout block".\', \'en\']]' => '开启“在结账栏显示其他支付插件”。',
  '\\nThe plugin shows its own card fields only on the classic checkout. Use the classic checkout page or ask the provider for block support.\\n' => '该插件仅在经典结帐时显示其自己的卡字段。使用经典结账页面或向提供商请求阻止支持。',
  '\\nMost plugins work; try a payment link once.\\n' => '大多数插件都可以工作;尝试一次付款链接。',
  '\\nDepends on the plugin; ask the provider.\\n' => '取决于插件;询问提供商。',
  '\\nIf the provider offers it, on its payment page.\\n' => '如果提供商提供,则在其付款页面上。',
  '\\nRefund in the provider\'s panel, then mark the order refunded.\\n' => '在提供商面板中退款,然后将订单标记为已退款。',
  '[[\'Confirmed by hand after the receipt.\\n' => '收货后由专人确认。',
  '\\nnot shown on the block checkout page\\n' => '未显示在块结账页面上',
  'Yes' => '是的',
  '\\nYes, by Flux Donate\\n' => '是的,通过 Flux Donate',
  '\\nOn the provider\\\'s page\\n' => '在提供商的页面上',
  'No' => '否',
  'Unknown' => '未知',
  '\\nEvery WooCommerce payment plugin (virtual POS) works on the donation checkout: install it, enter its settings in WooCommerce › Settings › Payments and enable it. This table shows what each one can do here.\\n' => '每个 WooCommerce 支付插件(虚拟 POS)都适用于捐赠结帐:安装它,在 WooCommerce › 设置 › 付款中输入其设置并启用它。下表显示了每个人可以执行的操作。',
  '\\nWooCommerce payments\\n' => 'WooCommerce 付款',
  '\\nPayment logos on the site\\n' => '网站上的付款徽标',
  '\\nCheckout page:%s.\\n' => '结账页面:%s。',
  '\\nCheckout block\\n' => '结帐块',
  '\\nclassic\\n' => '经典',
  'Method' => '方法',
  'On' => '开',
  'Off' => '关闭',
  '\\nOnly one card method is shown to donors. Change it under Cart and checkout › Card payment method.\\n' => '仅向捐赠者展示一种卡方法。在购物车和结帐下更改它 › 卡付款方式。',
  '\\nHidden at checkout\\n' => '结帐时隐藏',
  'yes' => '是的',
  '\\non the provider\'s page\\n' => ' 提供商的页面',
  'no' => '不',
  '\\nunknown, test it\\n' => '未知,测试一下',
  '\\nPoint at a mark for details.\\n' => '指向一个标记以了解详细信息。',
  '[[\'Donation type not found.\\n' => '未找到捐赠类型。',
  'Manual' => '手册',
  '\\nof%sgoal\\n' => '%s目标',
  '\\nGoal progress\\n' => '目标进度',
  '\\nreached\\n' => '已达到',
  '[[\'donor\', \'en\']]' . chr(0) . '[[\'donors\', \'en\']]' => '捐助者',
  '[[\'day left\', \'en\']]' . chr(0) . '[[\'days left\', \'en\']]' => '剩余天数',
  '\\nEnter a name.\\n' => '输入名称。',
  '\\nPartner not found.\\n' => '未找到合作伙伴。',
  '\\nEach tab must be a JSON object.\\n' => '每个选项卡必须是 JSON 对象。',
  '\\nA tab needs an "id".\\n' => '选项卡需要一个“id”。',
