  '\\nWhatsApp text with the file (%1$sname,%2$scode)\\n' => '包含文件的 WhatsApp 文本(%1$s名称、%2$s代码)',
  'Recorded' => '已录制',
  '\\nFile added\\n' => '文件已添加',
  '\\nFile removed\\n' => '文件已删除',
