  '\\nYour recurring donation to{kurum}\\n' => '您对{kurum}的定期捐款',
  '\\nThank you,{ad}\\n' => '谢谢你,{ad}',
  '\\nYour{aralik}donation of{tutar}is set up. The next payment will be taken on{sonraki}.\\n' => '您对{tutar}的{aralik}捐赠已设置。下一次付款将在{sonraki}进行。',
  '\\nYou can cancel your recurring donation at any time with the button below.\\n' => '您可以随时使用下面的按钮取消定期捐赠。',
  '\\nRecurring donation could not be charged\\n' => '无法收取定期捐赠',
  '\\nSent to the donor when the card was declined on every attempt and the recurring donation is paused.\\n' => '当卡每次尝试都被拒绝并且经常性捐赠被暂停时发送给捐赠者。',
  '\\nNumber of attempts\\n' => '尝试次数',
  '\\nWe could not take your donation to{kurum}\', \'en\']]' => '我们无法将您的捐款转至{kurum}',
  '\\nYour recurring donation is paused\\n' => '您的定期捐赠已暂停',
  '\\nDear{ad},\\n' => '亲爱的{ad},',
  '\\nWe tried{deneme}times but could not charge your card for your{aralik}donation of{tutar}, so it is paused. If you would like to continue, please make a new donation on our website or contact us.\\n' => '我们尝试了{deneme}次,但无法从您的卡中收取{aralik}的{tutar}捐赠费用,因此已暂停。如果您想继续,请在我们的网站上进行新的捐赠或联系我们。',
  '\\nDonate again\\n' => '再次捐赠',
  '\\nBank transfer receipt uploaded\\n' => '银行转帐收据已上传',
  '\\nSent to the donations manager when a donor uploads a transfer receipt (dekont).\\n' => '当捐赠者上传转账收据 (dekont) 时发送给捐赠经理。',
  '\\nOrder number\\n' => '订单号',
  '\\nTransfer reference\\n' => '传输参考',
  '\\nFile name\\n' => '文件名',
  '\\nOrder link (admin)\\n' => '订购链接(管理员)',
  '\\nReceipt uploaded: donation #{siparis}({ad})\\n' => '收据已上传:捐款 #{siparis}({ad})',
  '\\nA transfer receipt was uploaded\', \'en\']]' => '转账收据已上传',
  '\\nAmount:{tutar}\\n' => '金额:{tutar}',
  '\\nReference:{aciklama}\\n' => '参考:{aciklama}',
  '\\nFile:{dosya}\\n' => '文件:{dosya}',
  '\\nCheck the payment at the bank and press "Confirm payment" on the order; the certificate is then issued and sent automatically.\\n' => '到银行查看付款情况,并按订单上的“确认付款”;然后会自动颁发并发送证书。',
  '\\nOpen the order\\n' => '打开订单',
  'Payment rejected' => '付款被拒绝',
  '\\nSent to the donor when a manager rejects a bank transfer, with the reason.\\n' => '当经理拒绝银行转账时发送给捐赠者并说明原因。',
  '\\nWe could not confirm your donation payment\\n' => '我们无法确认您的捐款付款',
  '\\nWe could not confirm your payment\\n' => '我们无法确认您的付款',
  '\\nHello{ad},\\n' => '你好{ad},',
  '\\nWe could not confirm the payment of your{tutar}donation.\\n' => '我们无法确认您的{tutar}捐款的付款。',
  '\\nReason:{aciklama}\\n' => '原因:{aciklama}',
  '\\nIf you think this is a mistake, please reply to this e-mail. Thank you.\\n' => '如果您认为这是一个错误,请回复此电子邮件。谢谢。',
  '\\nSet the organisation name\\n' => '设置组织名称',
  '\\nThe name shown on receipts and donor e-mails (max. 190 characters).\\n' => '收据和捐赠者电子邮件上显示的姓名(最多 190 个字符)。',
  '\\nThe organisation name cannot be empty.\\n' => '组织名称不能为空。',
  '\\nOrganisation name saved:%s\\n' => '已保存组织名称:%s',
  '\\nSet the default currency\\n' => '设置默认货币',
  '\\nUsed for new donation types and manual entries.\\n' => '用于新的捐赠类型和手动输入。',
  '\\nUnsupported currency.\\n' => '不支持的货币。',
  '\\nDefault currency:%s\\n' => '默认货币:%s',
  '\\nOpen a donation type\\n' => '打开捐赠类型',
  '\\nSets a closed donation type that already has a price (or a free amount) to active. Value: the type slug.\\n' => '将已具有价格(或免费金额)的封闭式捐赠类型设置为活动状态。值: 类型段。',
  '\\nThis type has no option with a price and no free amount; set a price first.\\n' => '此类型没有价格选项,也没有免费金额;先定个价格。',
  '\\nDonation type opened:%s\\n' => '打开的捐赠类型:%s',
  '\\nSet a donation type\'s unit price\\n' => '设置捐赠类型的单价',
  '\\nValue "slug=price", e.g. "fidan=150". Every active option gets price × its units (1 sapling 150, 5 saplings 750). Linked forms update automatically.\\n' => '值“slug=价格”,例如“菲丹=150”。每个活跃选项的价格×其单位(1棵树苗150,5棵树苗750)。链接的表单自动更新。',
  '\\nThe price must be greater than 0.\\n' => '价格必须大于 0。',
  '\\nThis type has no active option; add one on the Donation types page.\\n' => '此类型没有活动选项;在“捐赠类型”页面上添加一项。',
  '\\nUnit price of%1$sset to%2$s%3$s.\\n' => '%1$s的单价设置为%2$s%3$s。',
  '\\nLink a form to a donation type\\n' => '将表单链接到捐赠类型',
  '\\nValue "slug=form id", e.g. "fidan=3". Forms:%s\\n' => '值“slug=form id”,例如“菲丹=3”。形式:%s',
  '\\nNo form with this id.\\n' => '没有具有此 ID 的表单。',
  '\\nThe form is already linked.\\n' => '表单已链接。',
  '\\nThe form could not be linked.\\n' => '无法链接该表单。',
  '\\nForm "%1$s" linked to%2$s.\\n' => '表单“%1$s”链接到%2$s。',
  '\\nUse the form "slug=value".\\n' => '使用“slug=value”形式。',
  '\\nNo donation type with this slug.\\n' => '此 slug 没有捐赠类型。',
