  'Daily' => '每日',
  'Weekly' => '每周',
  '\\nYearly\\n' => '每年',
  '\\nTest provider\\n' => '测试提供者',
  'Each line shows something the site needs and whether it is in place. Fix the errors first; warnings are worth a look.' => '每一行都显示站点需要的内容以及它是否到位。首先修复错误;警告值得一看。',
  'OK' => '好的',
  'Warning' => '警告',
  'Error' => '错误',
  'Info' => '信息',
  '%1$d OK · %2$d warnings · %3$d errors' => '%1$d正常 ·%2$d警告 ·%3$d错误',
  'Check again' => '再次检查',
  'Show only these (click again to show all)' => '仅显示这些(再次单击可显示全部)',
  'Checked: %s' => '已检查:%s',
  'Source' => '来源',
  'Action' => '行动',
  'No checks are registered.' => '没有登记任何支票。',
  'System check found %d problem(s) that can stop donations or automations.' => '系统检查发现%d问题,可能会停止捐赠或自动化。',
  'Open system check' => '打开系统检查',
  'Hide until the next update' => '隐藏直到下次更新',
  'System: %d error(s)' => '系统:%d错误',
  'Scheduled tasks (cron)' => '计划任务(cron)',
  'Security' => '安全性',
  '\\n%1$s(%2$s)\\n' => '%1$s(%2$s)',
  '\\nLast test%1$s:%2$s\\n' => '上次测试%1$s:%2$s',
  'WP-Cron mode' => 'WP-Cron 模式',
  '[[\'WP-Cron is turned off in wp-config.php (DISABLE_WP_CRON). That is fine only if a server cron job calls%severy 5–15 minutes; without it recurring charges, retries and other scheduled tasks never run.\\n' => 'WP-Cron 在 wp-config.php (DISABLE_WP_CRON) 中关闭。仅当服务器 cron 作业每 5-15 分钟调用%s时才可以;如果没有它,重复收费、重试和其他计划任务将永远不会运行。',
  '\\nScheduled tasks are running, so a server cron is in place.\\n' => '计划任务正在运行,因此服务器 cron 已就位。',
  '\\nScheduled tasks have not run recently: check the server cron job (Hostinger: hPanel › Advanced › Cron Jobs).\', \'en\']]' => '计划任务最近没有运行:检查服务器 cron 作业(Hostinger:hPanel › 高级 › Cron 作业)。',
  '\\nWP-Cron runs when someone visits the site. On a quiet site tasks can run late; for reliable recurring charges add a server cron job that calls wp-cron.php every 15 minutes and set DISABLE_WP_CRON to true (see KURULUM.md).\\n' => 'WP-Cron 在有人访问该网站时运行。在安静的站点上,任务可能会延迟;为了获得可靠的定期费用,添加一个服务器 cron 作业,每 15 分钟调用一次 wp-cron.php 并将 DISABLE_WP_CRON 设置为 true(请参阅 KURULUM.md)。',
  '\\nALTERNATE_WP_CRON is on.\\n' => 'ALTERNATE_WP_CRON 已打开。',
  '\\nFlux Donate hourly task", \'en\']]' => 'Flux 捐赠每小时任务',
  '\\nLast run:%s. Recurring iyzico charges are checked every hour.\\n' => '上次运行:%s。每小时检查一次 iyzico 重复费用。',
  '\\nNot run yet; the first run is scheduled for%s.\\n' => '尚未运行;第一次运行计划在%s进行。',
  '\\nLast run:%s, more than 2 hours ago.\\n' => '上次运行:%s,超过 2 小时前。',
  '\\nIt has never run.\\n' => '它从未运行过。',
  '\\nWP-Cron is off, so a server cron job must call wp-cron.php. It seems to be missing or failing.\', \'en\']]' => 'WP-Cron 已关闭,因此服务器 cron 作业必须调用 wp-cron.php。它似乎丢失或失败。',
  '\\nWP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.\\n' => 'WP-Cron 仅在访问时运行,可能会被主机或安全插件阻止。使用“测试 cron”或添加服务器 cron 作业。',
  '\\nNext scheduled:%s.\\n' => '下一个计划:%s。',
  '[[\'The task is not scheduled; it is added again on the next page load.\\n' => '任务未安排;它会在下一个页面加载时再次添加。',
  '\\nTest cron\\n' => '测试 cron',
  '\\nOverdue scheduled tasks\\n' => '过期的计划任务',
  '\\n%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.\\n' => '%1$d任务迟到超过 15 分钟:%2$s。%1$d任务延迟超过 15 分钟:%2$s。',
  '\\nA few late tasks right after a quiet period are normal; many mean cron is not running.\\n' => '安静期后出现一些迟到的任务是正常的;许多意味着 cron 没有运行。',
  '\\nNo task is late.\\n' => '没有任务迟到。',
  '\\nCron test\\n' => 'Cron 测试',
  '\\nNot tested. The test asks this server to call wp-cron.php once, as WordPress does after a visit.\\n' => '未测试。该测试要求该服务器调用 wp-cron.php 一次,就像 WordPress 在访问后所做的那样。',
  '\\nCard payment provider\\n' => '卡支付提供商',
  '\\nNo payment provider is available.\\n' => '没有可用的付款提供商。',
  '\\nPayment settings\\n' => '付款设置',
  '\\nCard payments are taken with%s.\\n' => '通过%s进行卡付款。',
  '\\n%sis the active provider but its keys are missing, so donation forms show "Online payment is unavailable".\\n' => '%s是活动提供者,但其密钥丢失,因此捐赠表单显示“在线支付不可用”。',
  '\\nEnter keys\\n' => '输入密钥',
  '\\nKeys are read from the iyzico Subscription plugin settings.\\n' => '密钥是从 iyzico 订阅插件设置中读取的。',
  '\\nKeys are entered in Donations › Payments › iyzico.\\n' => '密钥在捐赠 › 付款 › iyzico 中输入。',
  '[[\'No iyzico API key and secret key found (neither in the iyzico WooCommerce plugin nor in Flux Donate).\\n' => '未找到 iyzico API 密钥和秘密密钥(在 iyzico WooCommerce 插件和 Flux Donate 中均未找到)。',
  '\\nMode: sandbox (test). No real money is collected; switch to live keys before launch.\\n' => '模式:沙箱(测试)。不收取真钱;在启动前切换到实时密钥。',
  '\\nMode: live. Real payments are taken.\\n' => '模式:直播。进行真实付款。',
  '\\nUse "Test connection" to check the keys with iyzico.\\n' => '使用“测试连接”来检查 iyzico 的密钥。',
  '\\niyzico keys\\n' => 'iyzico 键',
  'Test connection' => '测试连接',
  '\\nPaste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url):%s. Subscription notification URLs are not needed.\\n' => '粘贴到 iyzico 面板中 › 商户通知 URL (şyeri Bildirimleri Url):%s。不需要订阅通知 URL。',
  '\\nLast notification received:%s.\\n' => '最后收到的通知:%s。',
  '\\nNo notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).\\n' => '过去 30 天内没有收到任何通知(在地址保存在 iyzico 面板中并付款之前是正常的)。',
  '\\nNotifications for WooCommerce orders are forwarded to the iyzico WooCommerce plugin.\\n' => 'WooCommerce 订单的通知将转发到 iyzico WooCommerce 插件。',
  '\\niyzico notification URL\\n' => 'iyzico 通知 URL',
  '\\nShow addresses\\n' => '显示地址',
  '\\nFailed recurring charges\\n' => '定期收费失败',
  '[[\'%drecurring donation stopped after its card was declined 3 times.\', \'en\']]' . chr(0) . '[[\'%drecurring donations stopped after their cards were declined 3 times.\', \'en\']]' => '%d经常性捐款在其卡被拒绝 3 次后停止。',
  '\\nStripe keys\\n' => '条带键',
  '\\nThe Stripe publishable key and secret key are missing.\\n' => 'Stripe 可发布密钥和秘密密钥丢失。',
  '\\nMode: live.\\n' => '模式:实时。',
  '\\nMode: test (pk_test_). No real money is collected.\\n' => '模式:测试(pk_test_)。没有收集到真正的钱。',
  '\\nWebhook signing secret is set.\\n' => 'Webhook 签名密钥已设置。',
  '\\nWebhook signing secret is missing: refunds and renewals made in Stripe will not show up in Flux Donate.\\n' => 'Webhook 签名密钥丢失:在 Stripe 中进行的退款和续订不会显示在 Flux Donate 中。',
  '\\nFlux Forms is not active. Donation forms and card payments need it.\\n' => 'Flux Forms 未激活。捐赠表格和银行卡付款需要它。',
  '\\nActive, version%s.\\n' => '活动,版本%s。',
  '\\nVersion%1$sis active; Flux Donate needs%2$sor later for payments and prices to work together.\\n' => '版本%1$s已激活; Flux Donate 需要%2$s或更高版本才能使付款和价格协同工作。',
  '\\nActive, version%s. Certificates can be sent after donations.\\n' => '活动,版本%s。捐赠后可发送证书。',
  '\\nVersion%1$sis active;%2$sor later is recommended.\\n' => '版本%1$s已激活;建议使用%2$s或更高版本。',
  '\\nNot active. Donations are recorded, but no certificate is created or sent.\\n' => '未激活。捐赠会被记录,但不会创建或发送任何证书。',
  '\\nWooCommerce is older than%s. Flux Donate 2.0 takes donations through WooCommerce; update it.\\n' => 'WooCommerce 早于%s。 Flux Donate 2.0 通过 WooCommerce 接受捐款;更新它。',
  '\\nWooCommerce is not active. Flux Donate 2.0 takes donations through the WooCommerce cart and checkout; until it is active, only the older Flux Forms payment layer works.\\n' => 'WooCommerce 未激活。 Flux Donate 2.0 通过 WooCommerce 购物车和结帐接受捐款;在其激活之前,只有较旧的 Flux Forms 支付层可以工作。',
  '[[\'The old Flux WooCommerce Bağış plugin is still active. Flux Donate 2.0 replaces it: deactivate and delete it, otherwise orders get two certificates and two messages.\\n' => '旧的 Flux WooCommerce Bağış 插件仍然有效。 Flux Donate 2.0 取代了它:停用并删除它,否则订单将获得两个证书和两条消息。',
  '\\nWooCommerce is active.\\n' => 'WooCommerce 处于活动状态。',
  '\\nThe iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.\\n' => 'iyzico WooCommerce 插件处于活动状态:它需要一次性卡付款,Flux Donate 会读取其 iyzico 密钥以进行每月捐款。',
  '\\nThe iyzico WooCommerce plugin is not active, but its saved keys are still used.\\n' => 'iyzico WooCommerce 插件未激活,但仍使用其保存的密钥。',
  '\\nThe iyzico WooCommerce plugin is not active; Flux Donate uses its own iyzico keys.\\n' => 'iyzico WooCommerce 插件未激活; Flux Donate 使用自己的 iyzico 密钥。',
  '\\nThe iyzico Subscription plugin is active; it renews WooCommerce subscriptions only. Flux Donate recurring donations use their own hourly task.\', \'en\']]' => 'iyzico 订阅插件已激活;它仅续订 WooCommerce 订阅。 Flux Donate 经常性捐赠使用自己的每小时任务。',
  '\\nWooCommerce and iyzico plugins\\n' => 'WooCommerce 和 iyzico 插件',
  '[[\'Open donation types\\n' => '开放捐赠类型',
  '[[\'%ddonation type is open and priced.\', \'en\']]' . chr(0) . '[[\'%ddonation types are open and priced.\', \'en\']]' => '%d捐赠类型开放并定价。',
  '\\nNo donation type is open with a price (or free amount), so forms cannot take donations.\\n' => '没有开放有价格(或免费金额)的捐赠类型,因此表格无法接受捐赠。',
  '\\nForms of open donation types\\n' => '公开捐赠类型的形式',
  '\\nNo (existing) form is linked to:%s. Visitors cannot give to these types online.\\n' => '没有(现有)表单链接到:%s。访问者无法在线向这些类型捐款。',
  '\\nEvery open donation type has a form.\\n' => '每种公开捐赠类型都有一个表格。',
  '\\nDefault currency:%s.\\n' => '默认货币:%s。',
  '\\niyzico is not set up for this currency (Donations › Payments › iyzico › currencies).\\n' => 'iyzico 未设置此货币(捐赠 › 付款 › iyzico › 货币)。',
  '\\nBank accounts (transfer)\\n' => '银行账户(转账)',
  '[[\'%dbank account is listed for bank transfer gifts.\', \'en\']]' . chr(0) . '[[\'%dbank accounts are listed for bank transfer gifts.\', \'en\']]' => '%d银行账户已列出用于银行转账礼物。',
  '\\nNo bank account is listed. They come from the theme (filter flxb_bank_accounts) and are used when recording bank transfer gifts.\\n' => '未列出银行帐户。它们来自主题(过滤器 flxb_bank_accounts),并在记录银行转账礼物时使用。',
  '\\nReceipts and e-mails show "%s".\', \'en\']]' => '收据和电子邮件显示“%s”。',
  '\\nNot set; receipts and e-mails use the site title "%s".\\n' => '未设置;收据和电子邮件使用网站标题“%s”。',
  '[[\'E-mail sending\\n' => '电子邮件发送',
  '\\nNot tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to%s.\\n' => '未测试。捐赠者电子邮件(定期捐赠开始,卡被拒绝)通过 wp_mail 发送。该测试向%s发送一条消息。',
  '\\nSend test e-mail\\n' => '发送测试电子邮件',
  'Permalinks' => '固定链接',
  '\\nPlain permalinks are in use. Payment callbacks still work through ?rest_route=, but some hosts and security plugins block that; choose "Post name".\\n' => '普通固定链接正在使用中。付款回调仍然可以通过 ?rest_route= 工作,但某些主机和安全插件会阻止它;选择“帖子名称”。',
  '\\nPretty permalinks are on; REST callbacks use /wp-json/.\\n' => '漂亮的永久链接已打开; REST 回调使用 /wp-json/。',
  '\\nThe site runs on HTTPS.\\n' => '该网站在 HTTPS 上运行。',
  '\\nLocal test site without HTTPS. The live site must use HTTPS; payment providers refuse plain HTTP.\\n' => '没有 HTTPS 的本地测试站点。直播站点必须使用HTTPS;支付提供商拒绝纯 HTTP。',
  '\\nThe site address is not HTTPS. Card payments and payment callbacks need HTTPS (Settings › General, and an SSL certificate from the host).\\n' => '站点地址不是 HTTPS。卡付款和付款回调需要 HTTPS(设置 › 常规,以及来自主机的 SSL 证书)。',
  'General settings' => '常规设置',
  '\\nWordPress security keys (salts)\\n' => 'WordPress 安全密钥(盐)',
  '\\nMissing or weak in wp-config.php:%s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.\\n' => 'wp-config.php 中缺少或较弱:%s。保存的 iyzico 卡使用这些密钥进行加密;设置唯一值一次(https://api.wordpress.org/secret-key/1.1/salt/),之后不要更改它们,否则保存的卡将停止工作。',
  '\\nSet in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.\\n' => '在 wp-config.php 中设置。已保存的 iyzico 卡已使用它们加密:请勿更改它们,否则已保存的卡将停止工作。',
  'Database tables' => '数据库表',
  '\\nUp to date (%s).\\n' => '最新 (%s)。',
  '\\nTables are at version%1$s, expected%2$s. Deactivate and activate Flux Donate to update them.\\n' => '表的版本为%1$s,预计为%2$s。停用并激活 Flux Donate 来更新它们。',
  '\\nNo iyzico keys to test.\\n' => '没有要测试的 iyzico 键。',
  '\\nsandbox\\n' => '沙箱',
  '\\nConnected; iyzico accepted the keys (%s).\\n' => '已连接; iyzico 接受了密钥 (%s)。',
  '\\niyzico refused the keys (%1$s):%2$s. Check that the keys belong to this environment.\\n' => 'iyzico 拒绝了密钥 (%1$s):%2$s。检查密钥是否属于此环境。',
  '\\nThis server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.\\n' => '此服务器无法访问其自己的 wp-cron.php (%s)。 WP-Cron无法从访问开始;添加服务器 cron 作业。',
  '\\nwp-cron.php answered; WP-Cron can start.\\n' => 'wp-cron.php 回答; WP-Cron 可以启动。',
  '\\nwp-cron.php answered with HTTP%d(blocked by the host or a security plugin?). Add a server cron job.\\n' => 'wp-cron.php 用 HTTP%d应答(被主机或安全插件阻止?)。添加服务器 cron 作业。',
  '\\n[%s] Test e-mail from Flux Donate\\n' => '[%s] 来自 Flux Donate 的测试电子邮件',
  '\\nThis is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.\\n' => '这是来自捐赠 › 设置 › 系统检查的测试。如果您能阅读,则可以发送捐赠者电子邮件。',
  '\\nSent to%s. Check that it arrived (and not in spam).\\n' => '发送到%s。检查它是否已到达(并且不在垃圾邮件中)。',
  '\\nSending failed:%s. Set up SMTP (e.g. an SMTP plugin with your mail account).\\n' => '发送失败:%s。设置 SMTP (例如使用您的邮件帐户的 SMTP 插件)。',
  'unknown error' => '未知错误',
  '[[\'Donations on WooCommerce: donation types and sapling packages sold as hidden products, cart and checkout (iyzico, bank transfer with receipt upload), monthly donations, online and printed certificates, donors, campaigns and a donation dashboard. Includes Flux WooCommerce Bağış.\', \'en\']]' => 'WooCommerce 上的捐赠:捐赠类型和作为隐藏产品出售的树苗包、购物车和结帐(iyzico、带有收据上传的银行转账)、每月捐赠、在线和打印证书、捐赠者、活动和捐赠仪表板。包括 Flux WooCommerce Bağış。',
  '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' . chr(0) . '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' => '%1$s捐赠 ·%2$s收到%1$s捐赠 ·%2$s收到',
  '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' . chr(0) . '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' => '%1$s付费礼物 ·%2$s%1$s付费礼物 ·%2$s',
  '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' . chr(0) . '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' => '%d活动类型具有其隐藏的 WooCommerce 产品。%d活动类型具有隐藏的 WooCommerce 产品。',
  '\\n%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.\\n' . chr(0) . '\\n%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.\\n' => '%1$d任务迟到超过 15 分钟:%2$s。%1$d任务延迟超过 15 分钟:%2$s。',
  '\\n%srecurring donation could not be charged through iyzico after all attempts and is now past due. The donor was e-mailed.\\x00%srecurring donations could not be charged through iyzico after all attempts and are now past due. The donors were e-mailed.\\n' => '%s经常性捐款在经过所有尝试后仍无法通过 iyzico 收取,现已过期。捐赠者已通过电子邮件发送。',
  '\\n%sdonor\\x00%sdonors\\n' => '%s捐助者',
  '\\nand%smore\\x00and%smore\\n' => '还有%s更多',
  '\\nImport%srow\\x00Import%srows\\n' => '导入%s行',
  '\\n%sdonation moved to the trash.\\x00%sdonations moved to the trash.\\n' => '%s捐款已移至垃圾桶。',
  '\\n%sdonation restored.\\x00%sdonations restored.\\n' => '%s捐款已恢复。',
