  '\\n%ditem updated.\\x00%ditems updated.\\n' => '%d项目已更新。',
  '\\n%srecord\\x00%srecords\\n' => '%s记录',
  '\\n%dwithout a price\\x00%dwithout a price\\n' => '%d无价格',
  '\\nUsed by%stype\\x00Used by%stypes\\n' => '由%s类型使用',
  '\\n%dfield\\x00%dfields\\n' => '%d字段',
  '\\n%srecurring donation\\x00%srecurring donations\\n' => '%s经常性捐款',
  '\\nPlease write at most%sname (one per share).\\x00Please write at most%snames (one per share).\\n' => '请最多写入%s名称(每个共享一个)。',
  '\\nYour certificate is ready\\x00Your certificates are ready\\n' => '您的证书已准备好',
  '\\nDonation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\\x00Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.\\n' => '%1$s树苗捐赠。%2$s会为您种植它们,并以您的名义发送在线证书。通过卡或银行转帐付款。',
  '\\n%sSapling\\x00%sSaplings\\n' => '%s树苗',
