  'They belong to iyzico\'s own subscription product; Flux Donate renews recurring donations with the saved card and its own scheduled task.' => '它们属于iyzico自己的订阅产品; Flux Donate 使用保存的卡片及其自己的计划任务续订定期捐赠。',
  'Callback URL (sent automatically with every payment, nothing to paste):' => '回调 URL(每次付款时自动发送,无需粘贴):',
  'The iyzico WooCommerce plugin has a webhook key on this site: notifications that are not for Flux Donate are forwarded to it.' => 'iyzico WooCommerce 插件在此站点上有一个 webhook 密钥:不适用于 Flux Donate 的通知将转发给它。',
