  'With "popup" the donor returns to the open form and the form is sent as usual. When the browser blocks the popup, the same tab is used.' => '通过“弹出”,捐赠者返回到打开的表格,并且表格照常发送。当浏览器阻止弹出窗口时,将使用相同的选项卡。',
  'Other currencies' => '其他货币',
