  'If iyzico does not return a stored card for the first payment of a recurring gift, it cannot be charged again.' => '如果 iyzico 没有退回用于首次支付定期礼物的存储卡,则无法再次扣费。',
  'Read from the iyzico WooCommerce plugin (WooCommerce › Settings › Payments › iyzico). Values here are used only when that plugin has no keys.' => '从 iyzico WooCommerce 插件读取(WooCommerce › 设置 › 付款 › iyzico)。仅当该插件没有键时才使用此处的值。',
  'Read from the iyzico WooCommerce Subscription plugin. Values here are used only when it has no keys.' => '从 iyzico WooCommerce 订阅插件读取。仅当没有键时才使用此处的值。',
  'You will enter your card on iyzico\'s secure payment page. It opens in a new window when you press Pay.' => '您将在 iyzico 的安全支付页面上输入您的卡。当您按“付款”时,它将在新窗口中打开。',
