  'Delete this agreement? Items already sent keep their price.' => '删除此协议?已发送的商品保持原价。',
  'Donation type and option' => '捐赠类型和选项',
  'all options' => '所有选项',
  'Add agreement' => '添加协议',
  '%s (cost)' => '%s(成本)',
  'Brought in (gift price)' => '带进来(礼金价)',
  'All partners' => '所有合作伙伴',
  'Gift price' => '礼品价格',
  '%d without a price' . chr(0) . '%d without a price' => '%d无价格',
  'Re-read prices from the agreements' => '重新读取协议中的价格',
  'Donations, donors and recurring gifts at a glance.' => '捐款、捐助者和经常性礼物一目了然。',
  'Custom' => '自定义',
  'The dashboard needs JavaScript.' => '仪表板需要 JavaScript。',
  'Sorry, you are not allowed to do that.' => '抱歉,您不能这样做。',
  'Tracking' => '跟踪',
  'Extra tabs' => '额外选项卡',
  'Settings sections' => '设置部分',
  'Default currency' => '默认货币',
  'Turkish lira (₺)' => '土耳其里拉 (₺)',
  'Euro (€)' => '欧元 (€)',
  'US dollar ($)' => '美元 ($)',
  'Pound sterling (£)' => '英镑 (£)',
  'Dashboard totals are in this currency; gifts in other currencies are listed but not added to the totals.' => '仪表板总计以该货币表示;其他货币的礼物会列出,但不会添加到总数中。',
  'Tracking module' => '跟踪模块',
  'Chosen donation types get one item per unit with a code, sent to partners (with agreed prices and settlement), files and history. Leave it off if you do not need it.' => '选定的捐赠类型每单位获得一件带有代码的物品,发送给合作伙伴(具有商定的价格和结算)、文件和历史记录。如果不需要,请将其关闭。',
  'A Reports screen with editable JSON reports (always on with the tracking module).' => '带有可编辑 JSON 报告的报告屏幕(始终与跟踪模块一起打开)。',
  'Gifts on behalf of a person' => '代表某人的礼物',
  'Adds a proxy (vekâlet) text the donor accepts, intentions and one item per unit with the name of the person it is given for. Turns tracking on too.' => '添加捐赠者接受的代理 (vekâlet) 文本、意图以及每个单位的一个项目,其中包含捐赠者的姓名。也打开跟踪。',
  'Which payments are donations?' => '哪些付款属于捐赠?',
  'Every payment taken through a Flux Forms form' => '通过 Flux Forms 表格进行的每笔付款',
  'Only payments through the forms selected below (and forms linked to a donation type)' => '仅通过下面选择的表格(以及链接到捐赠类型的表格)进行付款',
  'How donations are recorded' => '如何记录捐款',
  'A donation is stored when a Flux Forms payment is completed: at the final form submission (with name, phone and e-mail from the form), from the payment provider\'s notifications (refunds, renewals of recurring gifts) and by an hourly check that catches payments whose form was not submitted.' => '当 Flux Forms 付款完成时,捐款将被存储:最终表单提交时(包含表单中的姓名、电话和电子邮件)、支付提供商的通知(退款、经常性礼物的续订)以及每小时检查未提交表单的付款。',
  'Donors are matched on phone number or e-mail address, never on name alone.' => '捐赠者通过电话号码或电子邮件地址进行匹配,而不仅仅是姓名。',
  'Shown on receipts, donation pages and in exports. Empty fields fall back to the site name, the theme logo and the theme colours.' => '显示在收据、捐赠页面和导出中。空字段会回退到站点名称、主题徽标和主题颜色。',
  'Organisation name' => '组织名称',
  'Choose a logo' => '选择徽标',
  'Brand colour' => '品牌颜色',
  'Hex colour such as #1F2937. Empty = the theme\'s primary colour.' => '十六进制颜色,例如#1F2937。空 = 主题的原色。',
  'Receipt text' => '收据文本',
  'A thank-you note printed on the donation receipt.' => '捐款收据上印有感谢信。',
  'Footer text' => '页脚文本',
  'Address, registration number, bank details and similar; printed at the bottom of receipts.' => '地址、注册号、银行详细信息及类似信息;打印在收据底部。',
  'Donation type categories' => '捐赠类型类别',
  'Group donation types, e.g. Kurban, Ramazan, General. The key is stored on the types; a category that is in use cannot be removed.' => '团体捐赠类型,例如牺牲,斋月,将军。密钥存储在类型上;无法删除正在使用的类别。',
  'Save categories' => '保存类别',
  'Used by %s type' . chr(0) . 'Used by %s types' => '由%s类型使用',
  'Remove category' => '删除类别',
  'The words on the tracking screens. A donation type can use its own words (Donation types › Tracking); empty fields use these, and empty ones here the built-in words.' => '跟踪屏幕上的文字。捐赠类型可以使用自己的词语(捐赠类型 › 跟踪);空字段使用这些,空字段使用内置单词。',
  'Early days' => '早期',
  'How many days before the target date an item may already be done. After the target day it is still allowed, but shown as late.' => '在目标日期之前多少天某个项目可能已经完成。在目标日期之后,仍然允许,但显示为迟到。',
  'Proxy (vekâlet) text' => '代理 (vekâlet) 文本',
  'The text a donor accepts to authorise the organisation to give on their behalf. Every change is saved as a new version; each donation keeps the version that was accepted.' => 'The text a donor accepts to authorise the organisation to give on their behalf.每次更改都会保存为新版本;每次捐赠都会保留已接受的版本。',
  'Who items are sent to, their agreed prices and payments are kept under Donations › Partners.' => '物品发送给谁,其商定的价格和付款保存在捐赠 › 合作伙伴下。',
  'Proxy text versions' => '代理文本版本',
  'No text yet. Donations of types that require a proxy cannot be paid until a text is saved.' => '还没有文字。在保存文本之前,无法支付需要代理的类型的捐赠。',
  'Version %1$s · %2$s' => '版本%1$s·%2$s',
  'Add your own tabs with fields to tracked records ("on": "item") or donations ("on": "donation"), for all or some donation types. Leave it empty if you do not need any.' => '为所有或某些捐赠类型添加您自己的带有字段的选项卡,以跟踪记录(“on”:“item”)或捐赠(“on”:“donation”)。如果不需要,请将其留空。',
  'Tabs (JSON list)' => '选项卡(JSON 列表)',
  'Tabs in use' => '正在使用的选项卡',
  'Record page' => '记录页面',
  '%d field' . chr(0) . '%d fields' => '%d字段',
  'from a plugin' => '来自插件',
  'No extra tabs yet.' => '还没有额外的选项卡。',
  'Reads completed payments stored by Flux Forms and adds the missing ones as donations. Safe to run more than once: a payment is never imported twice.' => '读取 Flux Forms 存储的已完成付款,并将缺失的付款添加为捐款。可以安全运行多次:付款绝不会导入两次。',
  'Flux Forms\'s payment table was not found. Is Flux Forms installed?' => '未找到 Flux Forms 的付款表。是否安装了 Flux Forms?',
  'Importing…' => '正在导入...',
  'Import now' => '立即导入',
  'Last run %1$s: %2$s payments checked, %3$s imported.' => '上次运行%1$s:检查%2$s付款,导入%3$s。',
  'Upcoming (%s)' => '即将推出 (%s)',
  'New donation type' => '新的捐赠类型',
  'Donation types and campaigns' => '捐赠类型和活动',
  'What people can give for: each type has its own prices and options, dates, goal and linked forms.' => '人们可以付出什么:每种类型都有自己的价格和选项、日期、目标和链接表格。',
  'Open and closed' => '打开和关闭',
  'The archive is empty' => '存档为空',
  'No donation types yet' => '尚无捐赠类型',
  'Create a type such as a general donation, a sapling or a kurban share, set its prices, and link the forms that collect for it.' => '创建一个类型,例如一般捐赠、树苗或库尔班份额,设置其价格,并链接为其收集的表格。',
  'No category' => '没有类别',
  '(inactive)' => '(无效)',
  '(price not set)' => '(价格未定)',
  'free amount (min. %s)' => '免费金额(最少%s)',
