  'quantity' => '数量',
  'recurring' => '重复',
  '%1$s of %2$s (%3$s%%)' => '%1$s或%2$s(%3$s%%)',
  'Open-ended' => '开放式',
  'Load sample types' => '加载样本类型',
  'Adds ready-made types and categories that you can edit. Types whose sample price is 0 start closed until you set their prices.' => '添加您可以编辑的现成类型和类别。样本价格为 0 的类型开始关闭,直到您设置其价格。',
  'Sample set' => '样本集',
  'Donation type not found' => '未找到捐赠类型',
  'Edit donation type' => '编辑捐赠类型',
  'Edit categories' => '编辑类别',
  'Slug' => '子弹',
  'Optional; created from the title.' => '可选;根据标题创建。',
  'Prices and the goal are in this currency. A linked form must charge in the same currency, otherwise its payments are stopped.' => '价格和目标均以该货币表示。链接的表单必须以相同的货币收费,否则其付款将停止。',
  'Sheep' => '羊',
  'Camel' => '骆驼',
  'Card subtitle' => '卡片副标题',
  'One short line under the title on the type cards, e.g. "Sheep or goat".' => '类型卡标题下有一条短线,例如“绵羊或山羊”。',
  'Shown when the type has no image.' => '当类型没有图像时显示。',
  'Choose an image' => '选择图像',
  'Prices and options' => '价格和选项',
  'One option is a fixed price per unit (e.g. one sapling). Several options give the donor a choice (e.g. adak, akika, şifa). The amount charged is always computed on the server from these prices.' => '一个选项是每单位的固定价格(例如一棵树苗)。捐赠者有多种选择(例如adak、akika、şifa)。收费金额始终根据这些价格在服务器上计算。',
  'A price of 0 means the price is not announced yet: the option is shown but cannot be paid. An inactive option is hidden and cannot be paid.' => '价格为 0 表示价格尚未公布:选项已显示但无法支付。不活动的选项被隐藏并且无法支付。',
  'Free amount allowed' => '允许免费金额',
  'Minimum amount' => '最低金额',
  'Quantity allowed' => '允许数量',
  'Maximum quantity' => '最大数量',
  'Empty = no limit.' => '空 = 无限制。',
  'Recurring giving allowed' => '[[“允许重复捐赠',
  'Linked forms' => '链接表单',
  'Gifts through these Flux Forms forms count for this type. Map each priced choice of the form to an option: the form then charges the price set here.' => '通过这些 Flux Forms 形式提供的礼物属于此类型。将表单的每个定价选择映射到一个选项:然后表单按此处设置的价格收费。',
  'No payment form found in Flux Forms yet.' => '尚未在 Flux Forms 中找到付款表单。',
  'also linked to: %s' => '还链接到:%s',
  'Save after choosing a form to map its choices.' => '选择表单后保存以映射其选择。',
  'Hide the choice in the form when it was preselected' => '预选时隐藏表单中的选项',
  'When the page passes a choice (flxb_opt in the address or FLXB.preselect()), the form shows a short summary with a "Change" link instead of the choice list.' => '当页面传递选择(地址中的 flxb_opt 或 FLXB.preselect())时,表单会显示带有“更改”链接的简短摘要,而不是选择列表。',
  'A closed type keeps its history but its forms no longer take payments.' => '封闭类型保留其历史记录,但其表单不再接受付款。',
  'End date' => '结束日期',
  'Goal amount' => '目标金额',
  'Optional. Shown as a progress bar.' => '可选。显示为进度条。',
  'Show it on the site' => '在网站上显示',
  'Add baslik="hayir" to hide the title and description.' => '添加 baslik="hayir" 以隐藏标题和说明。',
  'Delete this donation type' => '删除此捐赠类型',
  'Delete this donation type?' => '删除此捐赠类型吗?',
  'This type has gifts, so it can be archived but not deleted.' => '此类型有礼物,因此可以存档但不能删除。',
  'Option name' => '选项名称',
  'e.g. Sapling, Adak, Iftar' => 'e.g.树苗、埃达克、开斋',
  'from the name' => '从名字来看',
  'Remove option' => '删除选项',
  '— not set' => '— 未设置',
  'Units per choice' => '每个选择的单位',
  'e.g. a whole animal = 7 shares' => 'e.g.一整只动物 = 7 份',
  'not offered' => '未提供',
  'Translations' => '翻译',
  'Shown on the donation page, the cart and the checkout in that language (Flux Lang). Empty fields use the texts above. Records keep the texts above. Save once after adding options to translate their names.' => '以该语言 (Flux Lang) 显示在捐赠页面、购物车和结帐处。空字段使用上面的文本。记录保留上述文字。添加翻译名称的选项后保存一次。',
  'Option: %s' => '选项:%s',
  'Each unit of a gift becomes its own item with a 7-digit code: approved, sent to a partner, completed, delivered to the owner, with files and history.' => '礼物的每个单元都成为带有 7 位数代码的自己的物品:批准、发送给合作伙伴、完成、交付给所有者,并带有文件和历史记录。',
  'Track every unit one by one' => '一一跟踪每个单元',
  'Always on for gifts given on behalf of a person.' => '代表某人赠送礼物时始终打开。',
  'The first file marks it completed' => '第一个文件将其标记为已完成',
  'Words for this type' => '此类型的单词',
  'On behalf of a person' => '代表某人',
  'For types given on behalf of a named person: each unit becomes its own item with that person\'s name, and the donor must accept the proxy (vekâlet) text.' => '对于代表指定人物给出的类型:每个单位都成为带有该人姓名的自己的项目,并且捐赠者必须接受代理 (vekâlet) 文本。',
  'Proxy (vekâlet) required' => '需要代理 (vekâlet)',
  'Animal' => '动物',
  'Cattle (7 shares)' => '牛(7股)',
  'All of the meat goes to people in need' => '所有的肉都送给有需要的人',
  'Mapping for “%s”' => '映射“%s”',
  'This form charges in %1$s but the donation type is in %2$s: its payments are stopped until both use the same currency.' => '此表单以%1$s收费,但捐赠类型为%2$s:其付款将停止,直到两者使用相同的货币。',
  'This form has no priced choices to map.' => '此表单没有可供映射的价格选择。',
  'Form choice' => '表单选择',
  'Units' => '单位',
  'form price: %s' => '表格价格:%s',
  'Not mapped (form price)' => '未映射(形成价格)',
  'Quantity field' => '数量字段',
  'Free amount field' => '免费金额字段',
  'On behalf of (names field)' => '代表(名称字段)',
  'One name per line. Units without a name are given on behalf of the donor.' => '每行一个名称。没有名字的单位是代表捐赠者提供的。',
  'Proxy consent field' => '代理同意字段',
  'Monthly, weekly or yearly gifts charged automatically by the payment provider.' => '支付提供商自动收取每月、每周或每年的礼物费用。',
  'Name, e-mail, phone, reference…' => '姓名、电子邮件、电话、参考...',
  'No recurring donations yet' => '尚无经常性捐款',
  'A recurring donation is created when a payment form is set to charge every day, week, month or year.' => '当付款表单设置为每天、每周、每月或每年收费时,就会创建定期捐款。',
  '%s recurring donation' . chr(0) . '%s recurring donations' => '%s经常性捐款',
  'Interval' => '间隔',
  'Next charge' => '下次充电',
  'Attempt %1$s of %2$s failed: %3$s' => '尝试%1$s或%2$s失败:%3$s',
  'canceled %s' => '已取消%s',
  'Cancel this recurring donation at the payment provider? No further charges will be made.' => '在支付提供商处取消此定期捐赠吗?不会再收取任何费用。',
  'Card payments: the official iyzico plugin is enabled.' => '刷卡支付:已启用官方 iyzico 插件。',
  'Card payments: Flux Donate iyzico (the official iyzico plugin is not enabled).' => '卡支付:Flux Donate iyzico(未启用官方 iyzico 插件)。',
  'Card payments: %s.' => '卡付款:%s。',
  'No card method is enabled (WooCommerce › Settings › Payments).' => '未启用银行卡方式(WooCommerce › 设置 › 付款)。',
  'Monthly donations: Flux Donate iyzico is ready.' => '每月捐赠:Flux Donate iyzico 已准备就绪。',
  'Monthly donations are off: enable "Card (iyzico) - Flux Donate" and enter iyzico keys.' => '每月捐赠已关闭:启用“卡 (iyzico) - Flux 捐赠”并输入 iyzico 密钥。',
  'Bank transfer (donations) is enabled.' => '银行转账(捐赠)已启用。',
  'Bank transfer (donations) is disabled.' => '银行转账(捐赠)已禁用。',
  'Flux Certificates is connected.' => 'Flux 证书已连接。',
  'Flux Certificates is active but has no active template.' => 'Flux 证书处于活动状态,但没有活动模板。',
  'Flux Certificates is not active: no certificate is made after payment.' => 'Flux 证书未激活:付款后未颁发证书。',
  'Donation page:' => '捐赠页面:',
  'The donation options are not on a page yet.' => '页面上还没有捐赠选项。',
  'WooCommerce is not active. Donations are paid through WooCommerce from version 2.0: install and activate WooCommerce.' => 'WooCommerce 未激活。从 2.0 版开始,捐款通过 WooCommerce 支付:安装并激活 WooCommerce。',
  'Sapling packages, prices and badges are edited on the donation type (Donations › Donation types). Which types give a certificate is set there too.' => '树苗包、价格和徽章是根据捐赠类型(捐赠 › 捐赠类型)编辑的。哪些类型提供证书也在那里设置。',
  'Automatic ("Fidan Bağış Sertifikası")' => '自动(“Fidan Bağış Sertifikası”)',
  'When chosen, online donation certificates count for this open event.' => '选择后,在线捐赠证书将计入此公开活动。',
  'Send by' => '发送者',
  'When the payment is confirmed the certificate link goes out on these channels. With a WhatsApp route no SMS is sent.' => '付款确认后,证书链接将在这些渠道上消失。通过 WhatsApp 路由,不会发送短信。',
  '"Online + printed certificate"' => '“在线+打印证书”',
  'Shown as "Coming soon" (cannot be chosen)' => '显示为“即将推出”(无法选择)',
  'Can be chosen' => '可以选择',
  'Printed certificate fee (per line)' => '打印证书费用(每行)',
  '0 = free. Orders with a printed certificate stay "Processing"; set them to "Completed" when sent.' => '0 = 免费。带有打印证书的订单仍处于“处理中”状态;发送时将其设置为“已完成”。',
  'Complete paid orders with an online certificate automatically' => '自动使用在线证书完成支付订单',
  'IBAN, recipient and reference code: WooCommerce › Settings › Payments › Bank transfer (donations). The transfer details and the receipt link are added to WooCommerce\'s "on hold" e-mail.' => 'IBAN、收件人和参考代码:WooCommerce › 设置 › 付款 › 银行转账(捐赠)。转账详细信息和收据链接将添加到 WooCommerce 的“暂停”电子邮件中。',
  'Short notification' => '简短通知',
  'A short message to the donor\'s phone when a transfer is registered (through Flux Mail, or Flux Certificates\'s providers). With both ticked, SMS only goes out when there is no WhatsApp route.' => '注册转账时(通过 Flux Mail 或 Flux 证书提供商)向捐赠者的手机发送一条短信。勾选两者后,只有在没有 WhatsApp 路由时才会发出短信。',
  'WhatsApp text' => 'WhatsApp 文本',
  'Placeholders: {ad} {tutar} {siparis} {alici} {iban} {aciklama} {link} {site}' => '占位符:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}',
  'SMS text' => '短信',
  'Largest receipt file (MB)' => '最大收据文件 (MB)',
  'Tell this address when a receipt is uploaded' => '上传收据时告知此地址',
  'After "Donate"' => '“捐赠”之后',
  'Go straight to the checkout' => '直接去结账',
  'Go to the cart' => '转到购物车',
  'Stay on the page' => '留在页面上',
  'Currencies donors can choose' => '货币捐赠者可以选择',
  '(store currency)' => '(存储货币)',
  'With more than one, donors pick the currency (shortcode [flx_bagis_para_birimi] or the theme). There are no exchange rates: set each option\'s price per currency on the donation type; options without a price in a currency are not offered in it. Check that your payment methods take these currencies.' => '如果有不止一种货币,捐赠者可以选择货币(简码 [flx_bagis_para_birimi] 或主题)。没有汇率:在捐赠类型上设置每个选项的每种货币的价格;其中不提供没有货币价格的期权。检查您的付款方式是否支持这些货币。',
  'Do not ask for an address at the checkout when the cart holds only donations' => '当购物车仅装有捐款时,请勿在结帐时询问地址',
  'Support WhatsApp number' => '支持 WhatsApp 号码',
  'Shown at the checkout and with the bank transfer details as "Any trouble? Write to us on WhatsApp". Leave empty to hide.' => '结账时显示,银行转账详细信息显示为“有任何问题吗?通过 WhatsApp 给我们写信”。留空以隐藏。',
  '— Choose —' => '— 选择—',
  '"Donate" links and the hidden product pages go here.' => '“捐赠”链接和隐藏的产品页面位于此处。',
  'Card payment method' => '银行卡付款方式',
  'Automatic: another virtual POS if one is enabled (e.g. EsnekPOS), otherwise iyzico' => '自动:另一个虚拟 POS(如果已启用)(例如 EsnekPOS),否则为 iyzico',
  'iyzico' => 'iyzico',
  'Show every enabled card method' => '显示每个启用的卡方法',
  'Donors see one card method; now: %s. Monthly donations always use Flux Donate iyzico (it stores the card). Bank transfer is always shown.' => '捐助者见一卡法;现在:%s。每月捐款始终使用 Flux Donate iyzico(它存储卡)。始终显示银行转帐。',
  'all' => '全部',
  'Show other payment plugins on the checkout block' => '在结账栏显示其他支付插件',
  'Virtual POS plugins that take the card on their own page but have no checkout block support (for example EsnekPOS) are added to the Checkout block. Plugins with their own card fields need the classic checkout.' => '在自己的页面上使用卡但不支持结帐块的虚拟 POS 插件(例如 EsnekPOS)将添加到结帐块中。具有自己的卡字段的插件需要经典的结帐。',
  'Flux Forms payment forms continue on the WooCommerce checkout' => 'Flux Forms 付款表格在 WooCommerce 结帐时继续',
  'The donor picks card or bank transfer there; the form entry, the certificate automation and the donation record are completed when the order is paid.' => '捐赠者在那里领取卡或银行转账;订单支付时,表单录入、证书自动化和捐赠记录完成。',
  'Card payment screen' => '卡支付屏幕',
  'Our own card fields on the checkout (3D Secure, installments, saved cards)' => '结帐时我们自己的卡字段(3D Secure、分期付款、保存的卡)',
  'iyzico payment page (as before)' => 'iyzico 付款页面(和以前一样)',
  'Official iyzico plugin for one-time donations' => '用于一次性捐赠的官方 iyzico 插件',
  'Card numbers go straight to iyzico and are never stored on this site. Monthly donations always use Flux Donate iyzico (it stores the card).' => '卡号直接进入 iyzico,并且绝不会存储在该网站上。每月捐款始终使用 Flux Donate iyzico(它存储卡)。',
  'Most installments' => '大部分分期付款',
  'Single payment only' => '[[“仅限单次付款',
  'With our own card fields. The options and any interest come from iyzico for each card.' => '用我们自己的卡字段。每张卡的选项和任何利息均来自 iyzico。',
  'Add the "Donation options" block to any page, or create a ready page:' => '将“捐赠选项”块添加到任何页面,或创建一个就绪页面:',
  'Create the online donation page' => '创建在线捐赠页面',
  'Product list (XML)' => '产品列表 (XML)',
  'For iyzico "upload your products with XML" and Google Merchant Center. Every fixed-price option on sale is one product; free amounts are left out. Updating daily is enough.' => '对于 iyzico“使用 XML 上传您的产品”和 Google Merchant Center。销售的每个固定价格选项都是一种产品;免费金额被忽略。每天更新就足够了。',
  'Shortcode and block' => '短代码和块',
  'Without attributes it shows the donation types marked "Show in the Donation options block". tur="slug1,slug2" shows only those types; sekme="slug" opens that type\'s tab first. In the editor: "Donation options" block.' => '如果没有属性,它会显示标记为“在捐赠选项块中显示”的捐赠类型。 tur="slug1,slug2" 仅显示这些类型; sekme="slug" 首先打开该类型的选项卡。在编辑器中:“捐赠选项”块。',
  'Choose a sapling package or give any amount you like. You can pay by card or bank transfer; a certificate is made in your name.' => '选择一个树苗包或提供任何您喜欢的数量。您可以通过银行卡或银行转账方式支付;证书将以您的名义制作。',
  'Online donation page' => '在线捐款页面',
  'How this type appears in the "Donation options" block and the WooCommerce cart. Its hidden WooCommerce product is kept in step automatically.' => '此类型如何显示在“捐赠选项”块和 WooCommerce 购物车中。其隐藏的 WooCommerce 产品会自动保持同步。',
  'Show in the "Donation options" block (donation page) and the product XML' => '在“捐赠选项”块(捐赠页面)和产品 XML 中显示',
  'Give a certificate (Flux Certificates)' => '提供证书(Flux 证书)',
  'Same as the WooCommerce settings' => '与 WooCommerce 设置相同',
  'Option with a − / + quantity' => '带有 - / + 数量的选项',
  'This option\'s card gets − / + buttons (e.g. "1 sapling"); price = number × this option\'s price, checked again on the server. The other options stay fixed packages. Use "Maximum quantity" above for the limit.' => '此选项的卡片有 - / + 按钮(例如“1 棵树苗”);价格=数量×该选项的价格,在服务器上再次检查。其他选项保持固定套餐。使用上面的“最大数量”作为限制。',
  'Preset amounts (free amount)' => '预设金额(免费金额)',
  'Separated by spaces, e.g. 250 500 1000.' => '用空格分隔,例如250 500 1000。',
  'Preset amounts in %s' => '%s中的预设金额',
  'Page address' => '页面地址',
  'Optional: where its product page and the product XML link go. Empty = the donation page in the WooCommerce settings.' => '可选:产品页面和产品 XML 链接所在的位置。空 = WooCommerce 设置中的捐赠页面。',
  'WooCommerce product #%d (hidden from the shop).' => 'WooCommerce 产品 #%d(在商店中隐藏)。',
  'This order has no donation line.' => '此订单没有捐赠热线。',
  'Donation records:' => '捐赠记录:',
  'Reference code:' => '参考代码:',
  'Make the certificate' => '制作证书',
  'Refund this amount to the donor\'s card?' => '将此金额退还到捐赠者的卡上吗?',
  'Record this refund? The money is not sent back automatically for this payment method.' => '记录这笔退款吗?对于此付款方式,资金不会自动退回。',
  'Record refund' => '记录退款',
  'Refunded through WooCommerce and the payment method; the record follows.' => '通过 WooCommerce 和付款方式退款;记录如下。',
  'Recorded in WooCommerce only: send the money back yourself (e.g. by bank transfer).' => '仅在 WooCommerce 中记录:自行将钱汇回(例如通过银行转帐)。',
  'Order line not found.' => '未找到订单行。',
  'Enter an amount up to what is left to refund.' => '输入剩余退款金额。',
  'Refunded from Flux Donate by %s' => '从%s的 Flux 捐赠中退还',
  'No donation lines.' => '没有捐赠热线。',
  'Unknown donation type.' => '未知的捐赠类型。',
  'The donation product could not be created.' => '无法创建捐赠产品。',
  'Recorded in Flux Chat (donation #%d).' => '记录在 Flux 聊天中(捐赠 #%d)。',
  'Canceled in Flux Donate.' => '在通量捐赠中取消。',
  'Put on hold in Flux Donate.' => '暂停通量捐赠。',
  'Marked as failed in Flux Donate.' => '在 Flux Donate 中标记为失败。',
  'This payment link has expired. Please fill in the form again.' => '此付款链接已过期。请重新填写表格。',
  'Flux Forms entry %s completed by this payment.' => '本次付款已完成通量表格条目%s。',
  'After you place the order you will see the IBAN and your own reference code. Once you have paid you can upload the receipt on the site; your certificate is sent when the payment is confirmed.' => '下订单后,您将看到 IBAN 和您自己的参考代码。付款后,您可以在网站上上传收据;确认付款后将发送您的证书。',
  'Your pre-registration is in' => '您的预注册时间为',
  'To complete your donation, make a bank transfer to the account below. Please write your own reference code in the description.' => '要完成捐赠,请通过银行转帐至以下帐户。请在描述中写下您自己的参考代码。',
  'The reference code lets us match your payment to your donation.' => '参考代码让我们能够将您的付款与您的捐款进行匹配。',
  'Receive your certificate' => '收到您的证书',
  'Once the payment is confirmed your certificate is sent by WhatsApp and e-mail; it also appears under My account › Orders.' => '付款确认后,您的证书将通过 WhatsApp 和电子邮件发送;它还显示在我的帐户 › 订单下。',
  'We confirm your donation' => '我们确认您的捐赠',
  'Once the payment is confirmed the order is completed and you get an e-mail; it also appears under My account › Orders.' => '付款确认后,订单完成,您会收到一封电子邮件;它还显示在我的帐户 › 订单下。',
  'My pending donations' => '我的待处理捐款',
  'Card number' => '卡号',
  'Name on the card' => '卡上的姓名',
  'Expiry (MM/YY)' => '到期 (MM/YY)',
  'card expiry placeholderMM/YY' => '月/年',
  'CVC' => 'CVC',
  'Save my card for next time' => '保存我的卡以供下次使用',
  'iyzico keeps the card; this site never stores card numbers.' => 'iyzico 保留该卡;此站点从不存储卡号。',
  'For the monthly donation iyzico keeps your card and charges it once a month. You can cancel at any time.' => '对于每月捐款,iyzico 会保留您的卡并每月收取一次费用。您可以随时取消。',
  'Use another card' => '使用另一张卡',
  'Your saved cards' => '您保存的卡片',
  'Installments' => '分期付款',
  'Single payment' => '单笔支付\', \'zh\']]',
  '%1$s installments × %2$s (total %3$s)' => '%1$s分期付款 ×%2$s(总计%3$s)',
  'Installment options appear after the card number.' => '分期付款选项出现在卡号后面。',
  'Please check the card number.' => '请检查卡号。',
  'Please write the name on the card.' => '请把名字写在卡上。',
  'Please check the expiry date.' => '请检查到期日期。',
  'Please check the security code (CVC).' => '请检查安全代码 (CVC)。',
  'Paid with 3D Secure through iyzico. Your bank may send you a code.' => '通过 iyzico 使用 3D Secure 付款。您的银行可能会向您发送一个代码。',
  'Test mode: use an iyzico test card, e.g. 5528 7900 0000 0008, 12/30, 123.' => '测试模式:使用 iyzico 测试卡,例如5528 7900 0000 0008, 12/30, 123.',
  'Fill in the test card' => '填写测试卡',
  'Test mode accepts only iyzico test cards. Use "Fill in the test card".' => '测试模式仅接受 iyzico 测试卡。使用“填写测试卡”。',
  'Card payments are not configured on this site. Please choose another payment method.' => '此网站未配置卡付款。请选择其他付款方式。',
  'The amount must be greater than zero.' => '金额必须大于零。',
  'This saved card cannot be used any more. Please enter the card.' => '这张保存的卡不能再使用。请输入卡。',
  'This installment option is not available for the card. Please choose another.' => '此分期付款选项不适用于该卡。请选择另一个。',
  'Card payment could not start: %1$s (card %2$s, %3$s).' => '卡付款无法开始:%1$s(卡%2$s、%3$s)。',
  'test mode' => '测试模式',
  'live' => '直播',
  'Card payment started: %1$s installments, %2$s charged by the bank.' => '卡付款开始:%1$s分期付款,%2$s由银行收取。',
  'iyzico 3D Secure: %s' => 'iyzico 3D 安全:%s',
  'The bank did not confirm the 3D Secure code. Please try again.' => '银行未确认 3D 安全代码。请重试。',
  'This card is not enrolled for 3D Secure. Please call your bank or use another card.' => '此卡未注册 3D Secure。请致电您的银行或使用其他卡。',
  'The bank could not check the card. Please try again or use another card.' => '银行无法检查该卡。请重试或使用另一张卡。',
  'iyzico: the payment was not completed (%s).' => 'iyzico: 付款未完成 (%s)。',
  'Default address' => '默认地址',
  'The page has expired. Please try again.' => '该页面已过期。请重试。',
  'Please fill in the name, address and city.' => '请填写姓名、地址和城市。',
  'Address deleted.' => '地址已删除。',
  'Default address changed.' => '默认地址已更改。',
  'Address book' => '通讯录',
  'Saved addresses are offered in a list at the checkout. The default one is filled in automatically.' => '结帐时会在列表中提供已保存的地址。默认值会自动填写。',
  'Delete this address?' => '删除该地址?',
  '+ Add a new address' => '+ 添加新地址',
  'Address name' => '地址名称',
  'e.g. Home, Office' => 'e.g.家庭、办公室',
  'Saved address' => '已保存的地址',
  'Write the new address below; it is saved to your address book with the order.' => '在下面写下新地址;它会与订单一起保存到您的地址簿中。',
  'Manage addresses' => '管理地址',
  'Keys are read from the iyzico WooCommerce plugin settings.' => '密钥是从 iyzico WooCommerce 插件设置中读取的。',
  'Keys are read from Donations › Settings › Payments › iyzico.' => '密钥从捐赠 › 设置 › 付款 › iyzico 中读取。',
  'No iyzico keys found. Enter them in the iyzico WooCommerce plugin or in Donations › Settings › Payments › iyzico.' => '未找到 iyzico 密钥。在 iyzico WooCommerce 插件或捐赠 › 设置 › 付款 › iyzico 中输入它们。',
  'Environment: sandbox (test).' => '环境:沙箱(测试)。',
  'Environment: live.' => '环境:现场。',
  'iyzico reported a payment (%s) that does not match this order (amount, currency or basket). Check it in the iyzico panel before doing anything.' => 'iyzico 报告了一笔付款 (%s) 与此订单(金额、货币或篮子)不匹配。在执行任何操作之前,请在 iyzico 面板中检查它。',
  'iyzico payment received: %1$s, payment id %2$s (%3$s).' => 'iyzico 收到付款:%1$s,付款 ID%2$s(%3$s)。',
  'Enter an amount to refund.' => '输入退款金额。',
  'This order has no iyzico transaction to refund.' => '此订单没有可退款的 iyzico 交易。',
  'The amount is more than what is left to refund at iyzico.' => '金额超过了 iyzico 剩余的退款金额。',
  'iyzico refused the refund: %s' => 'iyzico 拒绝退款:%s',
  'Refunded at iyzico: %1$s. %2$s' => '在 iyzico 退款:%1$s。%2$s',
  'Classic' => '经典',
  'One card: type tabs on top, the choices under them, the total at the bottom.' => '一张卡:在顶部键入选项卡,在其下方键入选项,在底部键入总计。',
  'A · Steps + summary' => 'A · 步骤 + 摘要',
  'Numbered steps on the left, a summary with the total and the button on the right.' => '左侧有编号的步骤,右侧有包含总计的摘要和按钮。',
  'B · Two panels' => 'B · 两个面板',
  'Types as a list on the left, the details on the right; a dark total bar.' => '在左侧输入列表,在右侧输入详细信息;黑色总栏。',
  'C · Picture cards' => 'C · 图卡',
  'Large cards with the type picture or icon; the details open below.' => '带有类型图片或图标的大卡片;详细信息如下。',
  'All options one under the other.' => '所有选项一个接一个。',
  'Drop-down' => '下拉菜单',
  'One row: the option in a drop-down menu and the quantity beside it.' => '一行:下拉菜单中的选项及其旁边的数量。',
  'List, then one row' => '列表,然后一行',
  'The list first; after a pick it folds into one row (drop-down + quantity) and the rest of the form opens.' => '列表优先;选择后,它会折叠成一行(下拉菜单+数量),然后打开表单的其余部分。',
  'The look of WooCommerce and the theme.' => 'WooCommerce 的外观和主题。',
  'Methods as cards with icons; the details of the picked one below.' => '方法如带有图标的卡片;下面是所选择的详细信息。',
  'Rows one under the other; the picked row opens.' => '一排排在另一排下面;选定的行将打开。',
  'One row of tab buttons; the details of the picked one below.' => '一排选项卡按钮;下面是所选择的详细信息。',
  'Options and amount' => '选项和金额',
  'On whose behalf' => '代表谁',
  'Certificate design' => '证书设计',
  'Repeat every month' => '每月重复一次',
  'How the "Donation options" block looks on the site. Prices, options and names are set under Donation types.' => '“捐赠选项”块在网站上的外观。价格、选项和名称在捐赠类型下设置。',
  'View the page' => '查看页面',
  'Heading over the types' => '类型标题',
  'Shown in the A and C layouts.' => '显示在 A 和 C 布局中。',
  'Heading over the options' => '查看选项',
  'Choose an option' => '选择一个选项',
  'How the options are shown' => '选项如何显示',
  'Order of the sections' => '各部分的顺序',
  'The type choice is always first and the total always last. Sections a type does not use are skipped.' => 'The type choice is always first and the total always last.类型不使用的部分将被跳过。',
  'Ask a phone number for every share (types with a proxy). The video or certificate of that share can be sent there too.' => '询问每个共享的电话号码(使用代理的类型)。该共享的视频或证书也可以发送到那里。',
  'Payment options at the checkout' => '结帐时的付款选项',
  'How card, PayPal, bank transfer and the other methods are shown. The methods themselves are turned on under WooCommerce › Settings › Payments.' => '如何显示卡、PayPal、银行转账和其他方式。这些方法本身在 WooCommerce › 设置 › 付款下打开。',
  'Colours and corners' => '颜色和角',
  'Used by the form and the payment options. Empty fields follow the theme.' => '由表单和付款选项使用。空字段遵循主题。',
  'Corner radius (px)' => '圆角半径 (px)',
  '0 = square, 4 = plain corporate, 16 = round.' => '0 = 方形,4 = 普通公司,16 = 圆形。',
  'Transaction fee' => '交易费用',
  'Donors can choose to also pay the fee of the payment method, so the whole donation reaches you. The fee is added at the checkout for the method they pick.' => '捐赠者可以选择同时支付付款方式的费用,以便全部捐赠到达您的手中。费用会在结帐时根据他们选择的方法添加。',
  'Show "I will cover the transaction fee" on the donation form' => '在捐款表格上注明“我将支付交易费”',
  'Ticked by default' => '默认勾选',
  'Fixed' => '已修复',
  'Empty or 0 = no fee for that method (for example bank transfer). Fee = donation × % + fixed.' => '空或 0 = 该方法不收取任何费用(例如银行转账)。费用=捐款×%+固定金额。',
  'Please choose what you would like to donate for.' => '请选择您想要捐赠的项目。',
  'This option cannot be donated in %s. Please choose another currency.' => '此选项无法在%s中捐赠。请选择其他货币。',
  'This option cannot be donated online at the moment.' => '此选项目前无法在线捐赠。',
  'The number must be between 1 and %s.' => '数字必须介于 1 和%s之间。',
  'The amount must be at least %s.' => '金额必须至少为%s。',
  'For this amount please get in touch with us.' => '对于此金额,请与我们联系。',
  'Please choose an option.' => '请选择一个选项。',
  'Printed certificates are not available yet. Please choose the online certificate.' => '打印证书尚不可用。请选择在线证书。',
  'Please write the postal address for the printed certificate.' => '请填写打印证书的邮寄地址。',
  'Please write the name of the person you are donating for.' => '请写下您要为其捐款的人的姓名。',
  'This donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.' => '此捐赠需要代理 (vekâlet) 同意,但尚未设置。请联系站点管理员。',
  'The proxy (vekâlet) text has been updated. Please read it again and accept it.' => '代理 (vekâlet) 文本已更新。请再次阅读并接受。',
  'Please write at most %s name (one per share).' . chr(0) . 'Please write at most %s names (one per share).' => '请最多写入%s名称(每股一个)。',
  'The phone number does not look right. Example: 0532 123 45 67' => '电话号码看起来不正确。示例: 0532 123 45 67',
  'The e-mail address does not look right.' => '电子邮件地址看起来不正确。',
  'This cause does not take monthly donations.' => '该事业不需要每月捐款。',
  'Monthly donations are not available at the moment.' => '目前无法提供每月捐款。',
  'Donations in %s cannot be paid here at the moment.' => '目前无法在%s中支付捐款。',
  'The donation product could not be found.' => '找不到捐赠产品。',
  'It could not be added to the cart.' => '无法将其添加到购物车。',
  'A donation in your cart cannot be paid in %s and was removed.' => '您购物车中的捐款无法在%s中支付,已被删除。',
  'A donation in your cart is no longer available and was removed.' => '您购物车中的捐赠不再可用,已被删除。',
  'Printed certificates can only be paid in the store currency; your certificate will be sent online.' => '打印的凭证只能以商店货币支付;您的证书将在线发送。',
  'Products in your cart can only be paid in %1$s. <a href="%2$s">Switch to %1$s</a>' => '您购物车中的产品只能通过%1$s付款。<a href="%2$s">切换到%1$s</a>',
  'Printed certificate delivery' => '打印证书交付',
  'Repeats' => '重复',
  'Names (one per share)' => '名称(每股一个)',
  'Design' => '设计',
  'Name on the certificate' => '证书上的名称',
  'Sent to' => '发送至',
  'copy to me' => '复制给我',
  'Postal address' => '邮寄地址',
  'accepted (text version %s)' => '已接受(文本版本%s)',
  'Online + printed' => '在线 + 打印',
  '%s Sapling Donation' => '%s树苗捐赠',
  'Certificate no' => '证书编号',
  'The certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).' => '无法制作证书:找不到 Flux 证书模板(捐赠 > 设置 > WooCommerce)。',
  'The certificate could not be made: %s' => '无法制作证书:%s',
  'Not sent yet.' => '尚未发送。',
  'Certificate made: %1$s (%2$s). %3$s' => '制作的证书:%1$s(%2$s)。%3$s',
  'Certificates made again (%d); the old ones were revoked.' => '再次制作证书(%d);旧的已被撤销。',
  'No delivery channel is chosen.' => '未选择传送渠道。',
  'Queued: %s.' => '排队:%s。',
  'Copy to the donor: %s.' => '复制到捐赠者:%s。',
  'The preview could not be drawn. You can open it with "View certificate".' => '无法绘制预览。您可以使用“查看证书”打开它。',
  'Your certificate is ready' . chr(0) . 'Your certificates are ready' => '您的证书已准备好',
  'No: %s' => '否:%s',
  'View certificate' => '查看证书',
  'Your certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.' => '正在准备您的证书。几分钟后将通过 WhatsApp 和电子邮件发送;您还可以刷新此页面来查看它。',
  'This certificate design cannot be chosen any more. Please pick another one.' => '此证书设计无法再选择。请选择另一个。',
  'Please fill in "%s" for the certificate.' => '请填写“%s”作为证书。',
  'Pick the design of your certificate. The donation amount does not change.' => '选择您的证书的设计。捐赠金额不变。',
  '"%s" was paid once: the card was not stored, so it will not repeat monthly.' => '“%s”已支付一次:该卡未存储,因此每月不会重复。',
  '"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.' => '“%1$s”每月重复一次(定期捐赠#%2$d);该卡存储在 iyzico。',
  'Card (iyzico), monthly' => '卡 (iyzico),每月',
  'Monthly renewal of recurring donation #%1$d (first order #%2$s).' => '每月续订定期捐款 #%1$d(第一笔订单 #%2$s)。',
  'Monthly charge accepted by iyzico: %1$s, payment id %2$s.' => 'iyzico 接受的每月费用:%1$s,付款 ID%2$s。',
  'Monthly charge failed after the last attempt: %s' => '最后一次尝试后每月充电失败:%s',
  'Monthly charge failed, it will be retried: %s' => '月费失败,将重试:%s',
  'Flux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.' => 'Flux Donate 始终使用 EsnekPOS 的安全支付页面;需要时银行会要求提供 3D Secure。',
  'Flux Donate' => '通量捐赠',
  'Flux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\'s developer page.' => 'Flux Donate 运行此付款方式:经典和块结帐、无购物车的付款链接,并且在订单标记为已付款之前,每笔付款均通过服务器的 EsnekPOS 进行确认。要进行测试,请输入商家 TEST1234 以及来自 EsnekPOS 开发者页面的测试商家密钥。',
  'Donation #%d' => '捐赠 #%d',
  'EsnekPOS did not answer (HTTP %d).' => 'EsnekPOS 未应答 (HTTP%d)。',
  'EsnekPOS payment could not start: %s' => 'EsnekPOS 付款无法开始:%s',
  'EsnekPOS payment could not start: %1$s (%2$s).' => 'EsnekPOS 付款无法开始:%1$s(%2$s)。',
  'The payment is being checked. Please wait a moment and refresh the page.' => '正在检查付款。请稍等片刻并刷新页面。',
  'EsnekPOS payment could not be checked: %s' => '无法检查 EsnekPOS 付款:%s',
  'The payment could not be verified yet. If money was taken from your card, please contact us before trying again.' => '尚未验证付款。如果您的卡上的钱被提取,请在重试之前联系我们。',
  'EsnekPOS payment received: reference %1$s, %2$s installment(s), %3$s charged.' => '已收到 EsnekPOS 付款:参考%1$s、%2$s分期付款、已收取%3$s。',
  'EsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.' => 'EsnekPOS 报告的付款 (%s) 与此订单(金额或参考)不匹配。在执行任何操作之前,请在 EsnekPOS 面板中检查它。',
  'EsnekPOS return said success but EsnekPOS did not confirm the payment: %s' => 'EsnekPOS 返回表示成功,但 EsnekPOS 未确认付款:%s',
  'EsnekPOS: the payment was not completed (%s).' => 'EsnekPOS: 付款未完成 (%s)。',
  'Test mode (merchant TEST1234).' => '测试模式(商家 TEST1234)。',
  'Flux Donate sends the order lines, no cart needed.' => 'Flux Donate 发送订单行,无需购物车。',
  'Flux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.' => 'Flux Donate 在订单标记为已付款之前询问 EsnekPOS (ProcessQuery)。',
  'On EsnekPOS\'s payment page, as set in the EsnekPOS panel.' => '在 EsnekPOS 的支付页面上,按照 EsnekPOS 面板中的设置。',
  'Refund in the EsnekPOS panel, then mark the order refunded.' => '在 EsnekPOS 面板中退款,然后将订单标记为已退款。',
  'Donation of %1$s sapling. %2$s plants it for you and sends an online certificate in your name. Pay by card or bank transfer.' . chr(0) . 'Donation of %1$s saplings. %2$s plants them for you and sends an online certificate in your name. Pay by card or bank transfer.' => '捐赠%1$s树苗。%2$s会为您种植它们,并以您的名义发送在线证书。通过卡或银行转账支付。',
  'Donation packages' => '捐赠包',
  'Donation > %s' => '捐赠 >%s',
  'I will also cover the transaction fee' => '我还将支付交易费',
  'So your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.' => '这样您的全部捐款就达到了目的。确切的费用取决于付款方式并在结账时显示。',
  'Transaction fee (covered by you)' => '交易费用(由您承担)',
  'Any trouble? Write to us on WhatsApp:' => '有什么麻烦吗?通过 WhatsApp 给我们写信:',
  'No badge' => '没有徽章',
  'Best value' => '最佳价值',
  'Most popular' => '最受欢迎',
  'Family pack' => '家庭包',
  'Hello {ad}, your donation of {tutar} is registered. IBAN: {iban} Reference: {aciklama} Upload your receipt: {link}' => '您好{ad},您的{tutar}捐赠已登记。 IBAN:{iban}参考号:{aciklama}上传收据:{link}',
  'Hello {ad} 🌱' . chr(10) . '' . chr(10) . 'Your donation of *{tutar}* is registered (No: {siparis}).' . chr(10) . '' . chr(10) . 'Bank transfer details:' . chr(10) . 'Recipient: {alici}' . chr(10) . 'IBAN: {iban}' . chr(10) . 'Reference: *{aciklama}*' . chr(10) . '' . chr(10) . 'After the transfer you can upload your receipt here:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . 'Thank you,' . chr(10) . '{site}' => '您好{ad}🌱' . chr(10) . '' . chr(10) . '您的 *{tutar}* 捐赠已登记(编号:{siparis})。' . chr(10) . '' . chr(10) . '银行转帐详细信息:' . chr(10) . '收款人:{alici}' . chr(10) . 'IBAN:{iban}' . chr(10) . '参考:*{aciklama}*' . chr(10) . '' . chr(10) . '转帐后,您可以在此处上传您的收据:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . '谢谢你,' . chr(10) . '{site}',
  'Pending transfer notification sent: %s.' => '已发送待处理传输通知:%s。',
  'WooCommerce checks' => 'WooCommerce 检查',
  'Version %1$s is active. Flux Donate was checked up to %2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.' => '版本%1$s处于活动状态。 Flux Donate 已检查至%2$s;它仅使用稳定的公共 WooCommerce 功能,但会在大型 WooCommerce 更新后测试捐赠。',
  'Active, version %s. Donations are paid through the WooCommerce cart and checkout.' => '活动,版本%s。捐款通过 WooCommerce 购物车和结帐支付。',
  'One-time card payments are taken by %s; iyzico is not shown at the checkout.' => '一次性卡付款由%s进行;结帐时不会显示 iyzico。',
  'One-time card payments are taken by the official iyzico WooCommerce plugin.' => '一次性卡付款由官方 iyzico WooCommerce 插件进行。',
  'Card payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).' => '卡付款在结帐时使用我们自己的卡字段(iyzico 3D Secure、分期付款、保存的卡)。',
  'One-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).' => '一次性卡付款由 Flux Donate iyzico 进行(未启用官方 iyzico 插件)。',
  'Card payments are taken by: %s.' => '银行卡付款方式为:%s。',
  'No card method is enabled; donations can only be paid by bank transfer.' => '未启用任何卡方法;捐款只能通过银行转账的方式支付。',
  'Card payments (WooCommerce)' => '卡付款 (WooCommerce)',
  'Monthly donations' => '每月捐款',
  'Flux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.' => 'Flux Donate iyzico 在首次付款时存储该卡;每月都会开立续订订单并收取费用。',
  'Monthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.' => '每月捐赠已关闭:在 WooCommerce › 设置 › 付款中启用“卡 (iyzico) - Flux Donate”并输入 iyzico 密钥。',
  'Bank transfer (donations)' => '银行转账(捐款)',
  'No IBAN entered.' => '未输入 IBAN。',
  'The payment method is disabled.' => '付款方式已禁用。',
  'Bank transfer settings' => '银行转帐设置',
  'Two bank transfer methods' => '两种银行转帐方式',
  'WooCommerce\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".' => 'WooCommerce 自己的“直接银行转账”在捐赠银行转账旁边启用。捐赠者会看到两个类似的选择,并且收据上传仅适用于捐赠的一项;禁用“直接银行转帐”。',
  'The shop currency is %1$s; these types use another currency and are charged in %1$s at the same number: %2$s' => '商店货币为%1$s; these types use another currency and are charged in%1$sat the same number:%2$s',
  'WooCommerce settings' => 'WooCommerce 设置',
  'Donation types and the shop use %s.' => '捐赠类型和商店使用%s。',
  'Donation products' => '捐赠产品',
  'These types get their hidden WooCommerce product the first time they are donated to or saved: %s' => '这些类型在第一次捐赠或保存时获得隐藏的 WooCommerce 产品:%s',
  '%d active type has its hidden WooCommerce product.' . chr(0) . '%d active types have their hidden WooCommerce products.' => '%d活动类型具有隐藏的 WooCommerce 产品。',
  'No page with the donation options block is selected.' => '未选择带有捐赠选项块的页面。',
  'Other payment plugins' => '其他支付插件',
  'Check these on the donation checkout: %s. Details: Donations › Settings › WooCommerce › Payment methods.' => '在捐赠结帐处检查这些:%s。详细信息:捐赠 › 设置 › WooCommerce › 付款方式。',
  'Enabled and shown on the donation checkout: %s.' => '已启用并显示在捐赠结帐上:%s。',
  'Certificates after payment' => '付款后证书',
  'Flux Certificates makes the certificates of paid donation lines.' => 'Flux Certificates 制作付费捐款线的证书。',
  'Flux Certificates has no active template.' => 'Flux 证书没有活动模板。',
  'Product XML' => '产品 XML',
  '%1$s lists %2$d donation packages (Google Merchant format, e.g. for iyzico).' => '%1$s列出%2$d捐赠包(Google Merchant 格式,例如 iyzico)。',
  'Payment forms on the checkout' => '结帐时的付款表格',
  'Donation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.' => '捐赠表格将他们的选择发送到 WooCommerce 购物车;订单支付后,“付款已完成”自动化运行。',
  'Flux Forms %s is active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.' => '通量形式%s处于活动状态。表单在结账时付款,但其“付款已完成”自动化功能需要 Flux Forms 2.1.0 或更高版本。',
  'Donation e-mails' => '捐赠电子邮件',
  'Sent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.' => '通过 Flux 邮件发送;可以在那里编辑模板(“Flux Donate”组)。 WooCommerce 订单电子邮件保留在 WooCommerce › 设置 › 电子邮件中。',
  'E-mail templates' => '电子邮件模板',
  'Flux Mail is not active: the donation e-mails are sent as plain text with their default wording.' => 'Flux 邮件未激活:捐赠电子邮件以纯文本形式使用默认措辞发送。',
  'Bank transfer (donation)' => '银行转账(捐赠)',
  'The donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.' => '捐赠者使用特定于订单的参考号转账,并将收据上传到网站上。确认付款后将颁发证书。',
  'Take donations by bank transfer' => '通过银行转账接受捐款',
  'Empty = the holder of the bank account below or, without an IBAN here, of WooCommerce\'s "Direct bank transfer" account (else the theme settings).' => '空 = 以下银行帐户的持有人,或者此处没有 IBAN 的 WooCommerce“直接银行转帐”帐户(否则主题设置)的持有人。',
  'The account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.' => '帐户随处可见(捐赠页面、结帐、呼叫中心)。空 = WooCommerce 的“直接银行转账”的第一个帐户,其他为主题设置;收件人和银行也来自该帐户。',
  'What the donor writes in the transfer description. Placeholders: {tur} (sapling donation / donation), {kod} (prefix + order no), {siparis}, {ad}. Empty: {tur} {kod} {ad}' => '捐赠者在转账说明中所写的内容。占位符:{tur}(树苗捐赠/捐赠)、{kod}(前缀+订单号)、{siparis}、{ad}。空:{tur}{kod}{ad}',
  'Bank transfer pre-registration: waiting for the payment.' => '银行转账预登记:等待付款。',
  'Card (iyzico) - Flux Donate' => '卡片 (iyzico) - 通量捐赠',
  'Card payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.' => 'iyzico 安全页面上的卡付款。每月捐款所需(该卡由 iyzico 存储,每月收费);当官方 iyzico 插件未激活时,也可用于一次性捐赠。',
  'Card payments through Flux Donate (iyzico)' => '通过 Flux Donate (iyzico) 进行卡支付',
  'Credit / debit card (iyzico)' => '信用卡/借记卡 (iyzico)',
  'You will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.' => '您将在 iyzico 的安全页面上付款。对于每月捐款,您的卡由 iyzico 存储并每月收取一次费用;您可以随时取消。',
  'Donation options' => '捐赠选项',
  'Sapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.' => '树苗包裹、原因和无偿捐赠;添加到购物车并通过 WooCommerce 付款。',
  'Tab shown first' => '首先显示选项卡',
  'The first one' => '第一个',
  'None chosen = the types marked "Show in the Donation options block".' => '未选择 = 标记为“在捐赠选项块中显示”的类型。',
  'Prices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.' => '价格和选项:捐赠 › 捐赠类型。证书和购物车:捐赠 › 设置 › WooCommerce。',
  'Could not copy, please select it by hand.' => '无法复制,请手动选择。',
  'We have your receipt. Thank you! We will let you know once the payment is confirmed.' => '我们有您的收据。谢谢你!付款确认后我们会通知您。',
  'Receipt under review' => '收据正在审核中',
  'Please write a WhatsApp number or an e-mail address (at least one).' => '请写下 WhatsApp 号码或电子邮件地址(至少一个)。',
  'Please enter a valid e-mail address.' => '请输入有效的电子邮件地址。',
  'Please enter a valid phone number.' => '请输入有效的电话号码。',
  'Please write at most one name per share.' => '每个共享最多只能写一个名称。',
  '/ month' => '/月',
  '(up to %s)' => '(直到%s)',
  '%s Sapling' . chr(0) . '%s Saplings' => '%s树苗',
  'Who is this donation for?' => '这笔捐款是给谁的?',
  'For myself' => '为了我自己',
  'On behalf of someone else' => '代表其他人',
  'Their name' => '他们的名字',
  'e.g. Ayşe Yılmaz or the Yılmaz family' => 'e.g. Ayşe Yılmaz 或 Yılmaz 家族',
  'Optional. If you leave it empty, the name from the checkout is used.' => '可选。如果将其留空,则使用结账时的名称。',
  'Written on the certificate and the donation record.' => '写在证书和捐赠记录上。',
  'Written on the donation record.' => '写在捐款记录上。',
  'Where should the certificate go?' => '证书应该去哪里?',
  'Empty fields use the phone and e-mail of your account or the checkout.' => '空白字段使用您帐户或结帐时的电话和电子邮件。',
  'Their phone and e-mail. Empty fields use yours.' => '他们的电话和电子邮件。空字段使用您的。',
  'Send me a copy too' => '也给我发一份',
  'Online certificate' => '在线证书',
  'Sent by WhatsApp and e-mail once the payment is confirmed, ready to download.' => '付款确认后通过 WhatsApp 和电子邮件发送,可供下载。',
  'Online + printed certificate' => '在线+打印证书',
  'A printed certificate is also posted to your address.' => '打印的证书也会邮寄到您的地址。',
  'Postal address for the printed certificate' => '打印证书的邮寄地址',
  'Name, full address, district / city, phone' => '姓名、详细地址、区/市、电话',
  'By card, stop any time.' => '刷卡,随时停车。',
  'Your donation was added to the cart.' => '您的捐款已添加到购物车。',
  'Go to cart' => '转到购物车',
  'Your donation' => '您的捐款',
  'from %s' => '来自%s',
  'Payments are taken securely by iyzico.' => 'iyzico 安全地进行付款。',
  'Pay safely by card or bank transfer.' => '通过卡或银行转帐安全付款。',
  'Your card details are never stored on our site.' => '您的银行卡详细信息绝不会存储在我们的网站上。',
  'How many saplings would you like to donate?' => '您想捐赠多少棵树苗?',
  'Another amount' => '另一笔金额',
  'Or write another amount' => '或者写另一个金额',
  'At least %s' => '至少%s',
  'On whose behalf?' => '代表谁?',
  'Given in your name, as you write it at the checkout.' => '以您在结账时所写的姓名提供。',
  'Shares without a name are given in the name from the checkout. With a phone number we can also send that person the news on WhatsApp.' => '没有名称的股票以结帐时的名称给出。通过电话号码,我们还可以通过 WhatsApp 向该人发送新闻。',
  'Shares without a name are given in the name from the checkout.' => '没有名称的共享以结账时的名称给出。',
  'Read the proxy (vekâlet) text (version %s)' => '读取代理 (vekâlet) 文本(版本%s)',
  'I give my proxy (vekâlet) for the sacrifice according to this text.' => '我根据本文给出我的代理人(vekâlet)作为牺牲。',
  'Share %s' => '共享%s',
  'Apply to all' => '应用于所有',
  'e.g. Ali Yılmaz' => 'e.g.阿里·耶尔马兹',
  'No receipt is expected for this donation.' => '预计此次捐赠不会有收据。',
  'At most 5 receipts can be uploaded for a donation.' => '一次捐赠最多可上传 5 张收据。',
  'The donor uploaded a receipt: %1$s (%2$s). Check the payment and confirm it.' => '捐赠者上传了收据:%1$s(%2$s)。检查付款并确认。',
  'the site' => '网站',
  'Warning: this receipt was uploaded before (%1$d time, via %2$s). Check it before confirming the payment.' . chr(0) . 'Warning: this receipt was uploaded before (%1$d times, via %2$s). Check it before confirming the payment.' => '警告:此收据之前已上传(%1$d次,通过%2$s)。确认付款前请检查一下。',
  'Earlier donation: #%d.' => '之前的捐赠:#%d。',
  'WooCommerce checkout' => 'WooCommerce 结帐',
  'You will choose how to pay (card or bank transfer) on the next page.' => '您将在下一页选择付款方式(卡或银行转帐)。',
  'Monthly donations are paid by card; the card is stored by iyzico and charged once a month.' => '每月捐款通过卡支付;该卡由 iyzico 存储,每月收费一次。',
  'This form is not linked to a donation type. Please contact the site administrator.' => '此表格未链接到捐赠类型。请联系站点管理员。',
  'The donation type of this form was not found.' => '找不到此表单的捐赠类型。',
  'The amount could not be calculated. Please review your choices and try again.' => '金额无法计算。请检查您的选择并重试。',
  'You have no pending donations.' => '您没有待处理的捐款。',
  'Donations made by bank transfer appear here until the payment is confirmed.' => '通过银行转帐进行的捐款将显示在此处,直至付款得到确认。',
  'Your bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.' => '您的银行转帐捐款。如果您已付款,请上传收据;您的证书一经确认就会发送。',
  'Donation #%s' => '捐赠 #%s',
  '%s donation is awaiting payment' . chr(0) . '%s donations are awaiting payment' => '%s捐款正在等待付款',
  'If you have made the transfer, upload your receipt.' => '如果您已进行转账,请上传收据。',
  'Please write your e-mail or phone number (at least one).' => '请写下您的电子邮件或电话号码(至少一个)。',
  'Write at least one. We send your receipt and certificate there.' => '至少写一个。我们会将您的收据和证书发送到那里。',
  'Continue to payment' => '继续付款',
  'I have read and accept the %1$sprivacy policy%2$s and the %3$sdonation agreement%4$s.' => '我已阅读并接受%1$s隐私政策%2$s和%3$s捐赠协议%4$s。',
  'Make payment' => '付款',
  'Please read and accept the terms to continue.' => '请阅读并接受条款以继续。',
  'Donation terms' => '捐赠条款',
  'Privacy policy' => '隐私政策',
  'These terms apply to donations made on this site to %s.' => '这些条款适用于在本网站上向%s进行的捐赠。',
  'A donation is a gift without anything in return. It is used for the purpose chosen on the donation form (for example sapling planting). When a purpose is fully funded, the association may use the donation for a similar purpose.' => '捐赠是一种礼物,没有任何回报。它用于捐赠表格上选择的目的(例如树苗种植)。当某个目的得到全额资助时,协会可以将捐款用于类似目的。',
  'Card payments are processed by the licensed payment institution iyzico with 3D Secure. Card details are not stored on this site. For bank transfers, the donation is confirmed when the money reaches the association account.' => '卡支付由持牌支付机构 iyzico 和 3D Secure 处理。该网站不存储银行卡详细信息。对于银行转账,当资金到达协会帐户时,捐款即被确认。',
  'A monthly donation is charged to the same card every month until you cancel it. You can cancel it at any time from your account page or by writing to us.' => '每月捐款会每月从同一张卡中扣除,直到您取消为止。您可以随时从您的帐户页面或写信给我们取消它。',
  'The online certificate is sent to the e-mail address or phone number you give after the payment is confirmed. Please check the names you write on the certificate.' => '付款确认后,在线证书将发送至您提供的电子邮件地址或电话号码。请检查您写在证书上的姓名。',
  'Cancellation and refunds' => '取消和退款',
  'If a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.' => 'If a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.',
  'Your name and contact details are used to record the donation, send the receipt and certificate, and contact you about your donation. See the privacy policy for details.' => '您的姓名和联系方式将用于记录捐赠、发送收据和证书,并就捐赠事宜与您联系。有关详细信息,请参阅隐私政策。',
  'For any question about your donation, write to us on WhatsApp: %s' => '如果对您的捐赠有任何疑问,请通过 WhatsApp 给我们写信:%s',
  'For any question about your donation, write to us through the contact page.' => '如果对您的捐赠有任何疑问,请通过联系页面写信给我们。',
  '%s processes your personal data under the Turkish Personal Data Protection Law (KVKK).' => '%s根据土耳其个人数据保护法 (KVKK) 处理您的个人数据。',
  'What we collect' => '我们收集什么',
  'Name, e-mail address, phone number and the details of your donation. Card details are entered on the payment institution and are not stored by us.' => '姓名、电子邮件地址、电话号码和您的捐款详细信息。卡详细信息由支付机构输入,我们不会存储。',
  'To record donations, send receipts and certificates, meet legal obligations and answer your questions.' => '记录捐款、发送收据和证书、履行法律义务并回答您的问题。',
  'Your rights' => '您的权利',
  'You can ask what data we hold about you, have it corrected or deleted, by writing to us.' => '您可以写信给我们,询问我们持有您的哪些数据、更正或删除这些数据。',
  'Block checkout' => '阻止结帐',
  'No address' => '没有地址',
  'Server check' => '服务器检查',
  'Saved cards' => '已保存的卡片',
  'Refund from site' => '从网站退款',
  'Shown on a checkout page built with the Checkout block. The classic checkout ([woocommerce_checkout]) shows every method.' => '显示在使用结帐块构建的结帐页面上。经典结帐 ([woocommerce_checkout]) 显示每种方法。',
  'Pays an existing order from its payment link (call center, "pay again"), without a cart.' => '通过付款链接(呼叫中心,“再次付款”)支付现有订单,无需购物车。',
  'Works on our checkout that asks no address: Flux Donate fills the organisation\'s city and address in.' => '[[“适用于我们的结帐,无需询问地址:Flux Donate 填写组织的城市和地址。',
  'The payment is confirmed with the provider from the server before the order is marked paid.' => '在订单标记为已付款之前,先从服务器向提供商确认付款。',
  'The donor can pay in installments.' => '捐赠者可以分期付款。',
  'The donor can save a card for the next donation.' => '捐赠者可以保存一张卡片以供下次捐赠使用。',
  'The Refund button on the order sends the refund to the provider.' => '订单上的退款按钮将退款发送给提供商。',
  'Monthly donations charge a stored card every month. Only Flux Donate iyzico does this.' => '每月捐款每月从存储的卡中收取费用。只有 Flux Donate iyzico 可以执行此操作。',
  'Added by Flux Donate (the plugin has no block support).' => '由 Flux Donate 添加(该插件没有块支持)。',
  'Added by Flux Donate once the method is enabled.' => '启用该方法后,由 Flux Donate 添加。',
  'Turn on "Show other payment plugins on the checkout block".' => '开启“在结账栏显示其他支付插件”。',
  'The plugin shows its own card fields only on the classic checkout. Use the classic checkout page or ask the provider for block support.' => '该插件仅在经典结帐时显示其自己的卡字段。使用经典结账页面或向提供商请求阻止支持。',
  'Most plugins work; try a payment link once.' => '大多数插件都可以工作;尝试一次付款链接。',
  'Depends on the plugin; ask the provider.' => '取决于插件;询问提供商。',
  'If the provider offers it, on its payment page.' => '如果提供商提供,则在其付款页面上。',
  'Refund in the provider\'s panel, then mark the order refunded.' => '在提供商面板中退款,然后将订单标记为已退款。',
  'Confirmed by hand after the receipt.' => '收货后由专人确认。',
