  'Every WooCommerce payment plugin (virtual POS) works on the donation checkout: install it, enter its settings in WooCommerce › Settings › Payments and enable it. This table shows what each one can do here.' => '每个 WooCommerce 支付插件(虚拟 POS)都适用于捐赠结帐:安装它,在 WooCommerce › 设置 › 付款中输入其设置并启用它。下表显示了每个人可以执行的操作。',
