  'package' => '包',
  'packages' => '包',
  'In the trash' => '垃圾桶里',
  'Yearly' => '每年',
  'Test provider' => '测试提供者',
  '%1$s (%2$s)' => '%1$s(%2$s)',
  'Last test %1$s: %2$s' => '上次测试%1$s:%2$s',
  'WP-Cron is turned off in wp-config.php (DISABLE_WP_CRON). That is fine only if a server cron job calls %s every 5–15 minutes; without it recurring charges, retries and other scheduled tasks never run.' => 'WP-Cron 在 wp-config.php (DISABLE_WP_CRON) 中关闭。仅当服务器 cron 作业每 5-15 分钟调用%s时才可以;如果没有它,重复收费、重试和其他计划任务将永远不会运行。',
  'Scheduled tasks are running, so a server cron is in place.' => '计划任务正在运行,因此服务器 cron 已就位。',
  'Scheduled tasks have not run recently: check the server cron job (Hostinger: hPanel › Advanced › Cron Jobs).' => '计划任务最近没有运行:检查服务器 cron 作业(Hostinger:hPanel › 高级 › Cron 作业)。',
  'WP-Cron runs when someone visits the site. On a quiet site tasks can run late; for reliable recurring charges add a server cron job that calls wp-cron.php every 15 minutes and set DISABLE_WP_CRON to true (see KURULUM.md).' => 'WP-Cron 在有人访问该网站时运行。在安静的站点上,任务可能会延迟;为了获得可靠的定期费用,添加一个服务器 cron 作业,每 15 分钟调用一次 wp-cron.php 并将 DISABLE_WP_CRON 设置为 true(请参阅 KURULUM.md)。',
  'ALTERNATE_WP_CRON is on.' => 'ALTERNATE_WP_CRON 已打开。',
  'Flux Donate hourly task' => 'Flux 捐赠每小时任务',
  'Last run: %s. Recurring iyzico charges are checked every hour.' => '上次运行:%s。每小时检查一次 iyzico 重复费用。',
  'Not run yet; the first run is scheduled for %s.' => '尚未运行;第一次运行计划在%s进行。',
  'Last run: %s, more than 2 hours ago.' => '上次运行:%s,超过 2 小时前。',
  'It has never run.' => '它从未运行过。',
  'WP-Cron is off, so a server cron job must call wp-cron.php. It seems to be missing or failing.' => 'WP-Cron 已关闭,因此服务器 cron 作业必须调用 wp-cron.php。它似乎丢失或失败。',
  'WP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.' => 'WP-Cron 仅在访问时运行,可能会被主机或安全插件阻止。使用“测试 cron”或添加服务器 cron 作业。',
  'Next scheduled: %s.' => '下一个计划:%s。',
  'The task is not scheduled; it is added again on the next page load.' => '任务未安排;它会在下一个页面加载时再次添加。',
  'Test cron' => '测试 cron',
  'Overdue scheduled tasks' => '过期的计划任务',
  '%1$d task is more than 15 minutes late: %2$s.' . chr(0) . '%1$d tasks are more than 15 minutes late: %2$s.' => '%1$d任务迟到超过 15 分钟:%2$s。',
  'A few late tasks right after a quiet period are normal; many mean cron is not running.' => '安静期后出现一些迟到的任务是正常的;许多意味着 cron 没有运行。',
  'No task is late.' => '没有任务迟到。',
  'Cron test' => 'Cron 测试',
  'Not tested. The test asks this server to call wp-cron.php once, as WordPress does after a visit.' => '未测试。该测试要求该服务器调用 wp-cron.php 一次,就像 WordPress 在访问后所做的那样。',
  'Card payment provider' => '卡支付提供商',
  'No payment provider is available.' => '没有可用的付款提供商。',
  'Payment settings' => '付款设置',
  'Card payments are taken with %s.' => '通过%s进行卡付款。',
  '%s is the active provider but its keys are missing, so donation forms show "Online payment is unavailable".' => '%s是活动提供者,但其密钥丢失,因此捐赠表单显示“在线支付不可用”。',
  'Enter keys' => '输入密钥',
  'Keys are read from the iyzico Subscription plugin settings.' => '密钥是从 iyzico 订阅插件设置中读取的。',
  'Keys are entered in Donations › Payments › iyzico.' => '密钥在捐赠 › 付款 › iyzico 中输入。',
  'No iyzico API key and secret key found (neither in the iyzico WooCommerce plugin nor in Flux Donate).' => '未找到 iyzico API 密钥和秘密密钥(在 iyzico WooCommerce 插件和 Flux Donate 中均未找到)。',
  'Mode: sandbox (test). No real money is collected; switch to live keys before launch.' => '模式:沙箱(测试)。不收取真钱;在启动前切换到实时密钥。',
  'Mode: live. Real payments are taken.' => '模式:直播。进行真实付款。',
  'Use "Test connection" to check the keys with iyzico.' => '使用“测试连接”来检查 iyzico 的密钥。',
  'iyzico keys' => 'iyzico 键',
  'Paste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url): %s. Subscription notification URLs are not needed.' => '粘贴到 iyzico 面板中 › 商户通知 URL (şyeri Bildirimleri Url):%s。不需要订阅通知 URL。',
  'Last notification received: %s.' => '最后收到的通知:%s。',
  'No notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).' => '过去 30 天内没有收到任何通知(在地址保存在 iyzico 面板中并付款之前是正常的)。',
  'Notifications for WooCommerce orders are forwarded to the iyzico WooCommerce plugin.' => 'WooCommerce 订单的通知将转发到 iyzico WooCommerce 插件。',
  'iyzico notification URL' => 'iyzico 通知 URL',
  'Show addresses' => '显示地址',
  'Failed recurring charges' => '定期收费失败',
  '%d recurring donation stopped after its card was declined 3 times.' . chr(0) . '%d recurring donations stopped after their cards were declined 3 times.' => '%d的定期捐款在其卡被拒绝 3 次后停止。',
  'Stripe keys' => '条带键',
  'The Stripe publishable key and secret key are missing.' => 'Stripe 可发布密钥和秘密密钥丢失。',
  'Mode: live.' => '模式:实时。',
  'Mode: test (pk_test_). No real money is collected.' => '模式:测试(pk_test_)。没有收集到真正的钱。',
  'Webhook signing secret is set.' => 'Webhook 签名密钥已设置。',
  'Webhook signing secret is missing: refunds and renewals made in Stripe will not show up in Flux Donate.' => 'Webhook 签名密钥丢失:在 Stripe 中进行的退款和续订不会显示在 Flux Donate 中。',
  'Flux Forms is not active. Donation forms and card payments need it.' => 'Flux Forms 未激活。捐赠表格和银行卡付款需要它。',
  'Active, version %s.' => '活动,版本%s。',
  'Version %1$s is active; Flux Donate needs %2$s or later for payments and prices to work together.' => '版本%1$s已激活; Flux Donate 需要%2$s或更高版本才能使付款和价格协同工作。',
  'Active, version %s. Certificates can be sent after donations.' => '活动,版本%s。捐赠后可发送证书。',
  'Version %1$s is active; %2$s or later is recommended.' => '版本%1$s已激活;建议使用%2$s或更高版本。',
  'Not active. Donations are recorded, but no certificate is created or sent.' => '未激活。捐赠会被记录,但不会创建或发送任何证书。',
  'WooCommerce is older than %s. Flux Donate 2.0 takes donations through WooCommerce; update it.' => 'WooCommerce 早于%s。 Flux Donate 2.0 通过 WooCommerce 接受捐款;更新它。',
  'WooCommerce is not active. Flux Donate 2.0 takes donations through the WooCommerce cart and checkout; until it is active, only the older Flux Forms payment layer works.' => 'WooCommerce 未激活。 Flux Donate 2.0 通过 WooCommerce 购物车和结帐接受捐款;在其激活之前,只有较旧的 Flux Forms 支付层可以工作。',
  'The old Flux WooCommerce Bağış plugin is still active. Flux Donate 2.0 replaces it: deactivate and delete it, otherwise orders get two certificates and two messages.' => '旧的 Flux WooCommerce Bağış 插件仍然有效。 Flux Donate 2.0 取代了它:停用并删除它,否则订单将获得两个证书和两条消息。',
  'WooCommerce is active.' => 'WooCommerce 处于活动状态。',
  'The iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.' => 'iyzico WooCommerce 插件处于活动状态:它需要一次性卡付款,Flux Donate 会读取其 iyzico 密钥以进行每月捐款。',
  'The iyzico WooCommerce plugin is not active, but its saved keys are still used.' => 'iyzico WooCommerce 插件未激活,但仍使用其保存的密钥。',
  'The iyzico WooCommerce plugin is not active; Flux Donate uses its own iyzico keys.' => 'iyzico WooCommerce 插件未激活; Flux Donate 使用自己的 iyzico 密钥。',
  'The iyzico Subscription plugin is active; it renews WooCommerce subscriptions only. Flux Donate recurring donations use their own hourly task.' => 'iyzico 订阅插件已激活;它仅续订 WooCommerce 订阅。 Flux Donate 经常性捐赠使用自己的每小时任务。',
  'WooCommerce and iyzico plugins' => 'WooCommerce 和 iyzico 插件',
  'Open donation types' => '开放捐赠类型',
  '%d donation type is open and priced.' . chr(0) . '%d donation types are open and priced.' => '%d捐赠类型是开放且定价的。',
  'No donation type is open with a price (or free amount), so forms cannot take donations.' => '没有开放有价格(或免费金额)的捐赠类型,因此表格无法接受捐赠。',
  'Forms of open donation types' => '公开捐赠类型的形式',
  'No (existing) form is linked to: %s. Visitors cannot give to these types online.' => '没有(现有)表单链接到:%s。访问者无法在线向这些类型捐款。',
  'Every open donation type has a form.' => '每种公开捐赠类型都有一个表格。',
  'Default currency: %s.' => '默认货币:%s。',
  'iyzico is not set up for this currency (Donations › Payments › iyzico › currencies).' => 'iyzico 未设置此货币(捐赠 › 付款 › iyzico › 货币)。',
  'Bank accounts (transfer)' => '银行账户(转账)',
  '%d bank account is listed for bank transfer gifts.' . chr(0) . '%d bank accounts are listed for bank transfer gifts.' => '列出了%d银行账户用于银行转账礼物。',
  'No bank account is listed. They come from the theme (filter flxb_bank_accounts) and are used when recording bank transfer gifts.' => '未列出银行帐户。它们来自主题(过滤器 flxb_bank_accounts),并在记录银行转账礼物时使用。',
  'Receipts and e-mails show "%s".' => '收据和电子邮件显示“%s”。',
  'Not set; receipts and e-mails use the site title "%s".' => '未设置;收据和电子邮件使用网站标题“%s”。',
  'E-mail sending' => '电子邮件发送',
  'Not tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to %s.' => '未测试。捐赠者电子邮件(定期捐赠开始,卡被拒绝)通过 wp_mail 发送。该测试向%s发送一条消息。',
  'Send test e-mail' => '发送测试电子邮件',
  'Plain permalinks are in use. Payment callbacks still work through ?rest_route=, but some hosts and security plugins block that; choose "Post name".' => '普通固定链接正在使用中。付款回调仍然可以通过 ?rest_route= 工作,但某些主机和安全插件会阻止它;选择“帖子名称”。',
  'Pretty permalinks are on; REST callbacks use /wp-json/.' => '漂亮的永久链接已打开; REST 回调使用 /wp-json/。',
  'The site runs on HTTPS.' => '该网站在 HTTPS 上运行。',
  'Local test site without HTTPS. The live site must use HTTPS; payment providers refuse plain HTTP.' => '没有 HTTPS 的本地测试站点。直播站点必须使用HTTPS;支付提供商拒绝纯 HTTP。',
  'The site address is not HTTPS. Card payments and payment callbacks need HTTPS (Settings › General, and an SSL certificate from the host).' => '站点地址不是 HTTPS。卡付款和付款回调需要 HTTPS(设置 › 常规,以及来自主机的 SSL 证书)。',
  'WordPress security keys (salts)' => 'WordPress 安全密钥(盐)',
  'Missing or weak in wp-config.php: %s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.' => 'wp-config.php 中缺少或较弱:%s。保存的 iyzico 卡使用这些密钥进行加密;设置唯一值一次(https://api.wordpress.org/secret-key/1.1/salt/),之后不要更改它们,否则保存的卡将停止工作。',
  'Set in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.' => '在 wp-config.php 中设置。已保存的 iyzico 卡已使用它们加密:请勿更改它们,否则已保存的卡将停止工作。',
  'Up to date (%s).' => '最新 (%s)。',
  'Tables are at version %1$s, expected %2$s. Deactivate and activate Flux Donate to update them.' => '表的版本为%1$s,预计为%2$s。停用并激活 Flux Donate 来更新它们。',
  'No iyzico keys to test.' => '没有要测试的 iyzico 键。',
  'sandbox' => '沙箱',
  'Connected; iyzico accepted the keys (%s).' => '已连接; iyzico 接受了密钥 (%s)。',
  'iyzico refused the keys (%1$s): %2$s. Check that the keys belong to this environment.' => 'iyzico 拒绝了密钥 (%1$s):%2$s。检查密钥是否属于此环境。',
  'This server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.' => '此服务器无法访问其自己的 wp-cron.php (%s)。 WP-Cron无法从访问开始;添加服务器 cron 作业。',
  'wp-cron.php answered; WP-Cron can start.' => 'wp-cron.php 回答; WP-Cron 可以启动。',
  'wp-cron.php answered with HTTP %d (blocked by the host or a security plugin?). Add a server cron job.' => 'wp-cron.php 用 HTTP%d应答(被主机或安全插件阻止?)。添加服务器 cron 作业。',
  '[%s] Test e-mail from Flux Donate' => '[%s] 来自 Flux Donate 的测试电子邮件',
  'This is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.' => '这是来自捐赠 › 设置 › 系统检查的测试。如果您能阅读,则可以发送捐赠者电子邮件。',
  'Sent to %s. Check that it arrived (and not in spam).' => '发送到%s。检查它是否已到达(并且不在垃圾邮件中)。',
  'Sending failed: %s. Set up SMTP (e.g. an SMTP plugin with your mail account).' => '发送失败:%s。设置 SMTP (例如使用您的邮件帐户的 SMTP 插件)。',
  'Donations on WooCommerce: donation types and sapling packages sold as hidden products, cart and checkout (iyzico, bank transfer with receipt upload), monthly donations, online and printed certificates, donors, campaigns and a donation dashboard. Includes Flux WooCommerce Bağış.' => 'WooCommerce 上的捐赠:捐赠类型和作为隐藏产品出售的树苗包、购物车和结帐(iyzico、带有收据上传的银行转账)、每月捐赠、在线和打印证书、捐赠者、活动和捐赠仪表板。包括 Flux WooCommerce Bağış。',
  'Healing' => '康复',
  'Sacrifice (sheep or goat)' => '牺牲(绵羊或山羊)',
  'Reading...' => '正在读取...',
  'Importing... Keep this page open; if it closes, opening it again continues where it stopped.' => '正在导入...保持此页面打开;如果它关闭,则再次打开它会从停止处继续。',
  '%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived' => '%1$s捐赠 ·%2$s收到%1$s捐赠 ·%2$s收到',
  '%1$spaid gift ·%2$s%1$spaid gifts ·%2$s' => '%1$s付费礼物 ·%2$s%1$s付费礼物 ·%2$s',
  '%swaiting' . chr(0) . '%swaiting' => '%s等待',
  'Brings gifts in (office, organization)' => '将礼物带入(办公室、组织)',
  'brand color' => '品牌颜色',
  'Hex color such as #1F2937. Empty = the theme\'s primary colour.' => '十六进制颜色,例如#1F2937。空 = 主题的原色。',
  'Group donation types, e.g. Sacrifice, Ramadan, General. The key is stored on the types; a category that is in use cannot be removed.' => '团体捐赠类型,例如牺牲,斋月,将军。密钥存储在类型上;无法删除正在使用的类别。',
  'Importing...' => '正在导入...',
  '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' => '%d活动类型具有其隐藏的 WooCommerce 产品。%d活动类型具有隐藏的 WooCommerce 产品。',
  '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' => '%1$d任务迟到超过 15 分钟:%2$s。%1$d任务延迟超过 15 分钟:%2$s。',
  '%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived' . chr(0) . '%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived' => '%1$s捐赠 ·%2$s收到%1$s捐赠 ·%2$s收到',
  '%1$spaid gift ·%2$s%1$spaid gifts ·%2$s' . chr(0) . '%1$spaid gift ·%2$s%1$spaid gifts ·%2$s' => '%1$s付费礼物 ·%2$s%1$s付费礼物 ·%2$s',
  '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' . chr(0) . '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' => '%d活动类型具有其隐藏的 WooCommerce 产品。%d活动类型具有隐藏的 WooCommerce 产品。',
  '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' . chr(0) . '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' => '%1$d任务迟到超过 15 分钟:%2$s。%1$d任务延迟超过 15 分钟:%2$s。',
  '%srecurring donation could not be charged through iyzico after all attempts and is now past due. The donor was e-mailed.\\x00%srecurring donations could not be charged through iyzico after all attempts and are now past due. The donors were e-mailed.' => '%s经常性捐款在经过所有尝试后仍无法通过 iyzico 收取,现已过期。捐赠者已通过电子邮件发送。',
  '%sdonor\\x00%sdonors' => '%s捐助者',
  'and%smore\\x00and%smore' => '还有%s更多',
  'Import%srow\\x00Import%srows' => '导入%s行',
  '%sdonation moved to the trash.\\x00%sdonations moved to the trash.' => '%s捐款已移至垃圾桶。',
  '%sdonation restored.\\x00%sdonations restored.' => '%s捐款已恢复。',
  '%sdonation deleted permanently.\\x00%sdonations deleted permanently.' => '%s捐款已永久删除。',
  '%swaiting\\x00%swaiting' => '%s等待',
  '%dcertificate made. Check it, then press "Send the certificates".\\x00%dcertificates made. Check them, then press "Send the certificates".' => '%d证书已制作。检查它们,然后按“发送证书”。',
  '%ditem updated.\\x00%ditems updated.' => '%d项目已更新。',
  '%srecord\\x00%srecords' => '%s记录',
  '%dwithout a price\\x00%dwithout a price' => '%d无价格',
  'Used by%stype\\x00Used by%stypes' => '由%s类型使用',
  '%dfield\\x00%dfields' => '%d字段',
  '%srecurring donation\\x00%srecurring donations' => '%s经常性捐款',
  'Please write at most%sname (one per share).\\x00Please write at most%snames (one per share).' => '请最多写入%s名称(每个共享一个)。',
  'Your certificate is ready\\x00Your certificates are ready' => '您的证书已准备好',
  'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\\x00Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.' => '%1$s树苗捐赠。%2$s会为您种植它们,并以您的名义发送在线证书。通过卡或银行转帐付款。',
  '%sSapling\\x00%sSaplings' => '%s树苗',
  'Warning: this receipt was uploaded before (%1$dtime, via%2$s). Check it before confirming the payment.\\x00Warning: this receipt was uploaded before (%1$dtimes, via%2$s). Check it before confirming the payment.' => '警告:此收据之前已上传(%1$d次,通过%2$s)。请先检查后再确认付款。',
  '%sdonation is awaiting payment\\x00%sdonations are awaiting payment' => '%s捐款正在等待付款',
  'donor\\x00donors' => '捐助者',
  'day left\\x00days left' => '剩余天数',
  '%drecurring donation stopped after its card was declined 3 times.\\x00%drecurring donations stopped after their cards were declined 3 times.' => '%d经常性捐款在其卡被拒绝 3 次后停止。',
  '%ddonation type is open and priced.\\x00%ddonation types are open and priced.' => '%d捐赠类型开放并定价。',
  '%dbank account is listed for bank transfer gifts.\\x00%dbank accounts are listed for bank transfer gifts.' => '%d银行账户已列出用于银行转账礼物。',
