  'Your certificate is ready\\x00Your certificates are ready' . chr(0) . 'Your certificate is ready\\x00Your certificates are ready' => '您的证书已准备好',
  'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\\x00Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.' . chr(0) . 'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\\x00Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.' => '%1$s树苗捐赠。%2$s会为您种植它们,并以您的名义发送在线证书。通过卡或银行转帐付款。',
  '%sSapling\\x00%sSaplings' . chr(0) . '%sSapling\\x00%sSaplings' => '%s树苗',
