  'donor\\x00donors' . chr(0) . 'donor\\x00donors' => '捐助者',
  'day left\\x00days left' . chr(0) . 'day left\\x00days left' => '剩余天数',
  '%drecurring donation stopped after its card was declined 3 times.\\x00%drecurring donations stopped after their cards were declined 3 times.' . chr(0) . '%drecurring donation stopped after its card was declined 3 times.\\x00%drecurring donations stopped after their cards were declined 3 times.' => '%d经常性捐款在其卡被拒绝 3 次后停止。',
  '%ddonation type is open and priced.\\x00%ddonation types are open and priced.' . chr(0) . '%ddonation type is open and priced.\\x00%ddonation types are open and priced.' => '%d捐赠类型开放并定价。',
  '%dbank account is listed for bank transfer gifts.\\x00%dbank accounts are listed for bank transfer gifts.' . chr(0) . '%dbank account is listed for bank transfer gifts.\\x00%dbank accounts are listed for bank transfer gifts.' => '%d银行账户已列出用于银行转账礼物。',
  'Donation lookup code' => '捐赠查询验证码',
  'One-time code a donor enters on the "My donations" page to see their donations and certificates.' => '捐赠者在“我的捐赠”页面输入的一次性验证码，用于查看其捐赠和证书。',
  'Minutes the code is valid' => '验证码有效分钟数',
  'Lookup page' => '查询页面',
  '{kod} is your code to view your donations' => '{kod} 是您查看捐赠的验证码',
  'Your verification code' => '您的验证码',
  'Enter this code on the "My donations" page to see your donations and download your certificates:' => '在“我的捐赠”页面输入此验证码，即可查看您的捐赠并下载证书：',
  'The code is valid for {dakika} minutes. If you did not ask for it, you can ignore this e-mail.' => '验证码 {dakika} 分钟内有效。如果不是您本人申请，请忽略此邮件。',
  'Enter a valid e-mail address or phone number.' => '请输入有效的电子邮箱或电话号码。',
  'Codes cannot be sent by phone at the moment. Please use your e-mail address.' => '目前无法通过电话发送验证码，请使用电子邮箱。',
  'Codes cannot be sent by e-mail at the moment. Please use your phone number.' => '目前无法通过电子邮件发送验证码，请使用电话号码。',
  'Too many attempts. Please wait a few minutes and try again.' => '尝试次数过多，请等待几分钟后再试。',
  'The code could not be sent. Please try again later or contact us.' => '验证码发送失败，请稍后重试或联系我们。',
  'If there is a donation with this number, we have sent a 6-digit code to it on WhatsApp.' => '如果该号码有捐赠记录，我们已通过 WhatsApp 发送 6 位验证码。',
  'If there is a donation with this number, we have sent a 6-digit code to it by SMS.' => '如果该号码有捐赠记录，我们已通过短信发送 6 位验证码。',
  'If there is a donation with this address, we have sent a 6-digit code to it. Check your spam folder too.' => '如果该邮箱有捐赠记录，我们已发送 6 位验证码。请同时查看垃圾邮件文件夹。',
  '%1$s is your code to view your donations at %2$s. Valid for 10 minutes. Do not share it with anyone.' => '%1$s 是您在 %2$s 查看捐赠的验证码，10 分钟内有效。请勿告诉他人。',
