  'My donations and certificates' => '我的捐赠和证书',
  'Enter the e-mail address or phone number you used when donating. We will send you a one-time code; no account or password is needed.' => '请输入您捐赠时使用的电子邮箱或电话号码。我们会向您发送一次性验证码，无需账号或密码。',
  'E-mail address' => '电子邮箱',
  'name@example.com' => 'name@example.com',
  'Phone number' => '电话号码',
  'Your details are only used to find your donations.' => '您的信息仅用于查找您的捐赠。',
  'Donation lookup' => '捐赠查询',
  'Donors can see their donations with a code' => '捐赠者可以用验证码查看捐赠',
  'On the "My donations" page a donor enters their e-mail or phone, gets a one-time code and sees their donations and certificates without an account.' => '在“我的捐赠”页面，捐赠者输入邮箱或电话，收到一次性验证码后无需账号即可查看捐赠和证书。',
  'Send the code by' => '验证码发送方式',
  '(no connection yet: set it up in Flux Mail or Flux Chat)' => '（尚无连接：请在 Flux Mail 或 Flux Chat 中设置）',
  'Phone numbers get the code on WhatsApp first, then by SMS. E-mail codes are limited to 40 a day to stay under the hosting mail limit.' => '电话号码优先通过 WhatsApp 接收验证码，其次是短信。为不超过主机的邮件限额，邮件验证码每天最多 40 封。',
  'Page' => '页面',
  '— Find automatically —' => '— 自动查找 —',
  'The page shows the %s shortcode. Leave it on "Find automatically" or create the page with the button below.' => '页面显示 %s 短代码。可保留“自动查找”，或用下方按钮创建页面。',
  'Create the "My donations" page' => '创建“我的捐赠”页面',
  'The page' => '页面',
  'There is no page yet.' => '尚无页面。',
  'The code is valid for 10 minutes; after 5 wrong codes a new one is needed. One address can ask for 3 codes in 10 minutes. A verified visitor stays signed in for 30 minutes on this device.' => '验证码有效期 10 分钟；输错 5 次后需要新的验证码。同一地址 10 分钟内最多申请 3 次。已验证的访客在此设备上保持登录 30 分钟。',
  'The answer is the same whether or not there is a donation, so the page does not reveal who has donated.' => '无论是否有捐赠，回复都相同，因此页面不会泄露谁捐过款。',
  'Donation lookup page' => '捐赠查询页面',
  'Donors cannot look up their donations yet: no published page has the [flx_bagislarim] shortcode.' => '捐赠者还无法查询捐赠：没有已发布的页面包含 [flx_bagislarim] 短代码。',
  'Create the page' => '创建页面',
  'Donors can see their donations on %s with a code sent by e-mail or phone.' => '捐赠者可在 %s 通过邮件或电话收到的验证码查看捐赠。',
  'The page %s works with e-mail only: there is no WhatsApp or SMS connection for phone codes.' => '页面 %s 仅支持邮件：没有用于电话验证码的 WhatsApp 或短信连接。',
  'Receipt awaiting approval' => '凭证待审核',
  'Receipts awaiting approval' => '待审核的凭证',
  'The donor sent a receipt. Open it, check the bank account, then approve or reject.' => '捐赠者已发送转账凭证。请打开查看并核对银行账户，然后批准或拒绝。',
  'Show in the list' => '在列表中显示',
  'Review' => '查看',
  '%s more' . chr(0) . '%s more' => '另外 %s 个',
  'Paid gifts' => '已付款捐赠',
  'Open chat' => '打开聊天',
  'This gift has no referral.' => '此捐赠没有推荐人。',
